import { ConcreteItemOptions, Item } from './Item';

export interface GoldCoinOptions extends ConcreteItemOptions {
  readonly coinValue?: number;
}

/**
 * Stackable gold currency minted in an ancient kingdom.
 */
export class GoldCoin extends Item {
  public readonly coinValue: number;

  constructor(options: GoldCoinOptions) {
    super({
      id: options.id ?? `gold-coin-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Gold Coin',
      itemTypeId: 'gold_coin',
      itemType: 'misc',
      position: options.position,
      spriteKey: 'item_coin',
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.1,
      stackable: true,
      description:
        options.description ??
        'Gleaming gold coins minted by an ancient kingdom, prized by merchants and adventurers.',
    });
    this.coinValue = options.coinValue ?? 1;
  }

  public override cloneWithAmount(newAmount: number, newId?: string): GoldCoin {
    return new GoldCoin({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
      coinValue: this.coinValue,
    });
  }

  public override serializeCustomData(): Record<string, unknown> {
    return { coinValue: this.coinValue };
  }
}
