import { Actor } from '../entities/Actor';
import { SeededRNG } from '../SeededRNG';
import { registerPotionType } from './PotionCatalog';
import { PotionItem, PotionItemOptions, PotionQuaffEffectResult } from './PotionItem';

export const DEFAULT_PARALYZE_MIN_TURNS = 5;
export const DEFAULT_PARALYZE_MAX_TURNS = 10;

export interface ParalyzePotionOptions extends PotionItemOptions {
  readonly minTurns?: number;
  readonly maxTurns?: number;
}

/**
 * Potion of Paralyze (`麻痺藥水`): inflicts 5–10 turns of additive Paralysis on its target
 * when quaffed (+10 Satiety) or thrown.
 */
export class ParalyzePotion extends PotionItem {
  public readonly minTurns: number;
  public readonly maxTurns: number;

  constructor(options: ParalyzePotionOptions) {
    const minTurns = Math.max(1, Math.round(options.minTurns ?? DEFAULT_PARALYZE_MIN_TURNS));
    const maxTurns = Math.max(
      minTurns,
      Math.round(options.maxTurns ?? DEFAULT_PARALYZE_MAX_TURNS)
    );
    super({
      id: options.id ?? `paralyze-potion-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Potion of Paralyze',
      itemTypeId: 'paralyze_potion',
      position: options.position,
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.5,
      stackable: true,
      quaffSatietyBonus: options.quaffSatietyBonus,
      description:
        options.description ??
        `A numbing toxin that paralyzes its target for ${minTurns}–${maxTurns} turns when quaffed or thrown.`,
    });
    this.minTurns = minTurns;
    this.maxTurns = maxTurns;
  }

  public override getIdentifiedStatBadge(lang: 'en' | 'zh-TW'): string {
    return lang === 'zh-TW'
      ? `麻痺 ${this.minTurns}–${this.maxTurns}回合`
      : `Paralysis ${this.minTurns}–${this.maxTurns}t`;
  }

  public applyToTarget(target: Actor, rng?: SeededRNG): number {
    if (!target.isAlive()) {
      return 0;
    }
    const rolledTurns = rng
      ? rng.nextInt(this.minTurns, this.maxTurns)
      : Math.floor(Math.random() * (this.maxTurns - this.minTurns + 1)) + this.minTurns;
    target.addParalysisTurns(rolledTurns);
    return rolledTurns;
  }

  public override applyQuaffEffect(target: Actor, rng?: SeededRNG): PotionQuaffEffectResult {
    const added = this.applyToTarget(target, rng);
    return {
      kind: 'paralysis',
      observableEffect: added > 0,
      paralysisTurnsAdded: added,
    };
  }

  public override cloneWithAmount(newAmount: number, newId?: string): ParalyzePotion {
    const cloned = new ParalyzePotion({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
      minTurns: this.minTurns,
      maxTurns: this.maxTurns,
      quaffSatietyBonus: this.quaffSatietyBonus,
    });
    cloned.spriteKey = this.spriteKey;
    return cloned;
  }

  public override serializeCustomData(): Record<string, unknown> {
    return {
      minTurns: this.minTurns,
      maxTurns: this.maxTurns,
    };
  }
}

registerPotionType('paralyze_potion');
