import { isFoodItem } from './FoodItem';
import { Item } from './Item';
import { isMeatItem } from './MeatItem';
import { isPotionItem } from './PotionItem';

export type ItemLocationSource = 'inventory' | 'ground';
export type ItemGroupFilter = boolean | 'all' | 'edible' | 'potions';

export interface GroupedItemEntry {
  readonly groupKey: string;
  readonly source: ItemLocationSource;
  readonly representative: Item;
  readonly members: readonly Item[];
  readonly totalAmount: number;
  readonly totalWeight: number;
  readonly meatFreshness?: 'fresh' | 'rotten';
}

/**
 * Visually groups perishable `MeatItem` instances by `(source, itemTypeId, freshness)` so
 * Inventory ('i'), Pick Up ('g'), Drop ('d'), Food ('e'), and Potion ('q') tabs never spam separate rows,
 * while sorting underlying meat instances oldest-first (`createdAtTime` ascending) for FIFO consumption.
 * Non-meat items remain 1-to-1 with their Inventory/ground entries (where `stackable` items are already merged).
 */
export function groupItemsForDisplay(
  items: readonly Item[],
  currentTimeTicks: number,
  source: ItemLocationSource,
  filter: ItemGroupFilter = false
): GroupedItemEntry[] {
  const onlyEdible = filter === true || filter === 'edible';
  const onlyPotions = filter === 'potions';
  const groups: Array<{
    groupKey: string;
    source: ItemLocationSource;
    members: Item[];
    meatFreshness?: 'fresh' | 'rotten';
  }> = [];
  const meatGroupMap = new Map<
    string,
    {
      groupKey: string;
      source: ItemLocationSource;
      members: Item[];
      meatFreshness: 'fresh' | 'rotten';
    }
  >();

  for (const item of items) {
    if (onlyEdible && !isFoodItem(item)) {
      continue;
    }
    if (onlyPotions && !isPotionItem(item)) {
      continue;
    }

    if (isMeatItem(item)) {
      const freshness = item.getFreshness(currentTimeTicks);
      if (freshness === 'rotted_away') {
        continue;
      }
      item.syncSprite(currentTimeTicks);
      const groupKey = `${source}::${item.itemTypeId}::${freshness}`;
      const existing = meatGroupMap.get(groupKey);
      if (existing) {
        existing.members.push(item);
      } else {
        const created = {
          groupKey,
          source,
          members: [item],
          meatFreshness: freshness,
        };
        meatGroupMap.set(groupKey, created);
        groups.push(created);
      }
    } else {
      groups.push({
        groupKey: `${source}::id::${item.id}`,
        source,
        members: [item],
      });
    }
  }

  return groups.map((g) => {
    const sortedMembers =
      g.meatFreshness !== undefined
        ? [...g.members].sort((a, b) => {
            if (isMeatItem(a) && isMeatItem(b)) {
              return a.createdAtTime - b.createdAtTime;
            }
            return 0;
          })
        : g.members;

    const totalAmount = sortedMembers.reduce((sum, m) => sum + m.amount, 0);
    const totalWeight = Number(
      sortedMembers.reduce((sum, m) => sum + m.totalWeight, 0).toFixed(2)
    );

    return {
      groupKey: g.groupKey,
      source: g.source,
      representative: sortedMembers[0],
      members: sortedMembers,
      totalAmount,
      totalWeight,
      meatFreshness: g.meatFreshness,
    };
  });
}
