import { Point } from '../types';
import { Enemy } from './Enemy';

export interface DogOptions {
  readonly id: string;
  readonly position: Point;
}

/**
 * Dog (`惡犬`):
 * - Fast, keen-scented hound with a wide sensing range (8 tiles, matching player sight radius)
 *   and strong bite attacks.
 * - Cannot open or close doors (`canOpenDoors = false`).
 */
export class Dog extends Enemy {
  constructor(options: DogOptions) {
    super({
      id: options.id,
      archetypeId: 'enemy_dog',
      name: 'Dog',
      position: options.position,
      spriteKey: 'enemy_dog',
      sensingRange: 8,
      canOpenDoors: false,
      scoreValue: 120,
      dropsMeat: true,
      meatDropChance: 0.2,
      meatSatietyValue: 200,
      meatWeight: 2.5,
      attributes: {
        str: 11,
        con: 9,
        int: 3,
        wis: 5,
        agi: 14,
        luk: 8,
      },
    });
  }
}
