/**
 * Weighted factory for spawning an enemy instance:
 * - 50% Chick (`roll < 0.5`)
 * - 30% Rooster (`0.5 <= roll < 0.8`)
 * - 20% Dog (`roll >= 0.8`)
 */
export function createWeightedEnemy(id: string, position: Point, roll: number): Enemy {
  if (roll < 0.5) {
    return new Chick({ id, position });
  }
  if (roll < 0.8) {
    return new Rooster({ id, position });
  }
  return new Dog({ id, position });
}

export type EnemyDeserializer = (data: SerializedEnemy) => Enemy;
export type EnemySpawnFactory = (id: string, position: Point) => Enemy;

export interface WizardEnemyDescriptor {
  readonly archetypeId: string;
  readonly name: string;
  readonly spriteKey: string;
  readonly dropsMeat: boolean;
  readonly meatSatietyValue: number;
  readonly meatWeight: number;
  readonly create: EnemySpawnFactory;
}

const enemyDeserializerRegistry = new Map<string, EnemyDeserializer>();
const enemySpawnFactoryRegistry = new Map<string, EnemySpawnFactory>();

function buildStubSerializedEnemy(archetypeId: string, id: string, position: Point): SerializedEnemy {
  return {
    archetypeId,
    sensingRange: DEFAULT_ENEMY_SENSING_RANGE,
    canOpenDoors: false,
    scoreValue: DEFAULT_ENEMY_SCORE_VALUE,
    dropsMeat: true,
    meatDropChance: DEFAULT_ENEMY_MEAT_DROP_CHANCE,
    meatSatietyValue: DEFAULT_ENEMY_MEAT_SATIETY,
    meatWeight: DEFAULT_ENEMY_MEAT_WEIGHT,
    actorState: {
      id,
      name: archetypeId,
      spriteKey: archetypeId,
      position: { ...position },
      baseAttributes: { str: 10, con: 10, int: 10, wis: 10, agi: 10, luk: 10 },
      attributeBonuses: {},
      attributeXp: { str: 0, con: 0, int: 0, wis: 0, agi: 0, luk: 0 },
      growthConfig: { base: 10, slope: 6 },
      enableAttributeGrowth: false,
      hp: 10,
      mp: 0,
      sp: 100,
      sightRadius: 6,
      nextActionTime: 0,
      lastActionSpRegenMultiplier: 1,
      hpRegenAccumulator: 0,
      mpRegenAccumulator: 0,
      spRegenAccumulator: 0,
      inventory: [],
    },
  };
}

/**
 * Registers a concrete Enemy subclass deserializer under its `archetypeId`.
 * Future enemy classes only need to register here to gain full Save/Load support
 * AND automatic discovery in developer Wizard Mode.
 */
export function registerEnemyDeserializer(
  archetypeId: string,
  deserializer: EnemyDeserializer,
  spawnFactory?: EnemySpawnFactory
): void {
  enemyDeserializerRegistry.set(archetypeId, deserializer);
  enemySpawnFactoryRegistry.set(
    archetypeId,
    spawnFactory ?? ((id, position) => deserializer(buildStubSerializedEnemy(archetypeId, id, position)))
  );
}

/**
 * Returns auto-discovered metadata and spawn factories for all registered enemy archetypes.
 */
export function getRegisteredWizardEnemies(): WizardEnemyDescriptor[] {
  const entries: WizardEnemyDescriptor[] = [];
  for (const [archetypeId, create] of enemySpawnFactoryRegistry.entries()) {
    const sample = create(`sample_${archetypeId}`, { x: 0, y: 0 });
    entries.push({
      archetypeId,
      name: sample.name,
      spriteKey: sample.spriteKey,
      dropsMeat: sample.dropsMeat,
      meatSatietyValue: sample.meatSatietyValue,
      meatWeight: sample.meatWeight,
      create,
    });
  }
  return entries;
}

/**
 * Reconstructs a concrete `Enemy` subclass instance from `SerializedEnemy` data,
 * restoring its full Actor state (HP, MP, SP, timeline timestamp, inventory, etc.).
 */
export function deserializeEnemy(data: SerializedEnemy): Enemy {
  const factory = enemyDeserializerRegistry.get(data.archetypeId);
  let enemy: Enemy;
  if (factory) {
    enemy = factory(data);
  } else {
    enemy = new Enemy({
      id: data.actorState.id,
      archetypeId: data.archetypeId,
      name: data.actorState.name,
      position: { ...data.actorState.position },
      spriteKey: data.actorState.spriteKey,
      sensingRange: data.sensingRange,
      canOpenDoors: data.canOpenDoors,
      scoreValue: data.scoreValue,
      dropsMeat: data.dropsMeat,
      meatDropChance: data.meatDropChance,
      meatSatietyValue: data.meatSatietyValue,
      meatWeight: data.meatWeight,
      attributes: data.actorState.baseAttributes,
      stats: data.actorState.customStatOverrides,
    });
  }
  enemy.restoreActorSaveState(data.actorState);
  if (typeof data.alertedTurns === 'number' && data.alertedTurns > 0) {
    enemy.setAlertedTurns(data.alertedTurns);
  }
  return enemy;
}

// Register built-in concrete enemy classes
registerEnemyDeserializer(
  'enemy_chick',
  (d) => new Chick({ id: d.actorState.id, position: { ...d.actorState.position } }),
  (id, position) => new Chick({ id, position })
);

