import { Point } from '../types';
import { Enemy } from './Enemy';

export interface RoosterOptions {
  readonly id: string;
  readonly position: Point;
}

/**
 * Rooster (`公雞`):
 * - Aggressive mid-tier bird with medium sensing range (6 tiles), higher AGI/STR, and spur attacks.
 * - Cannot open or close doors (`canOpenDoors = false`).
 */
export class Rooster extends Enemy {
  constructor(options: RoosterOptions) {
    super({
      id: options.id,
      archetypeId: 'enemy_rooster',
      name: 'Rooster',
      position: options.position,
      spriteKey: 'enemy_rooster',
      sensingRange: 6,
      canOpenDoors: false,
      scoreValue: 60,
      dropsMeat: true,
      meatDropChance: 0.2,
      meatSatietyValue: 200,
      meatWeight: 2.0,
      attributes: {
        str: 8,
        con: 7,
        int: 3,
        wis: 4,
        agi: 13,
        luk: 8,
      },
    });
  }
}
