import { Point } from '../types';

export interface EntityProps {
  readonly id: string;
  readonly name: string;
  readonly position: Point;
  readonly spriteKey: string;
  readonly blocksMovement: boolean;
}

/**
 * Base class for any object placed on the dungeon map (actors, items, props).
 */
export class Entity {
  public readonly id: string;
  public name: string;
  public position: Point;
  public spriteKey: string;
  public readonly blocksMovement: boolean;

  constructor(props: EntityProps) {
    this.id = props.id;
    this.name = props.name;
    this.position = { x: props.position.x, y: props.position.y };
    this.spriteKey = props.spriteKey;
    this.blocksMovement = props.blocksMovement;
  }
}
