import { DungeonMap, Rect, rectCenter, rectsOverlap } from '../DungeonMap';
import { SeededRNG } from '../SeededRNG';
import { Tile } from '../Tile';
import { DoorState, Point, pointsEqual, TileType } from '../types';
import {
  DEFAULT_MAP_GEN_CONFIG,
  GeneratedDungeon,
  MapGenConfig,
  MapGenerator,
} from './MapGenerator';

/**
 * Generates a dungeon consisting of multiple rectangular rooms connected by
 * narrow 1-tile-wide corridors, with doors placed at room entrance choke points.
 */
export class RoomsAndCorridorsGenerator implements MapGenerator {
  public readonly id = 'rooms-and-corridors';
  public readonly name = 'Rooms & Narrow Paths';
  public readonly description =
    'Multiple large rooms connected by narrow 1-tile corridors with doors at room entrances.';

  public generate(config?: Partial<MapGenConfig>): GeneratedDungeon {
    const cfg = { ...DEFAULT_MAP_GEN_CONFIG, ...config };
    const rng = new SeededRNG(cfg.seed);
    const map = new DungeonMap(cfg.width, cfg.height);
    const rooms: Rect[] = [];

    const attempts = cfg.maxRooms * 5;
    for (let i = 0; i < attempts && rooms.length < cfg.maxRooms; i++) {
      const w = rng.nextInt(cfg.minRoomSize, cfg.maxRoomSize);
      const h = rng.nextInt(cfg.minRoomSize, cfg.maxRoomSize);
      const maxX = Math.max(2, cfg.width - w - 2);
      const maxY = Math.max(2, cfg.height - h - 2);
      const x = rng.nextInt(2, maxX);
      const y = rng.nextInt(2, maxY);

      const candidate: Rect = { x, y, width: w, height: h };
      if (!rooms.some((r) => rectsOverlap(r, candidate, 2))) {
        map.carveRect(candidate);
        rooms.push(candidate);
      }
    }

    // Fallback guarantee: if map is very small and fewer than 2 rooms fit, place 2 deterministic rooms
    if (rooms.length === 0) {
      const r1: Rect = {
        x: 2,
        y: 2,
        width: Math.min(5, Math.max(3, Math.floor(cfg.width / 3))),
        height: Math.min(5, Math.max(3, Math.floor(cfg.height / 3))),
      };
      map.carveRect(r1);
      rooms.push(r1);
    }
    if (rooms.length === 1 && cfg.width >= 15 && cfg.height >= 10) {
      const r2: Rect = {
        x: Math.max(rooms[0].x + rooms[0].width + 2, cfg.width - 7),
        y: Math.max(2, cfg.height - 7),
        width: 4,
        height: 4,
      };
      if (r2.x + r2.width < cfg.width - 1 && r2.y + r2.height < cfg.height - 1) {
        map.carveRect(r2);
        rooms.push(r2);
      }
    }

    // Connect rooms with narrow 1-tile L-shaped corridors
    for (let i = 1; i < rooms.length; i++) {
      const prevCenter = rectCenter(rooms[i - 1]);
      const currCenter = rectCenter(rooms[i]);

      if (rng.chance(0.5)) {
        this.carveHorizontalTunnel(map, prevCenter.x, currCenter.x, prevCenter.y);
        this.carveVerticalTunnel(map, prevCenter.y, currCenter.y, currCenter.x);
      } else {
        this.carveVerticalTunnel(map, prevCenter.y, currCenter.y, prevCenter.x);
        this.carveHorizontalTunnel(map, prevCenter.x, currCenter.x, currCenter.y);
      }
    }

    // Add an optional loop corridor between two non-adjacent rooms for tactical exploration
    if (rooms.length >= 4) {
      const first = rectCenter(rooms[0]);
      const last = rectCenter(rooms[rooms.length - 1]);
      this.carveHorizontalTunnel(map, first.x, last.x, first.y);
      this.carveVerticalTunnel(map, first.y, last.y, last.x);
    }

    const playerSpawn = rectCenter(rooms[0]);

    // Place doors at valid room perimeter doorway choke points
    this.placeRoomEntranceDoors(map, rooms, playerSpawn, rng, cfg.doorChance);

    // Collect candidate spawn points (interior floor tiles of rooms, excluding playerSpawn)
    const candidateSpawns: Point[] = [];
    for (let i = 0; i < rooms.length; i++) {
      const r = rooms[i];
      for (let y = r.y + 1; y < r.y + r.height - 1; y++) {
        for (let x = r.x + 1; x < r.x + r.width - 1; x++) {
          const pt = { x, y };
          if (!pointsEqual(pt, playerSpawn) && map.getTile(x, y)?.type === TileType.FLOOR) {
            candidateSpawns.push(pt);
          }
        }
      }
    }

    return {
      map,
      playerSpawn,
      rooms,
      candidateSpawns: rng.shuffle(candidateSpawns),
      generatorId: this.id,
      seed: rng.numericSeed,
    };
  }

  private carveHorizontalTunnel(map: DungeonMap, x1: number, x2: number, y: number): void {
    const start = Math.min(x1, x2);
    const end = Math.max(x1, x2);
    for (let x = start; x <= end; x++) {
      if (map.inBounds(x, y)) {
        map.setTile(x, y, Tile.createFloor());
      }
    }
  }

  private carveVerticalTunnel(map: DungeonMap, y1: number, y2: number, x: number): void {
    const start = Math.min(y1, y2);
    const end = Math.max(y1, y2);
    for (let y = start; y <= end; y++) {
      if (map.inBounds(x, y)) {
        map.setTile(x, y, Tile.createFloor());
      }
    }
  }

  private placeRoomEntranceDoors(
    map: DungeonMap,
    rooms: readonly Rect[],
    playerSpawn: Point,
    rng: SeededRNG,
    doorChance: number
  ): void {
    const doorwayCandidates: Point[] = [];

    for (const room of rooms) {
      // Check the 1-tile perimeter ring just outside each room's 4 walls
      for (let x = room.x; x < room.x + room.width; x++) {
        doorwayCandidates.push({ x, y: room.y - 1 });
        doorwayCandidates.push({ x, y: room.y + room.height });
      }
      for (let y = room.y; y < room.y + room.height; y++) {
        doorwayCandidates.push({ x: room.x - 1, y });
        doorwayCandidates.push({ x: room.x + room.width, y });
      }
    }

    let doorsPlaced = 0;
    for (const pt of rng.shuffle(doorwayCandidates)) {
      if (pointsEqual(pt, playerSpawn)) {
        continue;
      }
      if (this.isValidDoorChokePoint(map, pt.x, pt.y)) {
        if (doorsPlaced === 0 || rng.chance(doorChance)) {
          map.setTile(pt.x, pt.y, Tile.createDoor(DoorState.CLOSED));
          doorsPlaced++;
        }
      }
    }
  }

  private isValidDoorChokePoint(map: DungeonMap, x: number, y: number): boolean {
    const tile = map.getTile(x, y);
    if (!tile || tile.type !== TileType.FLOOR) {
      return false;
    }

    // Prevent placing two doors adjacent to each other
    for (const adj of map.getAdjacentPoints({ x, y }, true)) {
      if (map.getTile(adj.x, adj.y)?.type === TileType.DOOR) {
        return false;
      }
    }

    const n = map.getTile(x, y - 1)?.type;
    const s = map.getTile(x, y + 1)?.type;
    const e = map.getTile(x + 1, y)?.type;
    const w = map.getTile(x - 1, y)?.type;

    const horizontalDoorway =
      n === TileType.WALL && s === TileType.WALL && e === TileType.FLOOR && w === TileType.FLOOR;
    const verticalDoorway =
      e === TileType.WALL && w === TileType.WALL && n === TileType.FLOOR && s === TileType.FLOOR;

    return horizontalDoorway || verticalDoorway;
  }
}
