import { Point } from '../types';
import { Enemy } from './Enemy';

export interface ChickOptions {
  readonly id: string;
  readonly position: Point;
}

/**
 * Chick (`小雞`):
 * - Low-tier small critter with short sensing range (4 tiles) and light peck attacks.
 * - Cannot open or close doors (`canOpenDoors = false`).
 */
export class Chick extends Enemy {
  constructor(options: ChickOptions) {
    super({
      id: options.id,
      archetypeId: 'enemy_chick',
      name: 'Chick',
      position: options.position,
      spriteKey: 'enemy_chick',
      sensingRange: 4,
      canOpenDoors: false,
      scoreValue: 25,
      dropsMeat: true,
      meatDropChance: 0.2,
      meatSatietyValue: 100,
      meatWeight: 1.5,
      attributes: {
        str: 4,
        con: 4,
        int: 2,
        wis: 2,
        agi: 10,
        luk: 5,
      },
    });
  }
}
