import { Actor } from '../entities/Actor';
import { registerPotionType } from './PotionCatalog';
import { PotionItem, PotionItemOptions, PotionQuaffEffectResult } from './PotionItem';

export interface StaminaPotionOptions extends PotionItemOptions {
  readonly staminaAmount?: number;
}

/**
 * Potion of Stamina (`體力藥水`): restores 100 SP when quaffed (+10 Satiety).
 */
export class StaminaPotion extends PotionItem {
  public readonly staminaAmount: number;

  constructor(options: StaminaPotionOptions) {
    const staminaAmount = options.staminaAmount ?? 100;
    super({
      id: options.id ?? `stamina-potion-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Potion of Stamina',
      itemTypeId: 'stamina_potion',
      position: options.position,
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.5,
      stackable: true,
      quaffSatietyBonus: options.quaffSatietyBonus,
      description:
        options.description ??
        `An invigorating tonic that restores ${staminaAmount} SP when quaffed.`,
    });
    this.staminaAmount = staminaAmount;
  }

  public override getIdentifiedStatBadge(lang: 'en' | 'zh-TW'): string {
    return lang === 'zh-TW' ? `體力 +${this.staminaAmount}` : `SP +${this.staminaAmount}`;
  }

  public override applyQuaffEffect(actor: Actor): PotionQuaffEffectResult {
    const restored = actor.restoreSp(this.staminaAmount);
    return {
      observableEffect: restored > 0,
      statKey: 'sp',
      amountRestored: restored,
    };
  }

  public override cloneWithAmount(newAmount: number, newId?: string): StaminaPotion {
    const cloned = new StaminaPotion({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
      staminaAmount: this.staminaAmount,
      quaffSatietyBonus: this.quaffSatietyBonus,
    });
    cloned.spriteKey = this.spriteKey;
    return cloned;
  }

  public override serializeCustomData(): Record<string, unknown> {
    return { staminaAmount: this.staminaAmount };
  }
}

registerPotionType('stamina_potion');
