export type ItemDeserializer = (data: SerializedItem) => Item;
export type ItemSpawnFactory = (options: {
  readonly id: string;
  readonly position: Point;
  readonly amount: number;
  readonly createdAtTime?: number;
}) => Item;

export interface WizardItemDescriptor {
  readonly catalogId: string;
  readonly itemTypeId: string;
  readonly name: string;
  readonly itemType: string;
  readonly stackable: boolean;
  readonly weight: number;
  readonly spriteKey: string;
  readonly isMeat: boolean;
  readonly isIdentifiable: boolean;
  readonly create: ItemSpawnFactory;
}

const itemDeserializerRegistry = new Map<string, ItemDeserializer>();
const itemSpawnFactoryRegistry = new Map<string, ItemSpawnFactory>();

function buildStubSerializedItem(
  itemTypeId: string,
  id: string,
  position: Point,
  amount: number
): SerializedItem {
  return {
    id,
    itemTypeId,
    name: itemTypeId,
    itemType: 'misc',
    spriteKey: '',
    position: { ...position },
    amount,
    weight: undefined as unknown as number,
    stackable: true,
    description: undefined as unknown as string,
  };
}

/**
 * Registers a concrete Item subclass deserializer under its `itemTypeId`.
 * Future item classes only need to register here to gain full Save/Load support
 * AND automatic discovery in developer Wizard Mode.
 */
export function registerItemDeserializer(
  itemTypeId: string,
  deserializer: ItemDeserializer,
  spawnFactory?: ItemSpawnFactory
): void {
  itemDeserializerRegistry.set(itemTypeId, deserializer);
  itemSpawnFactoryRegistry.set(
    itemTypeId,
    spawnFactory ??
      (({ id, position, amount }) =>
        deserializer(buildStubSerializedItem(itemTypeId, id, position, amount)))
  );
}

/**
 * Returns auto-discovered metadata and spawn factories for all registered item types.
 */
export function getRegisteredWizardItems(): WizardItemDescriptor[] {
  const entries: WizardItemDescriptor[] = [];

  for (const [itemTypeId, create] of itemSpawnFactoryRegistry.entries()) {
    const sample = create({ id: `sample_${itemTypeId}`, position: { x: 0, y: 0 }, amount: 1 });
    const isIdentifiable =
      isPotionItem(sample) ||
      sample instanceof MagicScroll ||
      sample.itemTypeId.includes('scroll');
    entries.push({
      catalogId: sample.itemTypeId,
      itemTypeId: sample.itemTypeId,
      name: sample.name,
      itemType: sample.itemType,
      stackable: sample.stackable,
      weight: sample.weight,
      spriteKey: sample.spriteKey,
      isMeat: sample instanceof MeatItem,
      isIdentifiable,
      create,
    });
  }

  return entries;
}

/**
 * Reconstructs a concrete `Item` subclass instance from `SerializedItem` data,
 * falling back to the base `Item` class if an unknown or ad-hoc `itemTypeId` is encountered.
 */
export function deserializeItem(data: SerializedItem): Item {
  const factory = itemDeserializerRegistry.get(data.itemTypeId);
  if (factory) {
    return factory(data);
  }
  if (data.customData?.isMeatItem === true || data.itemTypeId.startsWith('meat_')) {
    const sourceArchetypeId =
      typeof data.customData?.sourceArchetypeId === 'string'
        ? data.customData.sourceArchetypeId
        : data.itemTypeId.replace(/^meat_/, '');
    const sourceEnemyName =
      typeof data.customData?.sourceEnemyName === 'string'
        ? data.customData.sourceEnemyName
        : data.name.replace(/^Meat of\s+/i, '');
    const baseSatietyValue =
      typeof data.customData?.baseSatietyValue === 'number'
        ? data.customData.baseSatietyValue
        : 100;
    const createdAtTime =
      typeof data.customData?.createdAtTime === 'number' ? data.customData.createdAtTime : 0;
    const eatMinTurns =
      typeof data.customData?.eatMinTurns === 'number' ? data.customData.eatMinTurns : undefined;
    const eatMaxTurns =
      typeof data.customData?.eatMaxTurns === 'number' ? data.customData.eatMaxTurns : undefined;
    const meat = new MeatItem({
      id: data.id,
      position: { x: data.position.x, y: data.position.y },
      amount: data.amount,
      weight: data.weight,
      description: data.description,
      sourceArchetypeId,
      sourceEnemyName,
      baseSatietyValue,
      createdAtTime,
      eatMinTurns,
      eatMaxTurns,
    });
    if (data.spriteKey) {
      meat.spriteKey = data.spriteKey;
    }
    return meat;
  }
  if (data.customData?.isFoodItem === true) {
    const baseSatietyValue =
      typeof data.customData?.baseSatietyValue === 'number'
        ? data.customData.baseSatietyValue
        : 100;
    return new FoodItem({
      id: data.id,
      name: data.name,
      position: { x: data.position.x, y: data.position.y },
      itemTypeId: data.itemTypeId,
      itemType: data.itemType,
      spriteKey: data.spriteKey,
      amount: data.amount,
      weight: data.weight,
      stackable: data.stackable,
      description: data.description,
      baseSatietyValue,
      eatMinTurns:
        typeof data.customData?.eatMinTurns === 'number' ? data.customData.eatMinTurns : undefined,
      eatMaxTurns:
        typeof data.customData?.eatMaxTurns === 'number' ? data.customData.eatMaxTurns : undefined,
    });
  }
  return new Item({
    id: data.id,
    name: data.name,
    position: { x: data.position.x, y: data.position.y },
    itemTypeId: data.itemTypeId,
    itemType: data.itemType,
    spriteKey: data.spriteKey,
    amount: data.amount,
    weight: data.weight,
    stackable: data.stackable,
    description: data.description,
  });
}

// Register built-in concrete item classes
registerItemDeserializer(
  'healing_potion',
  (d) => {
    const p = new HealingPotion({
      id: d.id,
      position: { ...d.position },
      amount: d.amount,
      weight: d.weight,
      description: d.description,
      healAmount:
        typeof d.customData?.healAmount === 'number' ? d.customData.healAmount : undefined,
    });
    if (d.spriteKey) {
      p.spriteKey = d.spriteKey;
    }
    return p;
  },
  ({ id, position, amount }) => new HealingPotion({ id, position, amount })
);

