const PLAYER_ACTOR_TOKEN = '@player';

function resolvePlayerAwareTemplate(
  lang: LanguageCode,
  key: LogMessageKey,
  defaultTemplate: string,
  params?: Readonly<Record<string, string | number>>
): string {
  if (!params) {
    return defaultTemplate;
  }
  const actorIsPlayer = params.actor === PLAYER_ACTOR_TOKEN;
  const attackerIsPlayer = params.attacker === PLAYER_ACTOR_TOKEN;
  const defenderIsPlayer = params.defender === PLAYER_ACTOR_TOKEN;
  const blockerIsPlayer = params.blocker === PLAYER_ACTOR_TOKEN;

  if (lang === 'en') {
    if (actorIsPlayer) {
      switch (key) {
        case 'enteredDungeon':
          return 'You entered the dungeon ({generator}, seed: {seed}).';
        case 'waits':
          return 'You wait.';
        case 'seesItemsHere':
          return 'You see {items} here.';
        case 'tooHeavyToCarry':
          return 'You cannot carry {item} — too heavy!';
        case 'pickedUpItems':
          return 'You picked up {items}.';
        case 'droppedItems':
          return 'You dropped {items}.';
        case 'opensDoor':
          return 'You open the door.';
        case 'closesDoor':
          return 'You close the door.';
        case 'attackEmptyAir':
          return 'You swing at empty air.';
        case 'attributeIncreased':
          return 'You gained +1 {attr}! ({oldVal} → {newVal})';
        default:
          break;
      }
    }
    if (blockerIsPlayer && key === 'blockingTheWay') {
      return 'You are blocking the way.';
    }
    if (key === 'attackHit') {
      if (attackerIsPlayer) return 'You attack {defender} for {damage} damage.';
      if (defenderIsPlayer) return '{attacker} attacks you for {damage} damage.';
    }
    if (key === 'attackCrit') {
      if (attackerIsPlayer) return 'Critical hit! You strike {defender} for {damage} damage!';
      if (defenderIsPlayer) return 'Critical hit! {attacker} strikes you for {damage} damage!';
    }
    if (key === 'attackMissed') {
      if (attackerIsPlayer) return 'You attack {defender}, but miss.';
      if (defenderIsPlayer) return '{attacker} attacks you, but misses.';
    }
    if (key === 'actorDefeated' && defenderIsPlayer) {
      return 'You are defeated!';
    }
    if (defenderIsPlayer) {
      switch (key) {
        case 'throwItemHitNoDamage':
          return 'You throw {item} at yourself!';
        case 'throwItemHitDamage':
          return 'You throw {item} and hit yourself for {damage} damage!';
        case 'throwPotionRestore':
          return 'You throw {item} at yourself and recover {amount} {stat}!';
        case 'throwPotionIdentifyRestore':
          return 'You throw {item} at yourself and recover {amount} {stat}! It was {trueItem}!';
        case 'throwPotionParalyze':
          return 'You throw {item} at yourself and become paralyzed for {turns} turns!';
        case 'throwPotionIdentifyParalyze':
          return 'You throw {item} at yourself and become paralyzed for {turns} turns! It was {trueItem}!';
        case 'throwPotionNoEffect':
          return 'You throw {item} at yourself, and the vial shatters with no noticeable effect.';
        default:
          break;
      }
    }
  } else if (lang === 'zh-TW') {
    if (actorIsPlayer) {
      switch (key) {
        case 'enteredDungeon':
          return '你進入了地城（{generator}，種子碼：{seed}）。';
        case 'waits':
          return '你原地等待。';
        case 'seesItemsHere':
          return '你在此處發現了 {items}。';
        case 'tooHeavyToCarry':
          return '你無法拿起 {item}——太重了！';
        case 'pickedUpItems':
          return '你拾取了 {items}。';
        case 'droppedItems':
          return '你丟棄了 {items}。';
        case 'opensDoor':
          return '你打開了門。';
        case 'closesDoor':
          return '你關上了門。';
        case 'attackEmptyAir':
          return '你朝該方向揮空了。';
        case 'attributeIncreased':
          return '你的 {attr} 提升了！（{oldVal} → {newVal}）';
        default:
          break;
      }
    }
    if (blockerIsPlayer && key === 'blockingTheWay') {
      return '你擋住了去路。';
    }
    if (key === 'attackHit') {
      if (attackerIsPlayer) return '你攻擊了 {defender}，造成 {damage} 點傷害。';
      if (defenderIsPlayer) return '{attacker} 攻擊了你，造成 {damage} 點傷害。';
    }
    if (key === 'attackCrit') {
      if (attackerIsPlayer) return '暴擊！你重創了 {defender}，造成 {damage} 點傷害！';
      if (defenderIsPlayer) return '暴擊！{attacker} 重創了你，造成 {damage} 點傷害！';
    }
    if (key === 'attackMissed') {
      if (attackerIsPlayer) return '你攻擊 {defender}，但被閃避了。';
      if (defenderIsPlayer) return '{attacker} 攻擊你，但被閃避了。';
    }
    if (key === 'actorDefeated' && defenderIsPlayer) {
      return '你被擊敗了！';
    }
    if (defenderIsPlayer) {
      switch (key) {
        case 'throwItemHitNoDamage':
          return '你朝自己投出了 {item}！';
        case 'throwItemHitDamage':
          return '你投出 {item} 擊中自己，造成 {damage} 點傷害！';
        case 'throwPotionRestore':
          return '你朝自己投擲 {item}，恢復了 {amount} 點{stat}！';
        case 'throwPotionIdentifyRestore':
          return '你朝自己投擲 {item}，恢復了 {amount} 點{stat}！你鑑定出了 {trueItem}！';
        case 'throwPotionParalyze':
          return '你朝自己投擲 {item}，全身麻痺了 {turns} 回合！';
        case 'throwPotionIdentifyParalyze':
          return '你朝自己投擲 {item}，全身麻痺了 {turns} 回合！你鑑定出了 {trueItem}！';
        case 'throwPotionNoEffect':
          return '你朝自己投擲 {item}，藥瓶碎裂但沒有發生明顯的變化。';
        default:
          break;
      }
    }
  }

  return defaultTemplate;
}

export function localizeItemDisplayName(
  lang: LanguageCode,
  rawName: string,
  freshness?: 'fresh' | 'rotten'
): string {
  const catalog = TRANSLATIONS[lang];
  let baseRaw = rawName.trim();
  let detectedFreshness: 'fresh' | 'rotten' | undefined = freshness;

  const freshnessSuffixMatch = /^(.*?)\s*\((Fresh|Rotten)\)$/i.exec(baseRaw);
  if (freshnessSuffixMatch) {
    baseRaw = freshnessSuffixMatch[1].trim();
    if (!detectedFreshness) {
      detectedFreshness =
        freshnessSuffixMatch[2].toLowerCase() === 'rotten' ? 'rotten' : 'fresh';
    }
  }

  let localizedBase = catalog.itemNames[baseRaw];
  if (!localizedBase) {
    const meatMatch = /^Meat of\s+(.+)$/i.exec(baseRaw);
    const potionColorMatch = /^(.+)\s+Potion$/i.exec(baseRaw);
    if (meatMatch) {
      const enemyRaw = meatMatch[1].trim();
      const localizedEnemy = catalog.enemyNames[enemyRaw] ?? enemyRaw;
      localizedBase = lang === 'zh-TW' ? `${localizedEnemy}肉` : `Meat of ${localizedEnemy}`;
    } else if (potionColorMatch) {
      const colorEntry = findPotionColorByEnName(potionColorMatch[1]);
      if (colorEntry) {
        localizedBase =
          lang === 'zh-TW'
            ? `${colorEntry.zhColorName}藥水`
            : `${colorEntry.enColorName} Potion`;
      } else {
        localizedBase = baseRaw;
      }
    } else {
      localizedBase = baseRaw;
    }
  }

  if (!detectedFreshness) {
    return localizedBase;
  }
  const tag =
    detectedFreshness === 'rotten'
      ? catalog.itemModalsUI.rottenTag
      : catalog.itemModalsUI.freshTag;
  return lang === 'zh-TW' ? `${localizedBase}（${tag}）` : `${localizedBase} (${tag})`;
}

/**
 * Formats a localized log message given a language code, message key, and optional template parameters.
 */
export function formatLogMessage(
  lang: LanguageCode,
  key: LogMessageKey,
  params?: Readonly<Record<string, string | number>>
): string {
  const catalog = TRANSLATIONS[lang];
  let template = resolvePlayerAwareTemplate(lang, key, catalog.logTemplates[key], params);
  if (!params) {
    return template;
  }

  for (const [paramKey, rawVal] of Object.entries(params)) {
    let displayVal = String(rawVal);
    if (displayVal === PLAYER_ACTOR_TOKEN) {
      displayVal =
        lang === 'zh-TW'
          ? '你'
          : paramKey === 'defender'
            ? 'you'
            : 'You';
    } else if (paramKey === 'generator' && catalog.mapGenerators[displayVal]) {
      displayVal = catalog.mapGenerators[displayVal];
    } else if (
      paramKey === 'attr' &&
      catalog.stats[displayVal as keyof typeof catalog.stats]
    ) {
      displayVal = catalog.stats[displayVal as keyof typeof catalog.stats];
    } else if (paramKey === 'stat') {
      const statLower = displayVal.toLowerCase();
      if (lang === 'zh-TW') {
        if (statLower === 'hp') displayVal = '生命值（HP）';
        else if (statLower === 'mp') displayVal = '魔力值（MP）';
        else if (statLower === 'sp') displayVal = '體力值（SP）';
      } else {
        displayVal = displayVal.toUpperCase();
      }
    } else if (
      (paramKey === 'actor' ||
        paramKey === 'attacker' ||
        paramKey === 'defender' ||
        paramKey === 'blocker') &&
      catalog.enemyNames[displayVal]
    ) {
      displayVal = catalog.enemyNames[displayVal];
    } else if (paramKey === 'items' || paramKey === 'item' || paramKey === 'trueItem') {
      displayVal = displayVal
        .split(', ')
        .map((entry) => {
          const trimmed = entry.trim();
          const match = /^(.*?)\s+x(\d+)$/.exec(trimmed);
          if (match) {
            const baseName = match[1];
            const count = match[2];
            return `${localizeItemDisplayName(lang, baseName)} x${count}`;
          }
          return localizeItemDisplayName(lang, trimmed);
        })
        .join(lang === 'zh-TW' ? '、' : ', ');
    }
    template = template.replace(new RegExp(`\\{${paramKey}\\}`, 'g'), displayVal);
  }
  return template;
}
