export type ArrowKeyName = 'ArrowUp' | 'ArrowDown' | 'ArrowLeft' | 'ArrowRight';

const ARROW_KEYS = new Set<string>(['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight']);

export function isArrowKey(key: string): key is ArrowKeyName {
  return ARROW_KEYS.has(key);
}

export interface ModalController {
  getActiveModal(): ActiveModalType;
  openTitleScreen?(): void;
  moveTitleSelection?(delta: number): void;
  confirmTitleSelection?(): void;
  openSaveListModal?(): void;
  moveSaveListSelection?(delta: number): void;
  confirmSaveListSelection?(): boolean;
  deleteSelectedSave?(): boolean;
  openSaveConfirmModal?(world?: GameWorld): void;
  toggleSaveConfirmSelection?(): void;
  confirmSaveChoice?(world?: GameWorld, forceChoice?: 'yes' | 'no'): void;
  openLogModal(world: GameWorld): void;
  openHelpModal(): void;
  openConfigModal?(): void;
  openActionModal?(world: GameWorld): void;
  moveActionModalSelection?(world: GameWorld, delta: number): void;
  confirmActionModalSelection?(world: GameWorld): void;
  setActionOptionHandler?(handler: (actionId: ActionMenuOptionId) => void): void;
  openInventoryModal?(world: GameWorld): void;
  openPickupModal?(world: GameWorld): void;
  openDropModal?(world: GameWorld): void;
  openFoodModal?(world: GameWorld): void;
  openQuaffModal?(world: GameWorld): void;
  openThrowModal?(world: GameWorld): void;
  setThrowSelectionHandler?(handler: (itemId: string) => void): void;
  openGameOverModal?(world: GameWorld): void;
  restartFromGameOver?(): void;
  moveItemModalSelection?(world: GameWorld, delta: number): void;
  confirmItemModalSelection?(world: GameWorld, transferAllStack?: boolean): void;
  closeModal(world?: GameWorld): boolean;
  scrollLogModalSlow(direction: -1 | 1): void;
  scrollLogModalPage(direction: -1 | 1): void;
}

/**
 * Resolves a set of simultaneously pressed arrow keys into one of the 8 DirectionVectors,
 * or null if opposing keys cancel out to (0, 0).
 */
export function resolveArrowKeysToDirection(keys: ReadonlySet<ArrowKeyName>): DirectionVector | null {
  let dx = 0;
  let dy = 0;

  if (keys.has('ArrowLeft')) dx -= 1;
  if (keys.has('ArrowRight')) dx += 1;
  if (keys.has('ArrowUp')) dy -= 1;
  if (keys.has('ArrowDown')) dy += 1;

  if (dx === 0 && dy === -1) return DIRECTIONS[DirectionName.UP];
  if (dx === 1 && dy === -1) return DIRECTIONS[DirectionName.UP_RIGHT];
  if (dx === 1 && dy === 0) return DIRECTIONS[DirectionName.RIGHT];
  if (dx === 1 && dy === 1) return DIRECTIONS[DirectionName.RIGHT_DOWN];
  if (dx === 0 && dy === 1) return DIRECTIONS[DirectionName.DOWN];
  if (dx === -1 && dy === 1) return DIRECTIONS[DirectionName.LEFT_DOWN];
  if (dx === -1 && dy === 0) return DIRECTIONS[DirectionName.LEFT];
  if (dx === -1 && dy === -1) return DIRECTIONS[DirectionName.LEFT_UP];

  return null;
}

/**
 * Pure, unit-testable 2-key arrow chord state machine.
 * - Buffers initial arrow key presses for a short window (default 60ms) so pressing
 *   e.g. ArrowRight + ArrowUp nearly simultaneously triggers a single diagonal step (UP_RIGHT).
 * - Reacts only ONCE per press/chord gesture: holding down one or two arrow keys will NOT
 *   continue moving the character; all held arrow keys must be released before the next move.
 */
export class ArrowChordBuffer {
  public readonly chordWindowMs: number;
  private readonly heldKeys = new Set<ArrowKeyName>();
  private readonly pendingChordKeys = new Set<ArrowKeyName>();
  private pendingShiftKey = false;
  private timerId: ReturnType<typeof setTimeout> | null = null;
  private moveDispatchedInCurrentGesture = false;
  private readonly onDirection: (dir: DirectionVector, isDash: boolean) => void;

  constructor(
    onDirection: (dir: DirectionVector, isDash: boolean) => void,
    chordWindowMs = 60
  ) {
    this.onDirection = onDirection;
    this.chordWindowMs = chordWindowMs;
  }

  public handleKeyDown(key: ArrowKeyName, isRepeat = false, shiftKey = false): void {
    // Ignore auto-repeat events or duplicate keydown while key is already held
    if (isRepeat || this.heldKeys.has(key)) {
      return;
    }

    this.heldKeys.add(key);

    // If a move was already triggered during the current hold gesture, wait until all keys are released
    if (this.moveDispatchedInCurrentGesture) {
      return;
    }

    if (shiftKey) {
      this.pendingShiftKey = true;
    }
    this.pendingChordKeys.add(key);

    // Check if both a horizontal and a vertical arrow key are now present (a completed diagonal chord)
    const hasHorizontal =
      this.pendingChordKeys.has('ArrowLeft') || this.pendingChordKeys.has('ArrowRight');
    const hasVertical =
      this.pendingChordKeys.has('ArrowUp') || this.pendingChordKeys.has('ArrowDown');

    if (hasHorizontal && hasVertical) {
      this.dispatchPendingChord();
      return;
    }

    // Start the short chord window timer if not already running
    if (this.timerId === null) {
      this.timerId = setTimeout(() => {
        this.dispatchPendingChord();
      }, this.chordWindowMs);
    }
  }

  public handleKeyUp(key: ArrowKeyName): void {
    this.heldKeys.delete(key);

    // If a single key is released before the chord window expires, dispatch immediately for snappy response
    if (!this.moveDispatchedInCurrentGesture && this.pendingChordKeys.has(key)) {
      this.dispatchPendingChord();
    }

    // Once all arrow keys are released, re-arm the buffer for the next press gesture
    if (this.heldKeys.size === 0) {
      this.moveDispatchedInCurrentGesture = false;
      this.pendingChordKeys.clear();
      this.pendingShiftKey = false;
      this.clearTimer();
    }
  }

  public reset(): void {
    this.clearTimer();
    this.heldKeys.clear();
    this.pendingChordKeys.clear();
    this.pendingShiftKey = false;
    this.moveDispatchedInCurrentGesture = false;
  }

  private dispatchPendingChord(): void {
    this.clearTimer();
    if (this.pendingChordKeys.size === 0 || this.moveDispatchedInCurrentGesture) {
      return;
    }
    const dir = resolveArrowKeysToDirection(this.pendingChordKeys);
    const isDash = this.pendingShiftKey;
    this.pendingChordKeys.clear();
    this.pendingShiftKey = false;
    this.moveDispatchedInCurrentGesture = true;
    if (dir) {
      this.onDirection(dir, isDash);
    }
  }

  private clearTimer(): void {
    if (this.timerId !== null) {
      clearTimeout(this.timerId);
      this.timerId = null;
    }
  }
}

/**
 * Connects DOM Keyboard & Mouse events to GameWorld actions, CanvasRenderer updates,
 * and Modal Tabs ('/' Large Log Modal & 'h' Controls Modal).
 */
export class InputController {
  private world: GameWorld;
  private readonly renderer: CanvasRenderer;
  private readonly onStateChange: () => void;
  private readonly rawOnStateChange: () => void;
  private readonly chordBuffer: ArrowChordBuffer;
  private readonly modalController?: ModalController;
  private readonly autoTravelStepDelayMs: number;
  private readonly paralysisStepDelayMs: number;
  private readonly projectileStepDelayMs: number;
  private awaitingCloseDirection = false;
  private awaitingAttackDirection = false;
  private awaitingDashDirection = false;
  private throwTargetItemId: string | null = null;
  private throwCursorPos: Point | null = null;
  private isAnimatingProjectile = false;
  private projectileTimerId: ReturnType<typeof setTimeout> | null = null;
  private autoTravelQueue: Point[] = [];
  private autoTravelTimerId: ReturnType<typeof setTimeout> | null = null;
  private paralysisTimerId: ReturnType<typeof setTimeout> | null = null;
  private isProcessingParalysisSync = false;

  constructor(
    world: GameWorld,
    renderer: CanvasRenderer,
    onStateChange: () => void,
    chordWindowMs = 60,
    modalController?: ModalController,
    autoTravelStepDelayMs = 0,
    paralysisStepDelayMs = 0,
    projectileStepDelayMs = 0
  ) {
    this.world = world;
    this.renderer = renderer;
    this.modalController = modalController;
    this.autoTravelStepDelayMs = autoTravelStepDelayMs;
    this.paralysisStepDelayMs = paralysisStepDelayMs;
    this.projectileStepDelayMs = projectileStepDelayMs;
    this.rawOnStateChange = () => {
      if (
        !this.world.player.isAlive() &&
        (this.modalController?.getActiveModal() ?? 'none') !== 'gameover'
      ) {
        this.cancelAutoTravel();
        this.cancelParalysisCountdown();
        this.cancelProjectileAnimation();
        this.clearThrowTargeting();
        this.awaitingCloseDirection = false;
        this.awaitingAttackDirection = false;
        this.awaitingDashDirection = false;
        this.chordBuffer.reset();
        this.modalController?.openGameOverModal?.(this.world);
      }
      onStateChange();
    };
    this.onStateChange = () => {
      this.rawOnStateChange();
      this.syncPlayerParalysisState();
    };
    this.chordBuffer = new ArrowChordBuffer(
      (dir, isDash) => this.handleDirectionInput(dir, isDash),
      chordWindowMs
    );
    this.modalController?.setActionOptionHandler?.((actionId) =>
      this.executeActionMenuOption(actionId)
    );
    this.modalController?.setThrowSelectionHandler?.((itemId) =>
      this.startThrowTargeting(itemId)
    );
  }

  public setWorld(world: GameWorld): void {
    this.cancelAutoTravel();
    this.cancelParalysisCountdown();
    this.cancelProjectileAnimation();
    this.clearThrowTargeting();
    this.world = world;
    this.awaitingCloseDirection = false;
    this.awaitingAttackDirection = false;
    this.awaitingDashDirection = false;
    this.chordBuffer.reset();
    this.renderer.setHoverTile(null);
    this.syncPlayerParalysisState();
  }

  public isParalysisCountingDown(): boolean {
    return this.paralysisTimerId !== null;
  }

  public cancelParalysisCountdown(): void {
    if (this.paralysisTimerId !== null) {
      clearTimeout(this.paralysisTimerId);
      this.paralysisTimerId = null;
    }
  }

  /**
   * Drives the player's Paralysis turn countdown:
   * - When `paralysisStepDelayMs <= 0` (headless unit tests), steps all remaining paralyzed turns synchronously.
   * - When `paralysisStepDelayMs > 0` (browser UI, e.g. 120ms/turn), ticks 1 paralyzed turn per interval so
   *   `Paralysis (N)` visibly counts down on `#special-effects-row` while nearby enemies move/attack.
   */
  public syncPlayerParalysisState(): void {
    const activeModal = this.modalController?.getActiveModal() ?? 'none';
    if (
      activeModal === 'title' ||
      activeModal === 'savelist' ||
      activeModal === 'gameover' ||
      !this.world.player.isAlive() ||
      !this.world.player.isParalyzed()
    ) {
      this.cancelParalysisCountdown();
      return;
    }

    this.cancelAutoTravel();
    this.clearThrowTargeting();
    this.awaitingCloseDirection = false;
    this.awaitingAttackDirection = false;
    this.awaitingDashDirection = false;
    this.chordBuffer.reset();

    if (this.paralysisStepDelayMs <= 0) {
      if (this.isProcessingParalysisSync) {
        return;
      }
      this.isProcessingParalysisSync = true;
      try {
        let safety = 1000;
        while (
          safety-- > 0 &&
          this.world.player.isAlive() &&
          this.world.player.isParalyzed()
        ) {
          this.world.stepPlayerParalysisTurn();
          this.rawOnStateChange();
        }
      } finally {
        this.isProcessingParalysisSync = false;
      }
      return;
    }

    if (this.paralysisTimerId === null) {
      this.scheduleNextParalysisStep();
    }
  }

  private scheduleNextParalysisStep(): void {
    if (!this.world.player.isAlive() || !this.world.player.isParalyzed()) {
      this.cancelParalysisCountdown();
      return;
    }
    this.paralysisTimerId = setTimeout(() => {
      this.paralysisTimerId = null;
      const stillParalyzed = this.world.stepPlayerParalysisTurn();
      this.rawOnStateChange();
      if (stillParalyzed) {
        this.scheduleNextParalysisStep();
      }
    }, this.paralysisStepDelayMs);
  }

  public isAwaitingCloseDirection(): boolean {
    return this.awaitingCloseDirection;
  }

  public isAwaitingAttackDirection(): boolean {
    return this.awaitingAttackDirection;
  }

  public isAwaitingDashDirection(): boolean {
    return this.awaitingDashDirection;
  }

  public isThrowTargeting(): boolean {
    return this.throwTargetItemId !== null && this.throwCursorPos !== null;
  }

  public getThrowCursor(): Point | null {
    return this.throwCursorPos ? { ...this.throwCursorPos } : null;
  }

  public isProjectileAnimating(): boolean {
    return this.isAnimatingProjectile;
  }

  public cancelProjectileAnimation(): void {
    if (this.projectileTimerId !== null) {
      clearTimeout(this.projectileTimerId);
      this.projectileTimerId = null;
    }
    this.isAnimatingProjectile = false;
    this.renderer.setFlyingProjectile?.(null);
  }

  private clearThrowTargeting(): void {
    this.throwTargetItemId = null;
    this.throwCursorPos = null;
    this.renderer.setThrowPreview?.(null);
  }

  public isAutoTraveling(): boolean {
    return this.autoTravelQueue.length > 0 || this.autoTravelTimerId !== null;
  }

  public cancelAutoTravel(): void {
    if (this.autoTravelTimerId !== null) {
      clearTimeout(this.autoTravelTimerId);
      this.autoTravelTimerId = null;
    }
    this.autoTravelQueue = [];
  }

  /**
   * Processes a keydown event (returns true if the key was handled and default browser action should be prevented).
   */
  public handleKeyDown(key: string, isRepeat = false, shiftKey = false): boolean {
    // Ignore standalone modifier key presses such as Shift or Control
    if (key === 'Control' || key === 'Shift' || key === 'Alt' || key === 'Meta') {
      return false;
    }
    // Lock all keyboard input while a thrown projectile flight animation is playing
    if (this.isAnimatingProjectile) {
      this.chordBuffer.reset();
      return true;
    }
    // Cancel active auto-travel on any key press
    if (this.isAutoTraveling() && !isRepeat) {
      this.cancelAutoTravel();
      this.onStateChange();
      return true;
    }

    if (
      !this.world.player.isAlive() &&
      (this.modalController?.getActiveModal() ?? 'none') !== 'gameover' &&
      (this.modalController?.getActiveModal() ?? 'none') !== 'title' &&
      (this.modalController?.getActiveModal() ?? 'none') !== 'savelist'
    ) {
      this.modalController?.openGameOverModal?.(this.world);
    }

    const activeModal = this.modalController?.getActiveModal() ?? 'none';

    // Lock all player actions while Paralyzed on the main screen (allowing timeline countdown to proceed)
    if (
      activeModal === 'none' &&
      this.world.player.isAlive() &&
      (this.world.player.isParalyzed() || this.isParalysisCountingDown())
    ) {
      this.chordBuffer.reset();
      return true;
    }

    // 1. Escape closes any open modal tab first (or returns to Title Screen when on Game Over / Save List),
    //    cancels door-close/attack/dash direction mode, or opens the Action Menu Tab on the main screen.
    if (key === 'Escape' && !isRepeat) {
      if (activeModal === 'title') {
        this.chordBuffer.reset();
        return true;
      }
      if (activeModal === 'gameover') {
        this.chordBuffer.reset();
        if (this.modalController?.restartFromGameOver) {
          this.modalController.restartFromGameOver();
        } else {
          this.modalController?.closeModal(this.world);
          this.onStateChange();
        }
        return true;
      }
      if (activeModal !== 'none') {
        this.modalController?.closeModal(this.world);
        this.chordBuffer.reset();
        this.onStateChange();
        return true;
      }
      if (this.awaitingCloseDirection) {
        this.awaitingCloseDirection = false;
        this.world.eventBus.log(
          'Canceled closing door.',
          'info',
          this.world.timeline.currentTime,
          'canceledClosingDoor'
        );
        this.onStateChange();
        return true;
      }
      if (this.awaitingAttackDirection) {
        this.awaitingAttackDirection = false;
        this.world.eventBus.log(
          'Canceled directional attack.',
          'info',
          this.world.timeline.currentTime,
          'canceledAttackDirection'
        );
        this.onStateChange();
        return true;
      }
      if (this.awaitingDashDirection) {
        this.awaitingDashDirection = false;
        this.world.eventBus.log(
          'Canceled dash command.',
          'info',
          this.world.timeline.currentTime,
          'canceledDashDirection'
        );
        this.onStateChange();
        return true;
      }
      if (this.isThrowTargeting()) {
        this.clearThrowTargeting();
        this.chordBuffer.reset();
        this.world.eventBus.log(
          'Canceled throw command.',
          'info',
          this.world.timeline.currentTime,
          'canceledThrowTarget'
        );
        this.onStateChange();
        return true;
      }
      if (this.modalController?.openActionModal) {
        this.chordBuffer.reset();
        this.modalController.openActionModal(this.world);
        this.onStateChange();
        return true;
      }
      return false;
    }

    // 2. When a modal tab is open, suspend gameplay movement and handle modal keys
    if (activeModal !== 'none') {
      if (activeModal === 'gameover') {
        return true;
      }
      if (activeModal === 'title') {
        if (key === 'ArrowUp') {
          this.modalController?.moveTitleSelection?.(-1);
          return true;
        }
        if (key === 'ArrowDown') {
          this.modalController?.moveTitleSelection?.(1);
          return true;
        }
        if (key === 'Enter' && !isRepeat) {
          this.modalController?.confirmTitleSelection?.();
          return true;
        }
        return true;
      }
      if (activeModal === 'savelist') {
        if (key === 'ArrowUp') {
          this.modalController?.moveSaveListSelection?.(-1);
          return true;
        }
        if (key === 'ArrowDown') {
          this.modalController?.moveSaveListSelection?.(1);
          return true;
        }
        if (key === 'Enter' && !isRepeat) {
          this.modalController?.confirmSaveListSelection?.();
          return true;
        }
        if ((key === 'Delete' || key === 'Backspace') && !isRepeat) {
          this.modalController?.deleteSelectedSave?.();
          return true;
        }
        return true;
      }
      if (activeModal === 'save_confirm') {
        if (
          key === 'ArrowLeft' ||
          key === 'ArrowRight' ||
          key === 'ArrowUp' ||
          key === 'ArrowDown'
        ) {
          this.modalController?.toggleSaveConfirmSelection?.();
          return true;
        }
        if (key === 'Enter' && !isRepeat) {
          this.modalController?.confirmSaveChoice?.(this.world);
          return true;
        }
        if ((key === 'y' || key === 'Y') && !isRepeat) {
          this.modalController?.confirmSaveChoice?.(this.world, 'yes');
          return true;
        }
        if ((key === 'n' || key === 'N') && !isRepeat) {
          this.modalController?.confirmSaveChoice?.(this.world, 'no');
          return true;
        }
        return true;
      }
      if (activeModal === 'actions') {
        if (key === 'ArrowUp') {
          this.modalController?.moveActionModalSelection?.(this.world, -1);
          return true;
        }
        if (key === 'ArrowDown') {
          this.modalController?.moveActionModalSelection?.(this.world, 1);
          return true;
        }
        if (key === 'Enter' && !isRepeat) {
          this.modalController?.confirmActionModalSelection?.(this.world);
          return true;
        }
      }

      if (activeModal === 'log') {
        if (key === 'ArrowUp') {
          this.modalController?.scrollLogModalSlow(-1);
          return true;
        }
        if (key === 'ArrowDown') {
          this.modalController?.scrollLogModalSlow(1);
          return true;
        }
        if (key === 'PageUp') {
          this.modalController?.scrollLogModalPage(-1);
          return true;
        }
        if (key === 'PageDown') {
          this.modalController?.scrollLogModalPage(1);
          return true;
        }
      }

      if (
        activeModal === 'inventory' ||
        activeModal === 'pickup' ||
        activeModal === 'drop' ||
        activeModal === 'eat' ||
        activeModal === 'quaff' ||
        activeModal === 'throw'
      ) {
        if (key === 'ArrowUp') {
          this.modalController?.moveItemModalSelection?.(this.world, -1);
          return true;
        }
        if (key === 'ArrowDown') {
          this.modalController?.moveItemModalSelection?.(this.world, 1);
          return true;
        }
        if (key === 'PageUp') {
          this.modalController?.moveItemModalSelection?.(this.world, -5);
          return true;
        }
        if (key === 'PageDown') {
          this.modalController?.moveItemModalSelection?.(this.world, 5);
          return true;
        }
        if (
          (activeModal === 'eat' || activeModal === 'quaff' || activeModal === 'throw') &&
          !isRepeat &&
          key === 'Enter'
        ) {
          this.modalController?.confirmItemModalSelection?.(this.world, false);
          this.onStateChange();
          return true;
        }
        if ((activeModal === 'pickup' || activeModal === 'drop') && !isRepeat) {
          if (key === 'Enter') {
            this.modalController?.confirmItemModalSelection?.(this.world, shiftKey);
            this.onStateChange();
            return true;
          }
          if (key === 'a') {
            this.modalController?.confirmItemModalSelection?.(this.world, true);
            this.onStateChange();
            return true;
          }
        }
      }

      if (key === 'h' && !isRepeat && activeModal !== 'help' && activeModal === 'log') {
        this.modalController?.openHelpModal();
        return true;
      }

      if (key === '/' && !isRepeat && activeModal !== 'log' && activeModal === 'help') {
        this.modalController?.openLogModal(this.world);
        return true;
      }

      // Block gameplay keys while modal is open
      if (
        isArrowKey(key) ||
        key === 'c' ||
        key === 'i' ||
        key === 'g' ||
        key === 'd' ||
        key === 'e' ||
        key === 'q' ||
        key === 'f' ||
        key === 'F' ||
        key === 'D' ||
        key === 'S' ||
        key === '.' ||
        key === ' ' ||
        key === 'Enter'
      ) {
        return true;
      }
      return false;
    }

    // 2.5 Throw Targeting Mode: arrow keys move cursor across VISIBLE tiles; Enter fires
    if (this.isThrowTargeting()) {
      if (isArrowKey(key)) {
        this.chordBuffer.handleKeyDown(key, isRepeat, false);
        return true;
      }
      if (key === 'Enter' && !isRepeat && this.throwCursorPos) {
        this.fireThrowAt(this.throwCursorPos);
        return true;
      }
      return true;
    }

    // 3. Modal open shortcuts ('S' for Save Game Confirmation, '/' for Large Log Tab, 'h' for Controls/Help Tab, 'i' for Inventory, 'e' for Eat Food, 'q' for Quaff Potion, 'f' for Throw Item)
    if (key === 'S' && !isRepeat && this.modalController?.openSaveConfirmModal) {
      this.awaitingCloseDirection = false;
      this.awaitingAttackDirection = false;
      this.awaitingDashDirection = false;
      this.chordBuffer.reset();
      this.modalController.openSaveConfirmModal(this.world);
      this.onStateChange();
      return true;
    }

    if (key === '/' && !isRepeat && this.modalController) {
      this.chordBuffer.reset();
      this.modalController.openLogModal(this.world);
      return true;
    }

    if (key === 'h' && !isRepeat && this.modalController) {
      this.chordBuffer.reset();
      this.modalController.openHelpModal();
      return true;
    }

    if (key === 'i' && !isRepeat && this.modalController?.openInventoryModal) {
      this.chordBuffer.reset();
      this.modalController.openInventoryModal(this.world);
      this.onStateChange();
      return true;
    }

    if (key === 'g' && !isRepeat) {
      this.handlePickUpKeyPress();
      return true;
    }

    if (key === 'd' && !isRepeat) {
      this.handleDropKeyPress();
      return true;
    }

    if (key === 'e' && !isRepeat) {
      this.handleEatKeyPress();
      return true;
    }

    if (key === 'q' && !isRepeat) {
      this.handleQuaffKeyPress();
      return true;
    }

    if (key === 'f' && !isRepeat) {
      this.handleThrowKeyPress();
      return true;
    }

    // 4. Gameplay movement & action keys (case-sensitive alphabet commands: 'c' close door, 'F' directional attack, 'D' directional dash)
    if (isArrowKey(key)) {
      this.chordBuffer.handleKeyDown(key, isRepeat, shiftKey);
      return true;
    }

    if (key === 'c' && !isRepeat) {
      this.handleCloseDoorKeyPress();
      return true;
    }

    if (key === 'F' && !isRepeat) {
      this.handleAttackDirectionKeyPress();
      return true;
    }

    if (key === 'D' && !isRepeat) {
      this.handleDashDirectionKeyPress();
      return true;
    }

    if (key === '.' && !isRepeat && this.awaitingAttackDirection) {
      this.awaitingAttackDirection = false;
      this.world.attackSelf();
      this.onStateChange();
      return true;
    }

    if ((key === '.' || key === ' ') && !isRepeat) {
      this.awaitingCloseDirection = false;
      this.awaitingAttackDirection = false;
      this.awaitingDashDirection = false;
      this.world.performPlayerAction(new WaitAction());
      this.onStateChange();
      return true;
    }

    return false;
  }

  public handleKeyUp(key: string): boolean {
    if (isArrowKey(key)) {
      this.chordBuffer.handleKeyUp(key);
      return true;
    }
    return false;
  }

  /**
   * Routes Mouse Right-Click (`contextmenu`) to the exact same handler as pressing `Escape`.
   */
  public handleRightClick(): boolean {
    return this.handleKeyDown('Escape', false, false);
  }

  /**
   * Executes an option selected from the Action Menu Tab (`#action-modal`).
   */
  public executeActionMenuOption(actionId: ActionMenuOptionId): void {
    switch (actionId) {
      case 'pickup':
        this.modalController?.closeModal(this.world);
        this.handlePickUpKeyPress();
        return;
      case 'inventory':
        this.modalController?.openInventoryModal?.(this.world);
        this.onStateChange();
        return;
      case 'drop':
        this.modalController?.closeModal(this.world);
        this.handleDropKeyPress();
        return;
      case 'attack':
        this.modalController?.closeModal(this.world);
        this.handleAttackDirectionKeyPress();
        return;
      case 'dash':
        this.modalController?.closeModal(this.world);
        this.handleDashDirectionKeyPress();
        return;
      case 'close_door':
        this.modalController?.closeModal(this.world);
        this.handleCloseDoorKeyPress();
        return;
      case 'wait':
        this.modalController?.closeModal(this.world);
        this.world.performPlayerAction(new WaitAction());
        this.onStateChange();
        return;
      case 'log':
        this.modalController?.openLogModal(this.world);
        this.onStateChange();
        return;
      case 'help':
        this.modalController?.openHelpModal();
        this.onStateChange();
        return;
      case 'config':
        this.modalController?.openConfigModal?.();
        this.onStateChange();
        return;
      case 'eat':
        this.modalController?.closeModal(this.world);
        this.handleEatKeyPress();
        return;
      case 'quaff':
        this.modalController?.closeModal(this.world);
        this.handleQuaffKeyPress();
        return;
      case 'throw':
        this.modalController?.closeModal(this.world);
        this.handleThrowKeyPress();
        return;
      case 'save':
        this.modalController?.openSaveConfirmModal?.(this.world);
        this.onStateChange();
        return;
    }
  }

  public attach(targetWindow: Window = window, canvas: HTMLCanvasElement = this.renderer.canvas): () => void {
    const onKeyDown = (e: KeyboardEvent): void => {
      // Allow Escape to close open modals even if focus is inside a SELECT/INPUT control;
      // otherwise ignore keyboard shortcuts when typing in an input/select element
      if (e.key !== 'Escape') {
        const tag = (e.target as HTMLElement | null)?.tagName;
        if (tag === 'INPUT' || tag === 'SELECT' || tag === 'TEXTAREA') {
          return;
        }
      }

      if (this.handleKeyDown(e.key, e.repeat, e.shiftKey)) {
        e.preventDefault();
      }
    };

    const onKeyUp = (e: KeyboardEvent): void => {
      if (this.handleKeyUp(e.key)) {
        e.preventDefault();
      }
    };

    const onWindowBlur = (): void => {
      this.chordBuffer.reset();
    };

    const onContextMenu = (e: MouseEvent): void => {
      e.preventDefault();
      this.handleRightClick();
    };

    const onMouseMove = (e: MouseEvent): void => {
      if ((this.modalController?.getActiveModal() ?? 'none') !== 'none') {
        return;
      }
      if (this.isAnimatingProjectile) {
        return;
      }
      const tilePos = this.mouseEventToTile(e, canvas);
      if (this.isThrowTargeting()) {
        if (this.world.isTileVisible(tilePos)) {
          this.throwCursorPos = { ...tilePos };
          this.renderer.setThrowPreview?.({ cursor: this.throwCursorPos });
          this.renderer.render(this.world);
        }
        return;
      }
      this.renderer.setHoverTile({ position: tilePos, shiftKey: e.shiftKey });
      this.renderer.render(this.world);
    };

    const onMouseLeave = (): void => {
      if (this.isThrowTargeting() || this.isAnimatingProjectile) {
        return;
      }
      this.renderer.setHoverTile(null);
      this.renderer.render(this.world);
    };

    const onMouseClick = (e: MouseEvent): void => {
      if ((this.modalController?.getActiveModal() ?? 'none') !== 'none') {
        return;
      }
      const tilePos = this.mouseEventToTile(e, canvas);
      this.handleTileClick(tilePos, e.shiftKey);
    };

    targetWindow.addEventListener('keydown', onKeyDown);
    targetWindow.addEventListener('keyup', onKeyUp);
    targetWindow.addEventListener('blur', onWindowBlur);
    targetWindow.addEventListener('contextmenu', onContextMenu);
    canvas.addEventListener('mousemove', onMouseMove);
    canvas.addEventListener('mouseleave', onMouseLeave);
    canvas.addEventListener('click', onMouseClick);

    return () => {
      targetWindow.removeEventListener('keydown', onKeyDown);
      targetWindow.removeEventListener('keyup', onKeyUp);
      targetWindow.removeEventListener('blur', onWindowBlur);
      targetWindow.removeEventListener('contextmenu', onContextMenu);
      canvas.removeEventListener('mousemove', onMouseMove);
      canvas.removeEventListener('mouseleave', onMouseLeave);
      canvas.removeEventListener('click', onMouseClick);
    };
  }

  public handleDirectionInput(dir: DirectionVector, isDash = false): void {
    if ((this.modalController?.getActiveModal() ?? 'none') !== 'none') {
      return;
    }

    if (this.isAnimatingProjectile) {
      return;
    }

    if (this.isThrowTargeting() && this.throwCursorPos) {
      const candidate: Point = {
        x: this.throwCursorPos.x + dir.dx,
        y: this.throwCursorPos.y + dir.dy,
      };
      if (this.world.isTileVisible(candidate)) {
        this.throwCursorPos = candidate;
        this.renderer.setThrowPreview?.({ cursor: candidate });
        this.rawOnStateChange();
      }
      return;
    }

    if (this.awaitingDashDirection) {
      this.awaitingDashDirection = false;
      this.world.dashPlayer(dir);
      this.onStateChange();
      return;
    }

    if (this.awaitingAttackDirection) {
      this.awaitingAttackDirection = false;
      this.world.attackInDirection(dir);
      this.onStateChange();
      return;
    }

    if (this.awaitingCloseDirection) {
      this.awaitingCloseDirection = false;
      this.world.attemptCloseAdjacentDoor(dir);
      this.onStateChange();
      return;
    }

    if (isDash) {
      this.world.dashPlayer(dir);
      this.onStateChange();
      return;
    }

    this.world.movePlayer(dir);
    this.onStateChange();
  }

  public handleDashDirectionKeyPress(): void {
    if (this.awaitingDashDirection) {
      this.awaitingDashDirection = false;
      this.world.eventBus.log(
        'Canceled dash command.',
        'info',
        this.world.timeline.currentTime,
        'canceledDashDirection'
      );
      this.onStateChange();
      return;
    }

    if (!this.world.player.canDashBySatiety()) {
      this.world.eventBus.log(
        'You are too weak from hunger to dash!',
        'move',
        this.world.timeline.currentTime,
        'tooWeakToDash'
      );
      this.onStateChange();
      return;
    }

    if (this.world.player.stats.sp < DASH_SP_COST) {
      this.world.eventBus.log(
        'Not enough stamina (SP)!',
        'combat',
        this.world.timeline.currentTime,
        'notEnoughStamina',
        {
          actor: this.world.player.logName,
          required: DASH_SP_COST,
        }
      );
      this.onStateChange();
      return;
    }

    this.awaitingCloseDirection = false;
    this.awaitingAttackDirection = false;
    this.awaitingDashDirection = true;
    this.world.eventBus.log(
      'Dash which direction? (Press direction, click adjacent walkable tile, or Esc to cancel)',
      'info',
      this.world.timeline.currentTime,
      'promptDashDirection'
    );
    this.onStateChange();
  }

  public handleAttackDirectionKeyPress(): void {
    if (this.awaitingAttackDirection) {
      this.awaitingAttackDirection = false;
      this.world.eventBus.log(
        'Canceled directional attack.',
        'info',
        this.world.timeline.currentTime,
        'canceledAttackDirection'
      );
      this.onStateChange();
      return;
    }

    if (this.world.player.stats.sp < MELEE_SP_COST) {
      this.world.eventBus.log(
        'Not enough stamina (SP)!',
        'combat',
        this.world.timeline.currentTime,
        'notEnoughStamina',
        {
          actor: this.world.player.logName,
          required: MELEE_SP_COST,
        }
      );
      this.onStateChange();
      return;
    }

    this.awaitingCloseDirection = false;
    this.awaitingDashDirection = false;
    this.awaitingAttackDirection = true;
    this.world.eventBus.log(
      'Attack in which direction? (Press an arrow key/chord or click an adjacent tile; Esc to cancel)',
      'info',
      this.world.timeline.currentTime,
      'promptAttackDirection'
    );
    this.onStateChange();
  }

  public handleCloseDoorKeyPress(): void {
    if (this.awaitingCloseDirection) {
      this.awaitingCloseDirection = false;
      this.world.eventBus.log(
        'Canceled closing door.',
        'info',
        this.world.timeline.currentTime,
        'canceledClosingDoor'
      );
      this.onStateChange();
      return;
    }

    this.awaitingAttackDirection = false;
    this.awaitingDashDirection = false;
    const resolution = this.world.attemptCloseAdjacentDoor();
    if (resolution.status === 'NEEDS_DIRECTION') {
      this.awaitingCloseDirection = true;
    }
    this.onStateChange();
  }

  /**
   * Handles pressing 'g' (Pick Up Items):
   * - 0 items on current tile -> logs "There is nothing here to pick up." (0 ticks).
   * - 1 visual item group on current tile -> directly picks up the group, logs message, and consumes 1 turn (100 ticks).
   * - 2+ visual item groups on current tile -> opens the Pick Up modal tab for item-by-item selection.
   */
  public handlePickUpKeyPress(): void {
    const now = this.world.timeline.currentTime;
    const groundGroups = groupItemsForDisplay(
      this.world.getItemsAt(this.world.player.position),
      now,
      'ground',
      false
    );
    if (groundGroups.length === 0) {
      this.world.eventBus.log(
        'There is nothing here to pick up.',
        'info',
        now,
        'nothingToPickUp'
      );
      this.onStateChange();
      return;
    }

    if (groundGroups.length === 1) {
      const grp = groundGroups[0];
      let totalPicked = 0;
      for (const member of [...grp.members]) {
        const res = this.world.pickupSpecificGroundItem(
          this.world.player,
          member.id,
          member.amount
        );
        if (res.status === 'PICKED_UP' && res.pickedItem) {
          totalPicked += res.pickedItem.amount;
        } else if (res.status === 'TOO_HEAVY') {
          break;
        }
      }
      if (totalPicked > 0) {
        const logName = this.world.getItemDisplayNameForLog(grp.representative, grp.meatFreshness);
        const itemsSummary = totalPicked > 1 ? `${logName} x${totalPicked}` : logName;
        this.world.eventBus.log(
          `You picked up ${itemsSummary}.`,
          'info',
          this.world.timeline.currentTime,
          'pickedUpItems',
          { actor: this.world.player.logName, items: itemsSummary }
        );
        this.world.advancePlayerTurn(100);
      }
      this.onStateChange();
      return;
    }

    this.chordBuffer.reset();
    this.modalController?.openPickupModal?.(this.world);
    this.onStateChange();
  }

  /**
   * Handles pressing 'd' (Drop Items):
   * - Empty inventory -> logs "Your inventory is empty." without opening the modal (0 ticks).
   * - 1+ items in inventory -> opens the Drop modal tab for item selection.
   */
  public handleDropKeyPress(): void {
    if (this.world.player.inventory.isEmpty()) {
      this.world.eventBus.log(
        'Your inventory is empty.',
        'info',
        this.world.timeline.currentTime,
        'inventoryEmpty'
      );
      this.onStateChange();
      return;
    }

    this.chordBuffer.reset();
    this.modalController?.openDropModal?.(this.world);
    this.onStateChange();
  }

  /**
   * Handles pressing lowercase 'e' (Eat Food):
   * - If player has 'Full' special effect (satiety >= 1200), blocks eating and logs 'tooFullToEat' (0 ticks).
   * - If 0 edible items exist in inventory or on current ground tile, logs 'nothingEdible' (0 ticks).
   * - Otherwise opens the Food Tab ('eat' modal) for item selection.
   */
  public handleEatKeyPress(): void {
    this.awaitingCloseDirection = false;
    this.awaitingAttackDirection = false;
    this.awaitingDashDirection = false;

    const now = this.world.timeline.currentTime;
    if (!this.world.player.canEatFood()) {
      this.world.eventBus.log(
        'You are too full to eat anything!',
        'info',
        now,
        'tooFullToEat'
      );
      this.onStateChange();
      return;
    }

    const edibleGroups = [
      ...groupItemsForDisplay(this.world.player.inventory.getItems(), now, 'inventory', true),
      ...groupItemsForDisplay(this.world.getItemsAt(this.world.player.position), now, 'ground', true),
    ];
    if (edibleGroups.length === 0) {
      this.world.eventBus.log(
        'You have nothing edible to eat.',
        'info',
        now,
        'nothingEdible'
      );
      this.onStateChange();
      return;
    }

    this.chordBuffer.reset();
    this.modalController?.openFoodModal?.(this.world);
    this.onStateChange();
  }

  /**
   * Handles pressing lowercase 'q' (Quaff Potion):
   * - If 0 potions exist in `player.inventory`, logs 'noPotionsInInventory' (0 ticks).
   * - Otherwise opens the inventory-only Potion Tab ('quaff' modal) for potion selection.
   */
  public handleQuaffKeyPress(): void {
    this.awaitingCloseDirection = false;
    this.awaitingAttackDirection = false;
    this.awaitingDashDirection = false;

    const now = this.world.timeline.currentTime;
    const potionGroups = groupItemsForDisplay(
      this.world.player.inventory.getItems(),
      now,
      'inventory',
      'potions'
    );
    if (potionGroups.length === 0) {
      this.world.eventBus.log(
        'You have no potions in your inventory.',
        'info',
        now,
        'noPotionsInInventory'
      );
      this.onStateChange();
      return;
    }

    this.chordBuffer.reset();
    this.modalController?.openQuaffModal?.(this.world);
    this.onStateChange();
  }

  /**
   * Handles pressing lowercase 'f' (Throw Item):
   * - Blocked immediately if `player.stats.sp < 5` ('notEnoughStamina', 0 ticks).
   * - Blocked immediately if `player.inventory` is empty ('inventoryEmpty', 0 ticks).
   * - Otherwise opens the Throw Tab ('throw' modal) listing all inventory items.
   */
  public handleThrowKeyPress(): void {
    this.clearThrowTargeting();
    this.awaitingCloseDirection = false;
    this.awaitingAttackDirection = false;
    this.awaitingDashDirection = false;

    const now = this.world.timeline.currentTime;
    if (this.world.player.stats.sp < THROW_SP_COST) {
      this.world.eventBus.log(
        'Not enough stamina (SP)!',
        'combat',
        now,
        'notEnoughStamina',
        {
          actor: this.world.player.logName,
          required: THROW_SP_COST,
        }
      );
      this.onStateChange();
      return;
    }

    if (this.world.player.inventory.isEmpty()) {
      this.world.eventBus.log(
        'Your inventory is empty.',
        'info',
        now,
        'inventoryEmpty'
      );
      this.onStateChange();
      return;
    }

    this.chordBuffer.reset();
    this.modalController?.openThrowModal?.(this.world);
    this.onStateChange();
  }

  /**
   * Transitions from the 'f' Throw Tab into Throw Targeting Mode (0 ticks):
   * - Auto-snaps initial cursor to the nearest `VISIBLE` enemy, or `@` otherwise.
   */
  public startThrowTargeting(itemId: string): void {
    const item = this.world.player.inventory.getItems().find((i) => i.id === itemId);
    if (!item) {
      return;
    }
    this.awaitingCloseDirection = false;
    this.awaitingAttackDirection = false;
    this.awaitingDashDirection = false;
    this.chordBuffer.reset();

    const now = this.world.timeline.currentTime;
    const rawFresh = isMeatItem(item) ? item.getFreshness(now) : undefined;
    const meatFresh: 'fresh' | 'rotten' | undefined =
      rawFresh === 'rotten' ? 'rotten' : rawFresh === 'fresh' ? 'fresh' : undefined;
    const itemName = this.world.getItemDisplayNameForLog(item, meatFresh);

    this.throwTargetItemId = item.id;
    this.throwCursorPos = this.world.getInitialThrowTarget();
    this.renderer.setHoverTile?.(null);
    this.renderer.setThrowPreview?.({ cursor: this.throwCursorPos });

    this.world.eventBus.log(
      `Choose target tile to throw ${itemName} (Arrow keys / Mouse, Enter or Click to fire, Esc to cancel).`,
      'info',
      now,
      'promptThrowTarget',
      { item: itemName }
    );
    this.rawOnStateChange();
  }

  private fireThrowAt(targetPos: Point): void {
    if (!this.throwTargetItemId) {
      return;
    }
    if (!this.world.isTileVisible(targetPos)) {
      this.world.eventBus.log(
        'Target tile is outside your line of sight!',
        'info',
        this.world.timeline.currentTime,
        'throwOutOfSight'
      );
      this.rawOnStateChange();
      return;
    }

    const itemId = this.throwTargetItemId;
    const item = this.world.player.inventory.getItems().find((i) => i.id === itemId);
    this.clearThrowTargeting();
    this.chordBuffer.reset();

    if (!item) {
      this.onStateChange();
      return;
    }

    const trajectory = this.world.computeThrowTrajectory(targetPos);
    const deferParalysis = this.paralysisStepDelayMs > 0;

    if (this.projectileStepDelayMs <= 0 || trajectory.flightPath.length === 0) {
      this.world.throwInventoryItem(itemId, targetPos, { deferParalysisTicks: deferParalysis });
      this.onStateChange();
      return;
    }

    // Smooth visual flight animation using the item's 32x32 sprite before resolving impact
    const spriteKey = this.world.getItemEffectiveSpriteKey(item);
    const waypoints: Point[] = [{ ...trajectory.origin }, ...trajectory.flightPath];
    const frames: Array<{ x: number; y: number }> = [];
    for (let i = 0; i < waypoints.length - 1; i++) {
      const a = waypoints[i];
      const b = waypoints[i + 1];
      frames.push({ x: (a.x + b.x) * 0.5, y: (a.y + b.y) * 0.5 });
      frames.push({ x: b.x, y: b.y });
    }

    this.isAnimatingProjectile = true;
    const frameIntervalMs = Math.max(8, Math.round(this.projectileStepDelayMs * 0.5));
    let frameIndex = 0;

    const stepAnimation = (): void => {
      if (!this.isAnimatingProjectile) {
        return;
      }
      if (frameIndex < frames.length) {
        this.renderer.setFlyingProjectile?.({
          spriteKey,
          worldPosition: frames[frameIndex],
        });
        this.renderer.render(this.world);
        frameIndex += 1;
        this.projectileTimerId = setTimeout(stepAnimation, frameIntervalMs);
        return;
      }

      this.cancelProjectileAnimation();
      this.world.throwInventoryItem(itemId, targetPos, { deferParalysisTicks: deferParalysis });
      this.onStateChange();
    };

    stepAnimation();
  }

  public handleTileClick(tilePos: Point, shiftKey = false): void {
    if ((this.modalController?.getActiveModal() ?? 'none') !== 'none') {
      return;
    }

    if (this.isAnimatingProjectile) {
      return;
    }

    if (
      this.world.player.isAlive() &&
      (this.world.player.isParalyzed() || this.isParalysisCountingDown())
    ) {
      return;
    }

    if (this.isThrowTargeting()) {
      this.fireThrowAt(tilePos);
      return;
    }

    // Clicking while auto-travel is active cancels the remaining steps
    if (this.isAutoTraveling()) {
      this.cancelAutoTravel();
      this.onStateChange();
      return;
    }

    // If awaiting direction for 'D' / Action Menu Dash, clicking an adjacent walkable tile dashes in that direction
    if (this.awaitingDashDirection) {
      this.awaitingDashDirection = false;
      if (isAdjacent(this.world.player.position, tilePos)) {
        this.world.dashPlayer({
          dx: Math.sign(tilePos.x - this.world.player.position.x) as -1 | 0 | 1,
          dy: Math.sign(tilePos.y - this.world.player.position.y) as -1 | 0 | 1,
        });
      } else {
        this.world.eventBus.log(
          'Canceled dash command.',
          'info',
          this.world.timeline.currentTime,
          'canceledDashDirection'
        );
      }
      this.onStateChange();
      return;
    }

    // If awaiting direction for 'F' directional attack, clicking '@' self-attacks and clicking an adjacent tile attacks that tile
    if (this.awaitingAttackDirection) {
      this.awaitingAttackDirection = false;
      if (pointsEqual(this.world.player.position, tilePos)) {
        this.world.attackSelf();
      } else if (isAdjacent(this.world.player.position, tilePos)) {
        this.world.attackInDirection({
          dx: Math.sign(tilePos.x - this.world.player.position.x) as -1 | 0 | 1,
          dy: Math.sign(tilePos.y - this.world.player.position.y) as -1 | 0 | 1,
        });
      } else {
        this.world.eventBus.log(
          'Canceled directional attack.',
          'info',
          this.world.timeline.currentTime,
          'canceledAttackDirection'
        );
      }
      this.onStateChange();
      return;
    }

    // If awaiting direction for 'c' close door, clicking an adjacent open door closes it
    if (this.awaitingCloseDirection) {
      this.awaitingCloseDirection = false;
      if (isAdjacent(this.world.player.position, tilePos)) {
        this.world.performPlayerAction(new DoorAction(tilePos, 'CLOSE'));
      } else {
        this.world.eventBus.log(
          'Canceled closing door.',
          'info',
          this.world.timeline.currentTime,
          'canceledClosingDoor'
        );
      }
      this.onStateChange();
      return;
    }

    // Clicking the player's own tile ('@') picks up items if present, or waits 1 turn
    if (pointsEqual(this.world.player.position, tilePos)) {
      if (this.world.getItemsAt(tilePos).length > 0) {
        this.handlePickUpKeyPress();
      } else {
        this.world.performPlayerAction(new WaitAction());
        this.onStateChange();
      }
      return;
    }

    const tile = this.world.map.getTile(tilePos.x, tilePos.y);
    if (!tile) {
      return;
    }

    // Shift + Left-Click on an adjacent walkable tile executes a Dash move (2x speed, -10 SP)
    if (shiftKey && isAdjacent(this.world.player.position, tilePos)) {
      this.world.dashPlayer({
        dx: Math.sign(tilePos.x - this.world.player.position.x) as -1 | 0 | 1,
        dy: Math.sign(tilePos.y - this.world.player.position.y) as -1 | 0 | 1,
      });
      this.onStateChange();
      return;
    }

    // Compute shortest path through known (VISIBLE or EXPLORED) tiles
    const path = findShortestPath(this.world, this.world.player.position, tilePos);
    if (!path || path.length === 0) {
      this.world.eventBus.log(
        'Cannot find a walkable path to that tile.',
        'info',
        this.world.timeline.currentTime,
        'clickAdjacentTileHint'
      );
      this.onStateChange();
      return;
    }

    this.autoTravelQueue = [...path];
    this.processAutoTravel();
  }

  private processAutoTravel(): void {
    if (this.autoTravelStepDelayMs <= 0) {
      let safetySteps = 500;
      while (safetySteps-- > 0 && this.executeSingleAutoTravelStep()) {
        // Continue synchronously until path finishes or a halt condition triggers
      }
      this.cancelAutoTravel();
      return;
    }

    if (this.executeSingleAutoTravelStep()) {
      this.scheduleNextAutoTravelStep();
    }
  }

  private scheduleNextAutoTravelStep(): void {
    if (this.autoTravelQueue.length === 0) {
      this.cancelAutoTravel();
      return;
    }
    this.autoTravelTimerId = setTimeout(() => {
      this.autoTravelTimerId = null;
      if (this.executeSingleAutoTravelStep()) {
        this.scheduleNextAutoTravelStep();
      }
    }, this.autoTravelStepDelayMs);
  }

  /**
   * Executes a single step from `autoTravelQueue` and returns `true` only if more steps
   * remain AND no safety halt condition was triggered:
   * 1) Enemy spotted in VISIBLE range -> moves only 1 turn per click and halts.
   * 2) Any new event emitted to the log (e.g., stepping onto items, opening a door, being attacked, buff/debuff) -> halts.
   */
  private executeSingleAutoTravelStep(): boolean {
    if (this.autoTravelQueue.length === 0 || !this.world.player.isAlive()) {
      this.cancelAutoTravel();
      return false;
    }

    const enemyVisibleBeforeStep = this.world.getVisibleEnemies().length > 0;
    const emittedBeforeStep = this.world.eventBus.totalEmittedCount;
    const nextTarget = this.autoTravelQueue.shift()!;

    if (!isAdjacent(this.world.player.position, nextTarget)) {
      this.cancelAutoTravel();
      return false;
    }

    const res = this.world.performPlayerAction(
      MoveAction.fromTargetPoint(this.world.player.position, nextTarget)
    );
    this.onStateChange();

    if (!res.success || this.autoTravelQueue.length === 0) {
      this.cancelAutoTravel();
      return false;
    }

    // Halt Condition 1: Enemy spotted in visible range (only 1 turn per click when enemy is visible)
    if (enemyVisibleBeforeStep || this.world.getVisibleEnemies().length > 0) {
      this.cancelAutoTravel();
      return false;
    }

    // Halt Condition 2: Any new event logged in the message log (even when 500-message rolling history is full)
    if (this.world.eventBus.totalEmittedCount > emittedBeforeStep) {
      this.cancelAutoTravel();
      return false;
    }

    // Ensure the player actually stepped onto nextTarget before continuing
    if (!pointsEqual(this.world.player.position, nextTarget)) {
      this.cancelAutoTravel();
      return false;
    }

    return true;
  }

  private mouseEventToTile(e: MouseEvent, canvas: HTMLCanvasElement): Point {
    const rect = canvas.getBoundingClientRect();
    const scaleX = rect.width > 0 ? canvas.width / rect.width : 1;
    const scaleY = rect.height > 0 ? canvas.height / rect.height : 1;
    const canvasX = (e.clientX - rect.left) * scaleX;
    const canvasY = (e.clientY - rect.top) * scaleY;
    return this.renderer.camera.screenToWorld(canvasX, canvasY, this.world.player.position);
  }
}
