import { Actor } from '../entities/Actor';
import { registerPotionType } from './PotionCatalog';
import { PotionItem, PotionItemOptions, PotionQuaffEffectResult } from './PotionItem';

export interface ManaPotionOptions extends PotionItemOptions {
  readonly manaAmount?: number;
}

/**
 * Potion of Mana (`魔力藥水`): restores 50 MP when quaffed (+10 Satiety).
 */
export class ManaPotion extends PotionItem {
  public readonly manaAmount: number;

  constructor(options: ManaPotionOptions) {
    const manaAmount = options.manaAmount ?? 50;
    super({
      id: options.id ?? `mana-potion-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Potion of Mana',
      itemTypeId: 'mana_potion',
      position: options.position,
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.5,
      stackable: true,
      quaffSatietyBonus: options.quaffSatietyBonus,
      description:
        options.description ??
        `A concentrated arcane elixir that restores ${manaAmount} MP when quaffed.`,
    });
    this.manaAmount = manaAmount;
  }

  public override getIdentifiedStatBadge(lang: 'en' | 'zh-TW'): string {
    return lang === 'zh-TW' ? `魔力 +${this.manaAmount}` : `MP +${this.manaAmount}`;
  }

  public override applyQuaffEffect(actor: Actor): PotionQuaffEffectResult {
    const restored = actor.restoreMp(this.manaAmount);
    return {
      observableEffect: restored > 0,
      statKey: 'mp',
      amountRestored: restored,
    };
  }

  public override cloneWithAmount(newAmount: number, newId?: string): ManaPotion {
    const cloned = new ManaPotion({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
      manaAmount: this.manaAmount,
      quaffSatietyBonus: this.quaffSatietyBonus,
    });
    cloned.spriteKey = this.spriteKey;
    return cloned;
  }

  public override serializeCustomData(): Record<string, unknown> {
    return { manaAmount: this.manaAmount };
  }
}

registerPotionType('mana_potion');
