import { Actor } from '../entities/Actor';
import { registerPotionType } from './PotionCatalog';
import { PotionItem, PotionItemOptions, PotionQuaffEffectResult } from './PotionItem';

export interface HealingPotionOptions extends PotionItemOptions {
  readonly healAmount?: number;
}

/**
 * Potion of Heal (`治療藥水`): restores 50 HP when quaffed (+10 Satiety).
 */
export class HealingPotion extends PotionItem {
  public readonly healAmount: number;

  constructor(options: HealingPotionOptions) {
    const healAmount = options.healAmount ?? 50;
    super({
      id: options.id ?? `healing-potion-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Potion of Heal',
      itemTypeId: 'healing_potion',
      position: options.position,
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.5,
      stackable: true,
      quaffSatietyBonus: options.quaffSatietyBonus,
      description:
        options.description ??
        `A soothing herbal draught that restores ${healAmount} HP when quaffed.`,
    });
    this.healAmount = healAmount;
  }

  public override getIdentifiedStatBadge(lang: 'en' | 'zh-TW'): string {
    return lang === 'zh-TW' ? `生命 +${this.healAmount}` : `HP +${this.healAmount}`;
  }

  public override applyQuaffEffect(actor: Actor): PotionQuaffEffectResult {
    const restored = actor.restoreHp(this.healAmount);
    return {
      observableEffect: restored > 0,
      statKey: 'hp',
      amountRestored: restored,
    };
  }

  public override cloneWithAmount(newAmount: number, newId?: string): HealingPotion {
    const cloned = new HealingPotion({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
      healAmount: this.healAmount,
      quaffSatietyBonus: this.quaffSatietyBonus,
    });
    cloned.spriteKey = this.spriteKey;
    return cloned;
  }

  public override serializeCustomData(): Record<string, unknown> {
    return { healAmount: this.healAmount };
  }
}

registerPotionType('healing_potion');
