import { DungeonMap, Rect, rectCenter, rectsOverlap } from '../DungeonMap';
import { SeededRNG } from '../SeededRNG';
import { Tile } from '../Tile';
import { DoorState, Point, pointsEqual, TileType } from '../types';
import {
  DEFAULT_MAP_GEN_CONFIG,
  GeneratedDungeon,
  MapGenConfig,
  MapGenerator,
} from './MapGenerator';

/**
 * Generates a hybrid Maze & Chambers dungeon:
 * 1. Places odd-aligned chambers across the map.
 * 2. Carves a Recursive Backtracker maze through the remaining wall space.
 * 3. Connects all chambers and maze corridors through doorway connectors.
 * 4. Partially trims dead-end corridors so exploration remains dynamic.
 */
export class MazeGenerator implements MapGenerator {
  public readonly id = 'maze';
  public readonly name = 'Labyrinth Maze & Chambers';
  public readonly description =
    'Winding 1-tile labyrinth corridors interwoven with hidden chambers and doors.';

  public generate(config?: Partial<MapGenConfig>): GeneratedDungeon {
    const cfg = { ...DEFAULT_MAP_GEN_CONFIG, ...config };
    const rng = new SeededRNG(cfg.seed);
    const map = new DungeonMap(cfg.width, cfg.height);
    const rooms: Rect[] = [];

    // 1. Carve odd-aligned rooms so they align cleanly with the odd-grid maze
    const roomAttempts = Math.max(4, Math.floor(cfg.maxRooms * 2));
    const targetRooms = Math.max(2, Math.floor(cfg.maxRooms / 2));

    for (let i = 0; i < roomAttempts && rooms.length < targetRooms; i++) {
      const rawW = rng.nextInt(3, Math.min(7, cfg.maxRoomSize));
      const rawH = rng.nextInt(3, Math.min(7, cfg.maxRoomSize));
      const w = rawW % 2 === 1 ? rawW : rawW + 1;
      const h = rawH % 2 === 1 ? rawH : rawH + 1;

      const maxOddX = cfg.width - w - 2;
      const maxOddY = cfg.height - h - 2;
      if (maxOddX < 1 || maxOddY < 1) {
        break;
      }

      const x = this.randomOdd(rng, 1, maxOddX);
      const y = this.randomOdd(rng, 1, maxOddY);
      const candidate: Rect = { x, y, width: w, height: h };

      if (!rooms.some((r) => rectsOverlap(r, candidate, 2))) {
        map.carveRect(candidate);
        rooms.push(candidate);
      }
    }

    if (rooms.length === 0) {
      const fallbackRoom: Rect = { x: 1, y: 1, width: 3, height: 3 };
      map.carveRect(fallbackRoom);
      rooms.push(fallbackRoom);
    }

    // 2. Carve maze on unvisited odd coordinates using Iterative Backtracker
    for (let y = 1; y < cfg.height - 1; y += 2) {
      for (let x = 1; x < cfg.width - 1; x += 2) {
        if (map.getTile(x, y)?.type === TileType.WALL) {
          this.carveMazeFrom(map, { x, y }, rng);
        }
      }
    }

    // 3. Connect each room to the surrounding maze/rooms and ensure full graph connectivity
    const playerSpawn = rectCenter(rooms[0]);
    this.connectAllRegions(map, playerSpawn, rng, cfg.doorChance);

    // 4. Trim a portion of dead-ends to reduce tedious backtracking
    this.braidAndTrimDeadEnds(map, playerSpawn, 20);

    // 5. Collect floor spawn candidates outside playerSpawn
    const candidateSpawns: Point[] = [];
    for (let y = 1; y < cfg.height - 1; y++) {
      for (let x = 1; x < cfg.width - 1; x++) {
        const pt = { x, y };
        if (!pointsEqual(pt, playerSpawn) && map.getTile(x, y)?.type === TileType.FLOOR) {
          candidateSpawns.push(pt);
        }
      }
    }

    return {
      map,
      playerSpawn,
      rooms,
      candidateSpawns: rng.shuffle(candidateSpawns),
      generatorId: this.id,
      seed: rng.numericSeed,
    };
  }

  private randomOdd(rng: SeededRNG, min: number, max: number): number {
    const val = rng.nextInt(min, max);
    if (val % 2 === 1) return val;
    return val + 1 <= max ? val + 1 : Math.max(1, val - 1);
  }

  private carveMazeFrom(map: DungeonMap, start: Point, rng: SeededRNG): void {
    const stack: Point[] = [start];
    map.setTile(start.x, start.y, Tile.createFloor());

    const dirs = [
      { dx: 0, dy: -2 },
      { dx: 2, dy: 0 },
      { dx: 0, dy: 2 },
      { dx: -2, dy: 0 },
    ];

    while (stack.length > 0) {
      const current = stack[stack.length - 1];
      const unvisitedNeighbors: { next: Point; between: Point }[] = [];

      for (const d of dirs) {
        const nx = current.x + d.dx;
        const ny = current.y + d.dy;
        if (
          nx >= 1 &&
          nx < map.width - 1 &&
          ny >= 1 &&
          ny < map.height - 1 &&
          map.getTile(nx, ny)?.type === TileType.WALL
        ) {
          unvisitedNeighbors.push({
            next: { x: nx, y: ny },
            between: { x: current.x + d.dx / 2, y: current.y + d.dy / 2 },
          });
        }
      }

      if (unvisitedNeighbors.length > 0) {
        const chosen = rng.pick(unvisitedNeighbors);
        map.setTile(chosen.between.x, chosen.between.y, Tile.createFloor());
        map.setTile(chosen.next.x, chosen.next.y, Tile.createFloor());
        stack.push(chosen.next);
      } else {
        stack.pop();
      }
    }
  }

  private connectAllRegions(
    map: DungeonMap,
    playerSpawn: Point,
    rng: SeededRNG,
    doorChance: number
  ): void {
    let doorsPlaced = 0;

    // Repeatedly grow the main connected component from playerSpawn until no disconnected floor remains
    while (true) {
      const reachable = this.floodFillReachable(map, playerSpawn);
      const connectors: Point[] = [];

      for (let y = 1; y < map.height - 1; y++) {
        for (let x = 1; x < map.width - 1; x++) {
          if (map.getTile(x, y)?.type !== TileType.WALL) continue;

          const nReach = reachable.has(`${x},${y - 1}`);
          const sReach = reachable.has(`${x},${y + 1}`);
          const eReach = reachable.has(`${x + 1},${y}`);
          const wReach = reachable.has(`${x - 1},${y}`);

          const nFloor = map.isTraversableIgnoreClosedDoors(x, y - 1);
          const sFloor = map.isTraversableIgnoreClosedDoors(x, y + 1);
          const eFloor = map.isTraversableIgnoreClosedDoors(x + 1, y);
          const wFloor = map.isTraversableIgnoreClosedDoors(x - 1, y);

          const verticalBridge = nFloor && sFloor && nReach !== sReach;
          const horizontalBridge = eFloor && wFloor && eReach !== wReach;

          if (verticalBridge || horizontalBridge) {
            connectors.push({ x, y });
          }
        }
      }

      if (connectors.length === 0) {
        break;
      }

      const chosen = rng.pick(connectors);
      const hasAdjacentDoor = map
        .getAdjacentPoints(chosen, true)
        .some((p) => map.getTile(p.x, p.y)?.type === TileType.DOOR);

      if (!hasAdjacentDoor && (doorsPlaced === 0 || rng.chance(doorChance))) {
        map.setTile(chosen.x, chosen.y, Tile.createDoor(DoorState.CLOSED));
        doorsPlaced++;
      } else {
        map.setTile(chosen.x, chosen.y, Tile.createFloor());
      }
    }
  }

  private floodFillReachable(map: DungeonMap, start: Point): Set<string> {
    const visited = new Set<string>();
    const queue: Point[] = [start];
    visited.add(`${start.x},${start.y}`);

    const cardinalDirs = [
      { dx: 0, dy: -1 },
      { dx: 1, dy: 0 },
      { dx: 0, dy: 1 },
      { dx: -1, dy: 0 },
    ];

    while (queue.length > 0) {
      const curr = queue.shift()!;
      for (const d of cardinalDirs) {
        const nx = curr.x + d.dx;
        const ny = curr.y + d.dy;
        const key = `${nx},${ny}`;
        if (!visited.has(key) && map.isTraversableIgnoreClosedDoors(nx, ny)) {
          visited.add(key);
          queue.push({ x: nx, y: ny });
        }
      }
    }

    return visited;
  }

  private braidAndTrimDeadEnds(map: DungeonMap, protectedPoint: Point, maxSteps: number): void {
    const cardinalDirs = [
      { dx: 0, dy: -1 },
      { dx: 1, dy: 0 },
      { dx: 0, dy: 1 },
      { dx: -1, dy: 0 },
    ];

    for (let step = 0; step < maxSteps; step++) {
      let removedCount = 0;
      for (let y = 1; y < map.height - 1; y++) {
        for (let x = 1; x < map.width - 1; x++) {
          if (x === protectedPoint.x && y === protectedPoint.y) continue;
          if (map.getTile(x, y)?.type !== TileType.FLOOR) continue;

          let wallCount = 0;
          for (const d of cardinalDirs) {
            if (map.getTile(x + d.dx, y + d.dy)?.type === TileType.WALL) {
              wallCount++;
            }
          }
          if (wallCount >= 3) {
            map.setTile(x, y, Tile.createWall());
            removedCount++;
          }
        }
      }
      if (removedCount === 0) break;
    }
  }
}
