import { Actor } from '../entities/Actor';
import { SeededRNG } from '../SeededRNG';
import { ConcreteItemOptions, Item, ItemProps } from './Item';

export const POTION_QUAFF_SATIETY_BONUS = 10;

export type PotionStatKey = 'hp' | 'mp' | 'sp';

export type PotionQuaffEffectResult =
  | {
      readonly kind?: 'restore';
      readonly observableEffect: boolean;
      readonly statKey: PotionStatKey;
      readonly amountRestored: number;
    }
  | {
      readonly kind: 'paralysis';
      readonly observableEffect: boolean;
      readonly paralysisTurnsAdded: number;
    };

export interface PotionItemProps extends Omit<ItemProps, 'itemType' | 'spriteKey'> {
  readonly spriteKey?: string;
  readonly quaffSatietyBonus?: number;
}

export interface PotionItemOptions extends ConcreteItemOptions {
  readonly quaffSatietyBonus?: number;
}

/**
 * Base class for all quaffable/throwable potions ('q' Potion Tab) participating in the per-run
 * randomized color & observable-effect Identify system.
 */
export abstract class PotionItem extends Item {
  public readonly isPotion = true as const;
  public readonly quaffSatietyBonus: number;

  constructor(props: PotionItemProps) {
    super({
      ...props,
      itemType: 'consumable',
      spriteKey: props.spriteKey ?? 'item_potion',
      weight: props.weight ?? 0.5,
      stackable: props.stackable ?? true,
    });
    this.quaffSatietyBonus = props.quaffSatietyBonus ?? POTION_QUAFF_SATIETY_BONUS;
  }

  /**
   * Short stat/effect badge shown in the Upper Item Description Tab once identified
   * (e.g. `HP +50` / `生命 +50` or `Paralysis 5–10t` / `麻痺 5–10回合`).
   */
  public abstract getIdentifiedStatBadge(lang: 'en' | 'zh-TW'): string;

  /**
   * Applies the potion's primary effect to `target` when quaffed ('q')
   * and reports whether an observable change occurred.
   */
  public abstract applyQuaffEffect(target: Actor, rng?: SeededRNG): PotionQuaffEffectResult;

  /**
   * Applies the potion's primary effect to `target` when thrown ('f') and shattered on hit
   * (without granting the +10 quaff Satiety bonus).
   */
  public applyThrowEffect(target: Actor, rng?: SeededRNG): PotionQuaffEffectResult {
    return this.applyQuaffEffect(target, rng);
  }
}

export function isPotionItem(item: Item): item is PotionItem {
  return item instanceof PotionItem;
}
