import { DungeonMap } from '../DungeonMap';
import { deserializeEnemy, SerializedEnemy } from '../enemies';
import {
  PrimaryAttributes,
  SerializedActorState,
  SpecialEffectId,
} from '../entities/Actor';
import { GameEvent, MAX_LOG_HISTORY } from '../EventBus';
import { GameWorld, RunStats } from '../GameWorld';
import { deserializeItem, SerializedItem } from '../items';
import { Tile } from '../Tile';
import { DoorState, TileType, VisibilityState } from '../types';

export const SAVE_SCHEMA_VERSION = 1;
export const SAVE_STORAGE_KEY = 'biohoward.saves.v1';
export const MAX_SAVE_SLOTS = 10;

export interface SaveStorageAdapter {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem?(key: string): void;
}

/**
 * Pure in-memory storage adapter used for deterministic unit tests and headless environments.
 */
export class InMemorySaveStorage implements SaveStorageAdapter {
  private readonly store = new Map<string, string>();

  public getItem(key: string): string | null {
    return this.store.get(key) ?? null;
  }

  public setItem(key: string, value: string): void {
    this.store.set(key, value);
  }

  public removeItem(key: string): void {
    this.store.delete(key);
  }
}

function createDefaultStorageAdapter(): SaveStorageAdapter {
  try {
    if (typeof window !== 'undefined' && window.localStorage) {
      return window.localStorage;
    }
  } catch {
    // Fallback to in-memory storage if browser blocks localStorage access
  }
  return new InMemorySaveStorage();
}

export interface SerializedTile {
  readonly t: TileType;
  readonly d: DoorState;
  readonly v: VisibilityState;
  readonly ld: DoorState;
}

export interface SerializedDungeonMap {
  readonly width: number;
  readonly height: number;
  readonly enemyDensity: number;
  readonly enemySpawnProbability: number;
  readonly tiles: readonly SerializedTile[];
}

export interface GameWorldSaveData {
  readonly version: number;
  readonly runId: string;
  readonly generatorId: string;
  readonly map: SerializedDungeonMap;
  readonly player: SerializedActorState;
  readonly enemies: readonly SerializedEnemy[];
  readonly items: readonly SerializedItem[];
  readonly timeline: {
    readonly currentTime: number;
    readonly turnCount: number;
  };
  readonly rng: {
    readonly numericSeed: number;
    readonly state: number;
  };
  readonly counters: {
    readonly splitItemCounter: number;
    readonly spawnedEnemyCounter: number;
  };
  readonly runStats: RunStats;
  readonly events: readonly GameEvent[];
  readonly identifiedItemTypes?: readonly string[];
  readonly potionColorMap?: Readonly<Record<string, string>>;
  readonly customWorldData?: Record<string, unknown>;
}

export interface SaveSlotMetadata {
  readonly runId: string;
  readonly playerName: string;
  readonly generatorId: string;
  readonly savedAtIso: string;
  readonly savedAtMs: number;
  readonly turnsSurvived: number;
  readonly hp: number;
  readonly maxHp: number;
  readonly mp: number;
  readonly maxMp: number;
  readonly sp: number;
  readonly maxSp: number;
  readonly attributes: PrimaryAttributes;
  readonly specialEffects?: readonly SpecialEffectId[];
  readonly score: number;
}

export interface SaveSlotRecord {
  readonly version: number;
  readonly runId: string;
  readonly metadata: SaveSlotMetadata;
  readonly world: GameWorldSaveData;
}

/**
 * Formats an epoch timestamp (`savedAtMs`) as local `YYYY-MM-DD HH:mm:ss`.
 */
export function formatSaveTimestamp(savedAtMs: number): string {
  const d = new Date(savedAtMs);
  const pad = (n: number): string => String(n).padStart(2, '0');
  return (
    `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ` +
    `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`
  );
}

/**
 * Extensible, versioned Save/Load manager for `GameWorld` snapshots stored in browser `localStorage`.
 */
export class SaveManager {
  private readonly storage: SaveStorageAdapter;
  private readonly storageKey: string;
  private readonly maxSlots: number;

  constructor(
    storage?: SaveStorageAdapter,
    storageKey = SAVE_STORAGE_KEY,
    maxSlots = MAX_SAVE_SLOTS
  ) {
    this.storage = storage ?? createDefaultStorageAdapter();
    this.storageKey = storageKey;
    this.maxSlots = Math.max(1, maxSlots);
  }

  public serializeWorld(world: GameWorld): GameWorldSaveData {
    const tiles: SerializedTile[] = [];
    for (let y = 0; y < world.map.height; y++) {
      for (let x = 0; x < world.map.width; x++) {
        const tile = world.map.getTile(x, y)!;
        tiles.push({
          t: tile.type,
          d: tile.doorState,
          v: tile.visibility,
          ld: tile.lastSeenDoorState,
        });
      }
    }

    const rngState = world.rng.getState();
    const counters = world.getInternalCounters();

    return {
      version: SAVE_SCHEMA_VERSION,
      runId: world.runId,
      generatorId: world.generatorId,
      map: {
        width: world.map.width,
        height: world.map.height,
        enemyDensity: world.map.enemyDensity,
        enemySpawnProbability: world.map.enemySpawnProbability,
        tiles,
      },
      player: world.player.toActorSaveState(),
      enemies: world.enemies.filter((e) => e.isAlive()).map((e) => e.toSaveData()),
      items: world.items.map((i) => i.toSaveData()),
      timeline: {
        currentTime: world.timeline.currentTime,
        turnCount: world.timeline.turnCount,
      },
      rng: {
        numericSeed: rngState.numericSeed,
        state: rngState.state,
      },
      counters: {
        splitItemCounter: counters.splitItemCounter,
        spawnedEnemyCounter: counters.spawnedEnemyCounter,
      },
      runStats: {
        monstersKilled: world.runStats.monstersKilled,
        killsByArchetype: { ...world.runStats.killsByArchetype },
        killScorePoints: world.runStats.killScorePoints,
        damageDealt: world.runStats.damageDealt,
        damageTaken: world.runStats.damageTaken,
        attributeGains: world.runStats.attributeGains ?? 0,
        deathCause: world.runStats.deathCause ?? null,
        killedByArchetypeId: world.runStats.killedByArchetypeId,
        killedByName: world.runStats.killedByName,
      },
      events: world.eventBus.getRecentEvents(MAX_LOG_HISTORY),
      identifiedItemTypes: world.getIdentifiedItemTypeIds(),
      potionColorMap: world.getPotionColorMap(),
    };
  }

  public deserializeWorld(data: GameWorldSaveData): GameWorld {
    const map = new DungeonMap(data.map.width, data.map.height, undefined, {
      enemyDensity: data.map.enemyDensity ?? 12,
      enemySpawnProbability: data.map.enemySpawnProbability ?? 0.15,
    });

    let idx = 0;
    for (let y = 0; y < data.map.height; y++) {
      for (let x = 0; x < data.map.width; x++) {
        const cell = data.map.tiles[idx++];
        if (cell) {
          const tile = new Tile(cell.t, cell.d, cell.v);
          tile.lastSeenDoorState = cell.ld ?? cell.d;
          map.setTile(x, y, tile);
        }
      }
    }

    const world = new GameWorld(
      map,
      { ...data.player.position },
      data.player.name ?? 'Howard',
      data.rng?.numericSeed ?? 1337,
      data.generatorId ?? 'rooms_and_corridors',
      data.runId
    );

    // Restore exact player state (stats, XP, inventory, timeline nextActionTime, regen accumulators)
    world.player.restoreActorSaveState(data.player);

    // Restore ground items directly (preserving exact IDs and stack splits)
    world.items.length = 0;
    if (Array.isArray(data.items)) {
      for (const itemData of data.items) {
        world.items.push(deserializeItem(itemData));
      }
    }

    // Restore living enemies and register them onto the timeline with their saved nextActionTime
    world.enemies.length = 0;
    if (Array.isArray(data.enemies)) {
      for (const enemyData of data.enemies) {
        const enemy = deserializeEnemy(enemyData);
        world.enemies.push(enemy);
        world.timeline.addActor(enemy, enemy.nextActionTime);
      }
    }

    // Restore exact timeline clock & turn counter
    if (data.timeline) {
      world.timeline.restoreState(data.timeline.currentTime ?? 0, data.timeline.turnCount ?? 0);
    }

    // Restore RNG internal Mulberry32 state
    if (data.rng) {
      world.rng.restoreState(data.rng.numericSeed, data.rng.state);
    }

    // Restore internal ID counters
    if (data.counters) {
      world.restoreInternalCounters(
        data.counters.splitItemCounter ?? 0,
        data.counters.spawnedEnemyCounter ?? 0
      );
    }

    // Restore RunStats
    if (data.runStats) {
      world.runStats.monstersKilled = data.runStats.monstersKilled ?? 0;
      world.runStats.killsByArchetype = { ...(data.runStats.killsByArchetype ?? {}) };
      world.runStats.killScorePoints = data.runStats.killScorePoints ?? 0;
      world.runStats.damageDealt = data.runStats.damageDealt ?? 0;
      world.runStats.damageTaken = data.runStats.damageTaken ?? 0;
      world.runStats.attributeGains = data.runStats.attributeGains ?? 0;
      world.runStats.deathCause = data.runStats.deathCause ?? null;
      world.runStats.killedByArchetypeId = data.runStats.killedByArchetypeId ?? null;
      world.runStats.killedByName = data.runStats.killedByName ?? null;
    }

    // Restore EventBus log history (strictly capped at latest MAX_LOG_HISTORY = 500 entries)
    if (Array.isArray(data.events)) {
      world.eventBus.restoreEvents(data.events.slice(-MAX_LOG_HISTORY));
    }

    // Restore per-run item identification & randomized potion color map
    world.restoreIdentificationState(data.identifiedItemTypes ?? [], data.potionColorMap);

    // Recompute current FOV while preserving previously EXPLORED Fog of War tiles
    world.recomputeFOV();

    return world;
  }

  public saveGame(world: GameWorld, now: Date = new Date()): SaveSlotRecord {
    const worldData = this.serializeWorld(world);
    const runSummary = world.getRunSummary();
    const savedAtMs = now.getTime();
    const savedAtIso = now.toISOString();

    const metadata: SaveSlotMetadata = {
      runId: world.runId,
      playerName: world.player.name,
      generatorId: world.generatorId,
      savedAtIso,
      savedAtMs,
      turnsSurvived: runSummary.turnsSurvived,
      hp: world.player.stats.hp,
      maxHp: world.player.stats.maxHp,
      mp: world.player.stats.mp,
      maxMp: world.player.stats.maxMp,
      sp: world.player.stats.sp,
      maxSp: world.player.stats.maxSp,
      attributes: { ...world.player.attributes },
      specialEffects: world.player.getSpecialEffects().map((e) => e.id),
      score: runSummary.score,
    };

    const record: SaveSlotRecord = {
      version: SAVE_SCHEMA_VERSION,
      runId: world.runId,
      metadata,
      world: worldData,
    };

    const existing = this.readAllRecords().filter((r) => r.runId !== world.runId);
    const updated = [record, ...existing]
      .sort((a, b) => b.metadata.savedAtMs - a.metadata.savedAtMs)
      .slice(0, this.maxSlots);

    this.writeAllRecords(updated);
    return record;
  }

  public listSaves(): SaveSlotRecord[] {
    return this.readAllRecords().sort((a, b) => b.metadata.savedAtMs - a.metadata.savedAtMs);
  }

  public loadGame(runId: string): GameWorld | null {
    const found = this.readAllRecords().find((r) => r.runId === runId);
    if (!found) {
      return null;
    }
    return this.deserializeWorld(found.world);
  }

  public deleteSave(runId: string): boolean {
    const current = this.readAllRecords();
    const filtered = current.filter((r) => r.runId !== runId);
    if (filtered.length === current.length) {
      return false;
    }
    this.writeAllRecords(filtered);
    return true;
  }

  public clearAllSaves(): void {
    if (this.storage.removeItem) {
      this.storage.removeItem(this.storageKey);
    } else {
      this.storage.setItem(this.storageKey, '[]');
    }
  }

  private readAllRecords(): SaveSlotRecord[] {
    try {
      const raw = this.storage.getItem(this.storageKey);
      if (!raw) {
        return [];
      }
      const parsed = JSON.parse(raw) as unknown;
      if (!Array.isArray(parsed)) {
        return [];
      }
      return parsed.filter(
        (entry): entry is SaveSlotRecord =>
          Boolean(entry && typeof entry === 'object' && 'runId' in entry && 'world' in entry)
      );
    } catch {
      return [];
    }
  }

  private writeAllRecords(records: readonly SaveSlotRecord[]): void {
    try {
      this.storage.setItem(this.storageKey, JSON.stringify(records));
    } catch {
      // Ignore storage quota errors gracefully
    }
  }
}
