import { GameWorld } from './core/GameWorld';
import {
  GoldCoin,
  HealingPotion,
  IronSword,
  Item,
  MagicScroll,
  ManaPotion,
  ParalyzePotion,
  StaminaPotion,
  TreasureChest,
} from './core/items';
import { createDefaultMapGeneratorRegistry, MapGeneratorRegistry } from './core/mapgen';
import { SaveManager } from './core/save/SaveManager';
import { DEFAULT_TILE_SIZE, Point, VisibilityState } from './core/types';
import { InputController } from './input/InputController';
import { Camera } from './render/Camera';
import { CanvasRenderer } from './render/CanvasRenderer';
import { StatusHUD } from './render/StatusHUD';

export function createWorldFromGenerator(
  registry: MapGeneratorRegistry,
  generatorId: string
): GameWorld {
  const generator = registry.get(generatorId);
  const generated = generator.generate();
  const world = new GameWorld(
    generated.map,
    generated.playerSpawn,
    'Howard',
    generated.seed,
    generator.id
  );

  // Spawn initial enemies (Chick, Rooster, Dog) across walkable tiles with >= 3 tile safety buffer from playerSpawn
  world.spawnInitialEnemies();

  // Give player starting supplies so Inventory ('i'), Quaff ('q'), and Drop ('d') are immediately playable
  world.player.inventory.addItem(
    new HealingPotion({
      id: 'starter-potion',
      position: { ...generated.playerSpawn },
      amount: 2,
    })
  );
  world.player.inventory.addItem(
    new StaminaPotion({
      id: 'starter-stamina-potion',
      position: { ...generated.playerSpawn },
      amount: 1,
    })
  );
  world.player.inventory.addItem(
    new GoldCoin({
      id: 'starter-coins',
      position: { ...generated.playerSpawn },
      amount: 10,
    })
  );

  // Place nearby ground items on passable floor tiles adjacent to playerSpawn so both
  // single-item icons and multi-item bag icons ('item_bag') are immediately visible
  const nearbyFloors = generated.map
    .getAdjacentPoints(generated.playerSpawn, true)
    .filter((pt) => generated.map.getTile(pt.x, pt.y)?.isPassable() ?? false);

  if (nearbyFloors.length >= 1) {
    // Single item stack tile (displays sword icon; 'g' picks up directly)
    world.addItem(
      new IronSword({
        id: 'nearby-sword',
        position: nearbyFloors[0],
      })
    );
  }

  if (nearbyFloors.length >= 2) {
    // Multi-item tile (displays 'item_bag' loot sack icon; 'g' opens Pick Up modal tab)
    const bundlePos = nearbyFloors[1];
    world.addItem(
      new ManaPotion({
        id: 'bundle-potion',
        position: bundlePos,
        amount: 2,
      })
    );
    world.addItem(
      new MagicScroll({
        id: 'bundle-scroll',
        position: bundlePos,
        amount: 2,
      })
    );
    world.addItem(
      new GoldCoin({
        id: 'bundle-coins',
        position: bundlePos,
        amount: 25,
      })
    );
  }

  // Place assorted items in other rooms so item visibility in FOV vs. Fog of War is demonstrable
  const roomFactories: Array<(id: string, pos: Point) => Item> = [
    (id, position) => new TreasureChest({ id, position }),
    (id, position) => new HealingPotion({ id, position, amount: 2 }),
    (id, position) => new ManaPotion({ id, position, amount: 2 }),
    (id, position) => new StaminaPotion({ id, position, amount: 2 }),
    (id, position) => new ParalyzePotion({ id, position, amount: 1 }),
    (id, position) => new MagicScroll({ id, position, amount: 1 }),
    (id, position) => new GoldCoin({ id, position, amount: 15 }),
  ];

  for (let i = 0; i < Math.min(8, generated.candidateSpawns.length); i++) {
    const createRoomItem = roomFactories[i % roomFactories.length];
    world.addItem(createRoomItem(`room-item-${i + 1}`, generated.candidateSpawns[i]));
  }

  world.eventBus.log(
    `You entered the dungeon (${generator.name}, seed: ${generated.seed}).`,
    'info',
    0,
    'enteredDungeon',
    {
      actor: world.player.logName,
      generator: generator.id,
      seed: generated.seed,
    }
  );
  return world;
}

/**
 * Generates a fully illuminated showcase dungeon for the BioHoward Title Screen background.
 */
function createTitleBackgroundWorld(
  registry: MapGeneratorRegistry,
  generatorId: string
): GameWorld {
  const bgWorld = createWorldFromGenerator(registry, generatorId);
  for (let y = 0; y < bgWorld.map.height; y++) {
    for (let x = 0; x < bgWorld.map.width; x++) {
      const tile = bgWorld.map.getTile(x, y);
      if (tile) {
        tile.visibility = VisibilityState.VISIBLE;
      }
    }
  }
  return bgWorld;
}

export function bootstrapApp(): void {
  const canvas = document.getElementById('game-canvas') as HTMLCanvasElement | null;
  const characterNameEl = document.getElementById('character-name');
  const statusSummaryEl = document.getElementById('status-summary');
  const specialEffectsEl = document.getElementById('special-effects-row');
  const controlsContainerEl = document.getElementById('hud-controls');
  const bottomLogTitleEl = document.getElementById('bottom-log-title');
  const messageLogEl = document.getElementById('message-log');
  const logModalEl = document.getElementById('log-modal');
  const logModalTitleEl = document.getElementById('log-modal-title');
  const logModalSubtitleEl = document.getElementById('log-modal-subtitle');
  const logModalBodyEl = document.getElementById('log-modal-body');
  const helpModalEl = document.getElementById('help-modal');
  const helpModalTitleEl = document.getElementById('help-modal-title');
  const helpModalSubtitleEl = document.getElementById('help-modal-subtitle');
  const helpModalTbodyEl = document.getElementById('help-modal-tbody');
  const itemModalEl = document.getElementById('item-modal');
  const itemDescBodyEl = document.getElementById('item-desc-body');
  const itemModalTitleEl = document.getElementById('item-modal-title');
  const itemModalSubtitleEl = document.getElementById('item-modal-subtitle');
  const itemModalBodyEl = document.getElementById('item-modal-body');
  const configModalEl = document.getElementById('config-modal');
  const configModalTitleEl = document.getElementById('config-modal-title');
  const configModalSubtitleEl = document.getElementById('config-modal-subtitle');
  const configModalBodyEl = document.getElementById('config-modal-body');
  const actionModalEl = document.getElementById('action-modal');
  const actionModalTitleEl = document.getElementById('action-modal-title');
  const actionModalSubtitleEl = document.getElementById('action-modal-subtitle');
  const actionModalBodyEl = document.getElementById('action-modal-body');
  const gameOverModalEl = document.getElementById('gameover-modal');
  const gameOverModalTitleEl = document.getElementById('gameover-modal-title');
  const gameOverModalSubtitleEl = document.getElementById('gameover-modal-subtitle');
  const gameOverModalBodyEl = document.getElementById('gameover-modal-body');
  const titleScreenOverlayEl = document.getElementById('title-screen-overlay');
  const titleScreenHeadingEl = document.getElementById('title-screen-heading');
  const titleScreenTaglineEl = document.getElementById('title-screen-tagline');
  const titleScreenMenuEl = document.getElementById('title-screen-menu');
  const titleScreenHintEl = document.getElementById('title-screen-hint');
  const saveConfirmModalEl = document.getElementById('save-confirm-modal');
  const saveConfirmTitleEl = document.getElementById('save-confirm-title');
  const saveConfirmSubtitleEl = document.getElementById('save-confirm-subtitle');
  const saveConfirmBodyEl = document.getElementById('save-confirm-body');
  const saveListModalEl = document.getElementById('savelist-modal');
  const saveListTitleEl = document.getElementById('savelist-modal-title');
  const saveListSubtitleEl = document.getElementById('savelist-modal-subtitle');
  const saveListBodyEl = document.getElementById('savelist-modal-body');

  if (!canvas) {
    return;
  }

  const registry = createDefaultMapGeneratorRegistry();
  const saveManager = new SaveManager();
  let currentGeneratorId = registry.getDefault().id;
  let world = createTitleBackgroundWorld(registry, currentGeneratorId);

  const camera = new Camera(canvas.width, canvas.height, DEFAULT_TILE_SIZE);
  const renderer = new CanvasRenderer(canvas, camera);

  const fitCanvasToContainer = (): void => {
    const parent = canvas.parentElement;
    if (parent) {
      const w = Math.max(480, parent.clientWidth - 16);
      const h = Math.max(240, parent.clientHeight - 16);
      canvas.width = w;
      canvas.height = h;
      camera.resizeViewport(w, h);
    }
  };

  fitCanvasToContainer();

  const hud = new StatusHUD({
    characterNameEl,
    statusSummaryEl,
    specialEffectsEl,
    controlsContainerEl,
    bottomLogTitleEl,
    messageLogEl,
    logModalEl,
    logModalTitleEl,
    logModalSubtitleEl,
    logModalBodyEl,
    helpModalEl,
    helpModalTitleEl,
    helpModalSubtitleEl,
    helpModalTbodyEl,
    itemModalEl,
    itemDescBodyEl,
    itemModalTitleEl,
    itemModalSubtitleEl,
    itemModalBodyEl,
    configModalEl,
    configModalTitleEl,
    configModalSubtitleEl,
    configModalBodyEl,
    actionModalEl,
    actionModalTitleEl,
    actionModalSubtitleEl,
    actionModalBodyEl,
    gameOverModalEl,
    gameOverModalTitleEl,
    gameOverModalSubtitleEl,
    gameOverModalBodyEl,
    titleScreenOverlayEl,
    titleScreenHeadingEl,
    titleScreenTaglineEl,
    titleScreenMenuEl,
    titleScreenHintEl,
    saveConfirmModalEl,
    saveConfirmTitleEl,
    saveConfirmSubtitleEl,
    saveConfirmBodyEl,
    saveListModalEl,
    saveListTitleEl,
    saveListSubtitleEl,
    saveListBodyEl,
    registry,
    saveManager,
    sprites: renderer.sprites,
    onGenerateNewMap: (generatorId: string) => {
      currentGeneratorId = generatorId;
      world = createWorldFromGenerator(registry, currentGeneratorId);
      inputController.setWorld(world);
      fitCanvasToContainer();
      refreshView();
    },
    onStartNewGame: (generatorId: string) => {
      currentGeneratorId = generatorId;
      world = createWorldFromGenerator(registry, currentGeneratorId);
      inputController.setWorld(world);
      fitCanvasToContainer();
      refreshView();
    },
    onLoadSavedWorld: (loadedWorld: GameWorld) => {
      currentGeneratorId = loadedWorld.generatorId;
      world = loadedWorld;
      inputController.setWorld(world);
      fitCanvasToContainer();
      refreshView();
    },
    onReturnToTitleScreen: () => {
      currentGeneratorId = hud.getSelectedGeneratorId();
      world = createTitleBackgroundWorld(registry, currentGeneratorId);
      inputController.setWorld(world);
      fitCanvasToContainer();
      refreshView();
    },
    onTileSizeChange: (newTileSize: number) => {
      renderer.setTileSize(newTileSize);
      refreshView();
    },
    onLanguageChange: () => {
      refreshView();
    },
    onModalStateChange: () => {
      refreshView();
      inputController.syncPlayerParalysisState();
    },
  });

  const refreshView = (): void => {
    renderer.render(world);
    hud.update(world, renderer, currentGeneratorId);
  };

  const inputController = new InputController(
    world,
    renderer,
    refreshView,
    60,
    hud,
    40,
    120,
    28
  );
  inputController.attach(window, canvas);

  if (__ENABLE_WIZARD__) {
    void import('./wizard/WizardMode').then(({ attachWizardMode }) => {
      attachWizardMode({
        getWorld: () => world,
        renderer,
        hud,
        inputController,
        canvas,
        controlsContainerEl,
        refreshView,
      });
    });
  }

  window.addEventListener('resize', () => {
    fitCanvasToContainer();
    refreshView();
  });

  hud.openTitleScreen();
  fitCanvasToContainer();
  refreshView();
}

if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', bootstrapApp);
  } else {
    bootstrapApp();
  }
}
