export interface PotionColorEntry {
  readonly colorId: string;
  readonly spriteKey: string;
  readonly enColorName: string;
  readonly zhColorName: string;
  readonly liquidRgb: readonly [number, number, number];
  readonly highlightRgb: readonly [number, number, number];
}

