function hslToRgb(hDeg: number, sPct: number, lPct: number): [number, number, number] {
  const h = ((hDeg % 360) + 360) % 360;
  const s = Math.max(0, Math.min(1, sPct / 100));
  const l = Math.max(0, Math.min(1, lPct / 100));
  const c = (1 - Math.abs(2 * l - 1)) * s;
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = l - c / 2;
  let r1 = 0;
  let g1 = 0;
  let b1 = 0;

  if (h < 60) {
    r1 = c;
    g1 = x;
  } else if (h < 120) {
    r1 = x;
    g1 = c;
  } else if (h < 180) {
    g1 = c;
    b1 = x;
  } else if (h < 240) {
    g1 = x;
    b1 = c;
  } else if (h < 300) {
    r1 = x;
    b1 = c;
  } else {
    r1 = c;
    b1 = x;
  }

  return [
    Math.round((r1 + m) * 255),
    Math.round((g1 + m) * 255),
    Math.round((b1 + m) * 255),
  ];
}

/**
 * Synthesizes a deterministic extra potion color using golden-angle hue stepping
 * whenever registered potion types exceed `CURATED_POTION_COLORS.length`.
 */
export function synthesizeExtraPotionColor(extraIndex: number): PotionColorEntry {
  const n = Math.max(1, Math.floor(extraIndex));
  const hue = (n * 137.508 + 23) % 360;
  const sat = n % 2 === 0 ? 78 : 66;
  const liquidRgb = hslToRgb(hue, sat, 52);
  const highlightRgb = hslToRgb(hue, Math.min(95, sat + 10), 78);
  const colorId = `prism_${n}`;
  return {
    colorId,
    spriteKey: `item_potion_${colorId}`,
    enColorName: `Prismatic-${n}`,
    zhColorName: `幻彩${n}號`,
    liquidRgb,
    highlightRgb,
  };
}

/**
 * Returns a color pool guaranteed to contain at least `requiredCount` unique potion colors,
 * automatically expanding beyond the curated palette as new potions are added to the game.
 */
export function getPotionColorPool(requiredCount: number): PotionColorEntry[] {
  const pool: PotionColorEntry[] = [...CURATED_POTION_COLORS];
  let extraIdx = 1;
  while (pool.length < requiredCount) {
    pool.push(synthesizeExtraPotionColor(extraIdx++));
  }
  return pool;
}

export function getPotionColorById(colorId: string): PotionColorEntry {
  const curated = CURATED_POTION_COLORS.find((c) => c.colorId === colorId);
  if (curated) {
    return curated;
  }
  const prismMatch = /^prism_(\d+)$/.exec(colorId);
  if (prismMatch) {
    return synthesizeExtraPotionColor(Number(prismMatch[1]));
  }
  return CURATED_POTION_COLORS[0];
}

export function findPotionColorByEnName(enColorName: string): PotionColorEntry | null {
  const lower = enColorName.trim().toLowerCase();
  const curated = CURATED_POTION_COLORS.find((c) => c.enColorName.toLowerCase() === lower);
  if (curated) {
    return curated;
  }
  const prismMatch = /^prismatic-(\d+)$/i.exec(enColorName.trim());
  if (prismMatch) {
    return synthesizeExtraPotionColor(Number(prismMatch[1]));
  }
  return null;
}

const registeredPotionTypeIds = new Set<string>();

/**
 * Registers a potion `itemTypeId` so every new game automatically pairs it with a unique random color.
 */
export function registerPotionType(itemTypeId: string): void {
  registeredPotionTypeIds.add(itemTypeId);
}

export function getRegisteredPotionTypeIds(): string[] {
  return Array.from(registeredPotionTypeIds);
}

/**
 * Generates a fresh randomized 1-to-1 mapping from every registered potion `itemTypeId`
 * (plus any additional `extraPotionTypeIds`) to a unique `colorId` using `rng`.
 */
export function createRandomizedPotionColorMap(
  rng: SeededRNG,
  extraPotionTypeIds: readonly string[] = []
): Record<string, string> {
  const allTypeIds = Array.from(
    new Set([...getRegisteredPotionTypeIds(), ...extraPotionTypeIds])
  ).sort();
  const pool = getPotionColorPool(Math.max(CURATED_POTION_COLORS.length, allTypeIds.length));
  const shuffledColors = rng.shuffle(pool);
  const mapping: Record<string, string> = {};
  for (let i = 0; i < allTypeIds.length; i++) {
    mapping[allTypeIds[i]] = shuffledColors[i].colorId;
  }
  return mapping;
}
