export interface CloseDoorResolution {
  readonly status: 'CLOSED' | 'NONE_NEARBY' | 'NEEDS_DIRECTION' | 'BLOCKED';
  readonly result?: ActionResult;
  readonly candidateDoors: readonly Point[];
}

export interface PickupItemResolution {
  readonly status: 'PICKED_UP' | 'TOO_HEAVY' | 'NONE';
  readonly pickedItem: Item | null;
}

export interface EatFoodResolution {
  readonly status: 'COMPLETED' | 'INTERRUPTED' | 'TOO_FULL' | 'MISSING';
  readonly turnsElapsed: number;
  readonly satietyGained: number;
  readonly decreasedAttribute?: PrimaryAttributeKey;
}

export interface QuaffPotionResolution {
  readonly status: 'QUAFFED' | 'MISSING';
  readonly observableEffect: boolean;
  readonly newlyIdentified: boolean;
  readonly statKey?: PotionStatKey;
  readonly amountRestored: number;
  readonly paralysisTurnsAdded?: number;
  readonly satietyGained: number;
}

export interface ThrowTrajectory {
  readonly origin: Point;
  readonly targetCursor: Point;
  /** Ordered tiles along the flight ray (excluding `origin`, ending at `impactTile`; empty when self-firing at `origin`). */
  readonly flightPath: readonly Point[];
  /** Exact tile where the projectile hits a character or lands/shatters. */
  readonly impactTile: Point;
  /** First living Actor hit (`player` when self-firing at `origin`, or first living Enemy along ray, or null). */
  readonly hitActor: Actor | null;
  /** True if an impassable WALL or CLOSED door stopped the projectile early. */
  readonly blockedByObstacle: boolean;
}

export interface ThrowItemResolution {
  readonly status: 'THROWN' | 'NO_SP' | 'MISSING';
  readonly trajectory?: ThrowTrajectory;
  readonly spriteKey?: string;
  readonly hitActor: Actor | null;
  readonly shattered: boolean;
  readonly droppedItem: Item | null;
  readonly observableEffect: boolean;
  readonly newlyIdentified: boolean;
  readonly statKey?: PotionStatKey;
  readonly amountRestored: number;
  readonly paralysisTurnsAdded?: number;
  readonly damageDealt: number;
}

/**
 * Computes a standard integer Bresenham line from `origin` to `target` (excluding `origin`).
 */
export function computeBresenhamLine(origin: Point, target: Point): Point[] {
  const points: Point[] = [];
  let x0 = origin.x;
  let y0 = origin.y;
  const x1 = target.x;
  const y1 = target.y;

  const dx = Math.abs(x1 - x0);
  const dy = Math.abs(y1 - y0);
  const sx = x0 < x1 ? 1 : -1;
  const sy = y0 < y1 ? 1 : -1;
  let err = dx - dy;

  while (x0 !== x1 || y0 !== y1) {
    const e2 = err * 2;
    if (e2 > -dy) {
      err -= dy;
      x0 += sx;
    }
    if (e2 < dx) {
      err += dx;
      y0 += sy;
    }
    points.push({ x: x0, y: y0 });
  }

  return points;
}

export type DeathCause = 'combat' | 'starvation' | 'self';

export interface RunStats {
  monstersKilled: number;
  killsByArchetype: Record<string, number>;
  killScorePoints: number;
  damageDealt: number;
  damageTaken: number;
  attributeGains: number;
  deathCause?: DeathCause | null;
  killedByArchetypeId: string | null;
  killedByName: string | null;
}

export interface ComputedRunSummary {
  readonly turnsSurvived: number;
  readonly monstersKilled: number;
  readonly killsByArchetype: Readonly<Record<string, number>>;
  readonly killScorePoints: number;
  readonly damageDealt: number;
  readonly damageTaken: number;
  readonly attributeGains: number;
  readonly goldHeld: number;
  readonly itemsHeld: number;
  readonly deathCause: DeathCause | null;
  readonly killedByArchetypeId: string | null;
  readonly killedByName: string | null;
  readonly score: number;
}

const SATIETY_STATE_RANK: Readonly<Record<SatietyState, number>> = {
  full: 5,
  normal: 4,
  hungry: 3,
  weak: 2,
  faint: 1,
  starved: 0,
};

function resolveSatietyTransitionInfo(
  prevState: SatietyState,
  newState: SatietyState
): { key: LogMessageKey; fallbackMessage: string; isCombatHazard: boolean } {
  const worsened = SATIETY_STATE_RANK[newState] < SATIETY_STATE_RANK[prevState];
  switch (newState) {
    case 'starved':
      return {
        key: 'satietyStarved',
        fallbackMessage: 'You starved to death!',
        isCombatHazard: true,
      };
    case 'full':
      return {
        key: 'satietyFull',
        fallbackMessage: 'You feel completely full.',
        isCombatHazard: false,
      };
    case 'normal':
      return worsened
        ? {
            key: 'satietyNormalFromFull',
            fallbackMessage: 'You are no longer overly full.',
            isCombatHazard: false,
          }
        : {
            key: 'satietyRecoveredNormal',
            fallbackMessage: 'Your hunger is satisfied.',
            isCombatHazard: false,
          };
    case 'hungry':
      return worsened
        ? {
            key: 'satietyHungry',
            fallbackMessage: 'You are starting to feel hungry.',
            isCombatHazard: false,
          }
        : {
            key: 'satietyRecoveredHungry',
            fallbackMessage: 'Your strength returns, though you are still hungry.',
            isCombatHazard: false,
          };
    case 'weak':
      return worsened
        ? {
            key: 'satietyWeak',
            fallbackMessage: 'You feel weak from hunger!',
            isCombatHazard: true,
          }
        : {
            key: 'satietyRecoveredWeak',
            fallbackMessage:
              'You recover slightly from the brink of fainting, though you are still weak.',
            isCombatHazard: false,
          };
    case 'faint':
      return {
        key: 'satietyFaint',
        fallbackMessage: 'You feel faint from severe starvation!',
        isCombatHazard: true,
      };
  }
}

/**
 * Central coordinator for the dungeon map, player, enemies, items, timeline, FOV, and event bus.
 * Pure TypeScript with zero DOM dependencies.
 */
export class GameWorld {
  public runId: string;
  public generatorId: string;
  public map: DungeonMap;
  public readonly player: Player;
  public readonly enemies: Enemy[] = [];
  public readonly items: Item[] = [];
  public readonly timeline: TimelineScheduler;
  public readonly eventBus: GameEventBus;
  public readonly rng: SeededRNG;
  public readonly runStats: RunStats;
  private onFOVUpdate?: (world: GameWorld) => void;
  private splitItemCounter = 0;
  private spawnedEnemyCounter = 0;
  private readonly identifiedItemTypes = new Set<string>();
  private potionColorMap: Record<string, string>;

  constructor(
    map: DungeonMap,
    playerSpawn: Point,
    playerName = 'Howard',
    seed: number | string = 1337,
    generatorId = 'rooms_and_corridors',
    runId?: string
  ) {
    this.runId =
      runId ?? `run_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`;
    this.generatorId = generatorId;
    this.map = map;
    this.player = new Player(playerSpawn, undefined, undefined, playerName);
    this.timeline = new TimelineScheduler();
    this.eventBus = new GameEventBus();
    this.rng = new SeededRNG(seed);
    this.potionColorMap = createRandomizedPotionColorMap(
      new SeededRNG(`${String(seed)}::potion_colors`)
    );
    this.runStats = {
      monstersKilled: 0,
      killsByArchetype: {},
      killScorePoints: 0,
      damageDealt: 0,
      damageTaken: 0,
      attributeGains: 0,
      deathCause: null,
      killedByArchetypeId: null,
      killedByName: null,
    };

    this.player.setAttributeLevelUpHandler((evt) => {
      this.runStats.attributeGains += 1;
      const attrUpper = evt.attribute.toUpperCase();
      this.eventBus.log(
        `You gained +1 ${attrUpper}! (${evt.oldValue} → ${evt.newValue})`,
        'info',
        this.timeline.currentTime,
        'attributeIncreased',
        {
          actor: this.player.logName,
          attr: evt.attribute,
          oldVal: evt.oldValue,
          newVal: evt.newValue,
        }
      );
    });

    this.player.setSatietyStateChangeHandler((evt) => {
      const info = resolveSatietyTransitionInfo(evt.previousState, evt.newState);
      this.eventBus.log(
        info.fallbackMessage,
        info.isCombatHazard ? 'combat' : 'info',
        this.timeline.currentTime,
        info.key
      );
    });

    this.player.setBurdenedStateChangeHandler((evt) => {
      if (evt.isBurdened) {
        this.eventBus.log(
          'You are burdened by heavy gear!',
          'info',
          this.timeline.currentTime,
          'burdenedEntered'
        );
      } else {
        this.eventBus.log(
          'You are no longer burdened.',
          'info',
          this.timeline.currentTime,
          'burdenedCleared'
        );
      }
    });

    this.player.setStarvationDeathHandler(() => {
      this.runStats.deathCause = 'starvation';
      this.runStats.killedByArchetypeId = null;
      this.runStats.killedByName = null;
    });

    this.timeline.addActor(this.player, 0);
    this.recomputeFOV();
  }

  public recordDamageDealt(amount: number): void {
    if (amount > 0) {
      this.runStats.damageDealt += amount;
    }
  }

  public recordDamageTaken(amount: number, attacker?: Actor): void {
    if (amount > 0) {
      this.runStats.damageTaken += amount;
    }
    if (!this.player.isAlive() && attacker) {
      if (attacker.isPlayer) {
        this.runStats.deathCause = 'self';
        this.runStats.killedByArchetypeId = null;
        this.runStats.killedByName = null;
      } else {
        const maybeEnemy = attacker as Partial<Enemy>;
        this.runStats.deathCause = 'combat';
        this.runStats.killedByArchetypeId = maybeEnemy.archetypeId ?? attacker.spriteKey ?? null;
        this.runStats.killedByName = attacker.name;
      }
    }
  }

  public recordEnemyDefeated(enemy: Enemy): void {
    this.runStats.monstersKilled += 1;
    const key = enemy.archetypeId || enemy.spriteKey || enemy.name;
    this.runStats.killsByArchetype[key] = (this.runStats.killsByArchetype[key] ?? 0) + 1;
    this.runStats.killScorePoints += Math.max(0, enemy.scoreValue);
  }

  /**
   * Computes the current or end-of-run statistics and comprehensive score:
   * Score = sum(Enemy Kill Points) + (Damage Dealt * 1) + (Gold Held * 2) + min(Turns Survived, 200)
   */
  public getRunSummary(): ComputedRunSummary {
    const turnsSurvived = Math.floor(this.timeline.currentTime / 100);
    let goldHeld = 0;
    let itemsHeld = 0;
    for (const item of this.player.inventory.getItems()) {
      if (item.itemTypeId === 'gold_coin') {
        goldHeld += item.amount;
      } else {
        itemsHeld += item.amount;
      }
    }

    const score =
      this.runStats.killScorePoints +
      this.runStats.damageDealt +
      goldHeld * 2 +
      this.runStats.attributeGains * 20 +
      Math.min(turnsSurvived, 200);

    return {
      turnsSurvived,
      monstersKilled: this.runStats.monstersKilled,
      killsByArchetype: { ...this.runStats.killsByArchetype },
      killScorePoints: this.runStats.killScorePoints,
      damageDealt: this.runStats.damageDealt,
      damageTaken: this.runStats.damageTaken,
      attributeGains: this.runStats.attributeGains,
      goldHeld,
      itemsHeld,
      deathCause: this.runStats.deathCause ?? null,
      killedByArchetypeId: this.runStats.killedByArchetypeId,
      killedByName: this.runStats.killedByName,
      score,
    };
  }

  public nextRandom(): number {
    return this.rng.nextFloat();
  }

  public getInternalCounters(): { splitItemCounter: number; spawnedEnemyCounter: number } {
    return {
      splitItemCounter: this.splitItemCounter,
      spawnedEnemyCounter: this.spawnedEnemyCounter,
    };
  }

  public restoreInternalCounters(splitItemCounter: number, spawnedEnemyCounter: number): void {
    this.splitItemCounter = Math.max(0, splitItemCounter);
    this.spawnedEnemyCounter = Math.max(0, spawnedEnemyCounter);
  }

  public allocateSpawnedEnemyId(): string {
    return `enemy_${++this.spawnedEnemyCounter}`;
  }

  public allocateItemId(prefix = 'item'): string {
    return `${prefix}_${++this.splitItemCounter}`;
  }

  public clearIdentifiedItems(): void {
    this.identifiedItemTypes.clear();
  }

  public isItemIdentified(itemTypeId: string): boolean {
    return this.identifiedItemTypes.has(itemTypeId);
  }

  /**
   * Marks `itemTypeId` as identified for this run (`true` if newly identified, `false` if already known).
   */
  public identifyItemType(itemTypeId: string): boolean {
    if (this.identifiedItemTypes.has(itemTypeId)) {
      return false;
    }
    this.identifiedItemTypes.add(itemTypeId);
    return true;
  }

  public getIdentifiedItemTypeIds(): string[] {
    return Array.from(this.identifiedItemTypes);
  }

  public getPotionColorMap(): Readonly<Record<string, string>> {
    return { ...this.potionColorMap };
  }

  public restoreIdentificationState(
    identifiedIds: readonly string[],
    savedPotionColorMap?: Readonly<Record<string, string>>
  ): void {
    this.identifiedItemTypes.clear();
    for (const id of identifiedIds) {
      if (typeof id === 'string' && id.length > 0) {
        this.identifiedItemTypes.add(id);
      }
    }
    if (savedPotionColorMap && Object.keys(savedPotionColorMap).length > 0) {
      this.potionColorMap = { ...savedPotionColorMap };
    }
  }

  /**
   * Returns the `colorId` paired with `potionItemTypeId` in this run, lazily assigning a unique unused
   * color from the auto-expanding palette if a newly added potion type was not yet mapped.
   */
  public getPotionColorId(potionItemTypeId: string): string {
    const existing = this.potionColorMap[potionItemTypeId];
    if (existing) {
      return existing;
    }
    const usedColorIds = new Set(Object.values(this.potionColorMap));
    const pool = getPotionColorPool(usedColorIds.size + 4);
    const available = pool.filter((c) => !usedColorIds.has(c.colorId));
    const chosen =
      available.length > 0
        ? available[this.rng.nextInt(0, available.length - 1)]
        : pool[pool.length - 1];
    this.potionColorMap[potionItemTypeId] = chosen.colorId;
    return chosen.colorId;
  }

  public getPotionColorEntry(potionItemTypeId: string): PotionColorEntry {
    return getPotionColorById(this.getPotionColorId(potionItemTypeId));
  }

  public getItemEffectiveSpriteKey(item: Item): string {
    if (isPotionItem(item)) {
      const sprite = this.getPotionColorEntry(item.itemTypeId).spriteKey;
      item.spriteKey = sprite;
      return sprite;
    }
    if (isFoodItem(item)) {
      return item.getEffectiveSpriteKey(this.timeline.currentTime);
    }
    return item.spriteKey;
  }

  /**
   * Returns the English/canonical log token for `item` respecting unidentified potion masking
   * (`"{Color} Potion"` before identification, or `item.name` once identified) and meat freshness.
   */
  public getItemDisplayNameForLog(item: Item, meatFreshness?: 'fresh' | 'rotten'): string {
    if (meatFreshness) {
      return `${item.name} (${meatFreshness === 'rotten' ? 'Rotten' : 'Fresh'})`;
    }
    if (isPotionItem(item) && !this.isItemIdentified(item.itemTypeId)) {
      const color = this.getPotionColorEntry(item.itemTypeId);
      return `${color.enColorName} Potion`;
    }
    return item.name;
  }

  /**
   * Registers an optional listener that is notified whenever FOV is recomputed.
   */
  public setFOVUpdateHandler(handler: (world: GameWorld) => void): void {
    this.onFOVUpdate = handler;
    this.recomputeFOV();
  }

  public recomputeFOV(): void {
    FOVSystem.computeFOV(this.map, this.player.position, this.player.sightRadius);
    if (this.onFOVUpdate) {
      this.onFOVUpdate(this);
    }
  }

  public isTileVisible(pos: Point): boolean {
    return this.map.getTile(pos.x, pos.y)?.visibility === VisibilityState.VISIBLE;
  }

  public isTileExplored(pos: Point): boolean {
    return this.map.getTile(pos.x, pos.y)?.visibility === VisibilityState.EXPLORED;
  }

  /**
   * Returns true only if the entity's current tile is currently VISIBLE to the player.
   * Entities on UNEXPLORED or EXPLORED (Fog of War) tiles are hidden from the player.
   */
  public canPlayerSeeEntity(entity: Entity): boolean {
    return this.isTileVisible(entity.position);
  }

  public getLivingEnemies(): Enemy[] {
    return this.enemies.filter((enemy) => enemy.isAlive());
  }

  public getVisibleEnemies(): Enemy[] {
    return this.enemies.filter((enemy) => enemy.isAlive() && this.isTileVisible(enemy.position));
  }

  public getAdjacentEnemies(): Enemy[] {
    return this.enemies.filter(
      (enemy) => enemy.isAlive() && isAdjacent(this.player.position, enemy.position)
    );
  }

  public getVisibleItems(): Item[] {
    return this.items.filter((item) => this.isTileVisible(item.position));
  }

  public addEnemy(enemy: Enemy): void {
    this.enemies.push(enemy);
    this.timeline.addActor(enemy, this.timeline.currentTime);
  }

  public removeEnemy(enemyId: string): void {
    const idx = this.enemies.findIndex((e) => e.id === enemyId);
    if (idx !== -1) {
      this.enemies.splice(idx, 1);
    }
    this.timeline.removeActor(enemyId);
  }

  /**
   * Spawns initial enemies across walkable tiles when the game starts:
   * - Bounded by `this.map.enemyDensity`.
   * - Defaults to ~65% of `enemyDensity` (e.g., 8 enemies when `enemyDensity = 12`) so per-cycle
   *   dynamic spawning has headroom to operate.
   * - Enforces a minimum Chebyshev distance >= 3 from `player.position` when possible.
   */
  public spawnInitialEnemies(initialCount?: number): Enemy[] {
    if (this.map.enemyDensity <= 0) {
      return [];
    }

    const defaultCount = Math.min(
      this.map.enemyDensity,
      Math.max(1, Math.round(this.map.enemyDensity * 0.65))
    );
    const remainingCapacity = Math.max(
      0,
      this.map.enemyDensity - this.getLivingEnemies().length
    );
    const targetCount = Math.min(remainingCapacity, initialCount ?? defaultCount);
    if (targetCount <= 0) {
      return [];
    }

    const allWalkable = this.map
      .getWalkablePoints()
      .filter((pt) => this.getBlockingActorAt(pt) === null);

    const safeWalkable = allWalkable.filter((pt) => {
      const chebyshev = Math.max(
        Math.abs(pt.x - this.player.position.x),
        Math.abs(pt.y - this.player.position.y)
      );
      return chebyshev >= 3;
    });

    const pool = safeWalkable.length >= targetCount ? safeWalkable : allWalkable;
    const shuffled = this.rng.shuffle(pool);
    const spawned: Enemy[] = [];

    for (let i = 0; i < Math.min(targetCount, shuffled.length); i++) {
      const pos = shuffled[i];
      const enemy = createWeightedEnemy(
        `enemy_${++this.spawnedEnemyCounter}`,
        pos,
        this.nextRandom()
      );
      this.addEnemy(enemy);
      spawned.push(enemy);
    }

    return spawned;
  }

  /**
   * Attempts to dynamically spawn 1 new enemy when the timeline reaches a new tick cycle:
   * - Only spawns if `livingEnemies.length < map.enemyDensity`.
   * - Rolls against `map.enemySpawnProbability`.
   * - Strictly places the enemy on an unoccupied walkable tile OUTSIDE the player's current sight range
   *   (`tile.visibility !== VisibilityState.VISIBLE`).
   */
  public trySpawnDynamicEnemyOutsideSight(): Enemy | null {
    if (this.getLivingEnemies().length >= this.map.enemyDensity) {
      return null;
    }

    if (
      this.map.enemySpawnProbability <= 0 ||
      this.nextRandom() >= this.map.enemySpawnProbability
    ) {
      return null;
    }

    const validOutsideSight = this.map.getWalkablePoints().filter((pt) => {
      const tile = this.map.getTile(pt.x, pt.y);
      if (!tile || tile.visibility === VisibilityState.VISIBLE) {
        return false;
      }
      return this.getBlockingActorAt(pt) === null;
    });

    if (validOutsideSight.length === 0) {
      return null;
    }

    const idx = Math.floor(this.nextRandom() * validOutsideSight.length);
    const pos = validOutsideSight[Math.min(validOutsideSight.length - 1, Math.max(0, idx))];
    const enemy = createWeightedEnemy(
      `enemy_${++this.spawnedEnemyCounter}`,
      pos,
      this.nextRandom()
    );
    this.addEnemy(enemy);
    return enemy;
  }

  public addItem(item: Item): Item {
    if (isPotionItem(item)) {
      item.spriteKey = this.getPotionColorEntry(item.itemTypeId).spriteKey;
    }
    if (item.stackable) {
      const existing = this.items.find(
        (groundItem) =>
          pointsEqual(groundItem.position, item.position) && groundItem.canStackWith(item)
      );
      if (existing) {
        existing.amount += item.amount;
        return existing;
      }
    }
    this.items.push(item);
    return item;
  }

  /**
   * Removes up to `amount` units from the ground item stack at `indexAtTile` on tile `pos`.
   * Returns a detached Item instance representing the removed stack, or null if invalid.
   */
  public removeGroundItemAt(pos: Point, indexAtTile: number, amount = 1): Item | null {
    const tileItems = this.getItemsAt(pos);
    if (indexAtTile < 0 || indexAtTile >= tileItems.length) {
      return null;
    }

    const target = tileItems[indexAtTile];
    const removeCount = Math.max(1, Math.min(Math.floor(amount), target.amount));

    if (removeCount >= target.amount) {
      const globalIdx = this.items.indexOf(target);
      if (globalIdx !== -1) {
        this.items.splice(globalIdx, 1);
      }
      return target;
    }

    target.amount -= removeCount;
    return target.cloneWithAmount(
      removeCount,
      `${target.id}_ground_split_${++this.splitItemCounter}`
    );
  }

  /**
   * Transfers up to `requestedAmount` units of the ground item stack at `indexAtTile` on
   * `actor.position` into `actor.inventory`, enforcing the 1.5x maxCarryWeight hard cap.
   */
  public pickupGroundItemAt(
    actor: Actor,
    indexAtTile: number,
    requestedAmount = 1
  ): PickupItemResolution {
    const tileItems = this.getItemsAt(actor.position);
    if (indexAtTile < 0 || indexAtTile >= tileItems.length) {
      return { status: 'NONE', pickedItem: null };
    }

    const target = tileItems[indexAtTile];
    const desiredAmount = Math.max(1, Math.min(Math.floor(requestedAmount), target.amount));
    const affordableAmount = actor.getMaxPickupAmount(target.weight, desiredAmount);

    if (affordableAmount <= 0) {
      const displayItemName = this.getItemDisplayNameForLog(target);
      const msg = actor.isPlayer
        ? `You cannot carry ${displayItemName} — too heavy!`
        : `${actor.name} cannot carry ${displayItemName} — too heavy!`;
      this.eventBus.log(msg, 'info', this.timeline.currentTime, 'tooHeavyToCarry', {
        actor: actor.logName,
        item: displayItemName,
      });
      return { status: 'TOO_HEAVY', pickedItem: null };
    }

    const removed = this.removeGroundItemAt(actor.position, indexAtTile, affordableAmount);
    if (!removed) {
      return { status: 'NONE', pickedItem: null };
    }

    actor.inventory.addItem(removed);
    return { status: 'PICKED_UP', pickedItem: removed };
  }

  public removeGroundItemById(itemId: string, amount = 1): Item | null {
    const idx = this.items.findIndex((i) => i.id === itemId);
    if (idx === -1) {
      return null;
    }
    const target = this.items[idx];
    const removeCount = Math.max(1, Math.min(Math.floor(amount), target.amount));
    if (removeCount >= target.amount) {
      this.items.splice(idx, 1);
      return target;
    }
    target.amount -= removeCount;
    return target.cloneWithAmount(
      removeCount,
      `${target.id}_ground_split_${++this.splitItemCounter}`
    );
  }

  public pickupSpecificGroundItem(
    actor: Actor,
    itemId: string,
    requestedAmount = 1
  ): PickupItemResolution {
    const tileItems = this.getItemsAt(actor.position);
    const indexAtTile = tileItems.findIndex((i) => i.id === itemId);
    if (indexAtTile === -1) {
      return { status: 'NONE', pickedItem: null };
    }
    return this.pickupGroundItemAt(actor, indexAtTile, requestedAmount);
  }

  /**
   * Drops up to `requestedAmount` units from `actor.inventory` at `inventoryIndex`
   * onto `actor.position` on the ground.
   */
  public dropInventoryItemAt(actor: Actor, inventoryIndex: number, requestedAmount = 1): Item | null {
    const removed = actor.inventory.removeItemAt(inventoryIndex, requestedAmount);
    if (!removed) {
      return null;
    }
    removed.position = { ...actor.position };
    this.addItem(removed);
    return removed;
  }

  public dropSpecificInventoryItem(
    actor: Actor,
    itemId: string,
    requestedAmount = 1
  ): Item | null {
    const removed = actor.inventory.removeItemById(itemId, requestedAmount);
    if (!removed) {
      return null;
    }
    removed.position = { ...actor.position };
    this.addItem(removed);
    return removed;
  }

  /**
   * Rolls `enemy.meatDropChance` (default 20%) when `enemy.dropsMeat` is true upon defeat,
   * dropping a fresh `MeatItem` on the defeated enemy's tile.
   */
  public tryDropEnemyMeat(enemy: Enemy): MeatItem | null {
    if (!enemy.dropsMeat || enemy.meatDropChance <= 0) {
      return null;
    }
    if (this.nextRandom() >= enemy.meatDropChance) {
      return null;
    }
    const meat = new MeatItem({
      id: `meat_${enemy.id}_${this.timeline.currentTime}_${++this.splitItemCounter}`,
      position: { ...enemy.position },
      sourceArchetypeId: enemy.archetypeId,
      sourceEnemyName: enemy.name,
      baseSatietyValue: enemy.meatSatietyValue,
      weight: enemy.meatWeight,
      createdAtTime: this.timeline.currentTime,
    });
    this.addItem(meat);
    return meat;
  }

  /**
   * Sweeps all perishable `MeatItem`s in `player.inventory` and `this.items`:
   * - Updates sprites when crossing 100 turns into 'rotten'.
   * - Deletes items older than 200 turns ('rotted_away'), logging when in player inventory
   *   or on a VISIBLE ground tile, and deleting silently when out of sight.
   */
  public processPerishableDecay(exemptItemId?: string): void {
    const now = this.timeline.currentTime;

    // 1. Player inventory perishable check
    const rottedBagCounts = new Map<string, number>();
    const invSnapshot = [...this.player.inventory.getItems()];
    for (const item of invSnapshot) {
      if (!isMeatItem(item) || item.id === exemptItemId) {
        continue;
      }
      const freshness = item.getFreshness(now);
      if (freshness === 'rotted_away') {
        this.player.inventory.removeItemById(item.id, item.amount);
        rottedBagCounts.set(item.name, (rottedBagCounts.get(item.name) ?? 0) + item.amount);
      } else {
        item.syncSprite(now);
      }
    }

    if (rottedBagCounts.size > 0) {
      const itemsSummary = Array.from(rottedBagCounts.entries())
        .map(([name, count]) => (count > 1 ? `${name} x${count}` : name))
        .join(', ');
      this.eventBus.log(
        `Your ${itemsSummary} rotted away!`,
        'info',
        now,
        'meatRottedInBag',
        { items: itemsSummary }
      );
    }

    // 2. Ground items perishable check
    const rottedVisibleGroundCounts = new Map<string, number>();
    for (let i = this.items.length - 1; i >= 0; i--) {
      const item = this.items[i];
      if (!isMeatItem(item) || item.id === exemptItemId) {
        continue;
      }
      const freshness = item.getFreshness(now);
      if (freshness === 'rotted_away') {
        const visible = this.isTileVisible(item.position);
        this.items.splice(i, 1);
        if (visible) {
          rottedVisibleGroundCounts.set(
            item.name,
            (rottedVisibleGroundCounts.get(item.name) ?? 0) + item.amount
          );
        }
      } else {
        item.syncSprite(now);
      }
    }

    if (rottedVisibleGroundCounts.size > 0) {
      const itemsSummary = Array.from(rottedVisibleGroundCounts.entries())
        .map(([name, count]) => (count > 1 ? `${name} x${count}` : name))
        .join(', ');
      this.eventBus.log(
        `${itemsSummary} on the ground rotted away.`,
        'info',
        now,
        'meatRottedOnGround',
        { items: itemsSummary }
      );
    }
  }

  /**
   * Executes stationary multi-turn food consumption (`5–10` standard turns):
   * - Pauses passive Satiety drain while eating and snapshots freshness at bite start.
   * - Halts immediately if the player takes HP damage (food is NOT consumed and Satiety is unchanged).
   * - On full completion, consumes 1 unit, restores 100% (Fresh) or 50% (Rotten) Satiety,
   *   and if Rotten permanently decreases 1 random primary attribute (excluding LUK) by -1.
   */
  public eatFoodItem(food: FoodItem, source: ItemLocationSource): EatFoodResolution {
    if (!this.player.canEatFood()) {
      this.eventBus.log(
        'You are too full to eat anything!',
        'info',
        this.timeline.currentTime,
        'tooFullToEat'
      );
      return { status: 'TOO_FULL', turnsElapsed: 0, satietyGained: 0 };
    }

    const existsInSource =
      source === 'inventory'
        ? this.player.inventory.getItems().some((i) => i.id === food.id)
        : this.getItemsAt(this.player.position).some((i) => i.id === food.id);
    if (!existsInSource) {
      return { status: 'MISSING', turnsElapsed: 0, satietyGained: 0 };
    }

    const snapshotFreshness: 'fresh' | 'rotten' =
      isMeatItem(food) && food.getFreshness(this.timeline.currentTime) === 'rotten'
        ? 'rotten'
        : 'fresh';

    const eatTurns = this.rng.nextInt(food.eatMinTurns, food.eatMaxTurns);
    this.eventBus.log(
      `You start eating ${food.name}...`,
      'info',
      this.timeline.currentTime,
      'startEatingFood',
      { item: food.name }
    );

    let turnsElapsed = 0;
    let interruptedByDamage = false;
    this.player.pauseSatietyDrain = true;

    try {
      for (let i = 0; i < eatTurns; i++) {
        if (!this.player.isAlive()) {
          interruptedByDamage = true;
          break;
        }
        const damageBefore = this.runStats.damageTaken;
        const hpBefore = this.player.stats.hp;
        const turnStart = this.timeline.currentTime;

        this.player.lastActionSpRegenMultiplier = 0.5;
        this.timeline.recordAction(this.player, DEFAULT_ACTION_TIME_COST);
        turnsElapsed += 1;

        if (this.player.isAlive()) {
          this.processEnemyTurnsUntilPlayer();
        }
        this.processTickCycleSpawning(turnStart, this.timeline.currentTime);
        this.recomputeFOV();
        this.processPerishableDecay(food.id);

        const tookDamage =
          !this.player.isAlive() ||
          this.runStats.damageTaken > damageBefore ||
          this.player.stats.hp < hpBefore;
        if (tookDamage) {
          interruptedByDamage = true;
          break;
        }
      }
    } finally {
      this.player.pauseSatietyDrain = false;
    }

    if (interruptedByDamage) {
      if (this.player.isAlive()) {
        this.eventBus.log(
          `You took damage and stopped eating ${food.name}!`,
          'combat',
          this.timeline.currentTime,
          'eatingInterruptedByDamage',
          { item: food.name }
        );
      }
      this.processPerishableDecay();
      return { status: 'INTERRUPTED', turnsElapsed, satietyGained: 0 };
    }

    // Consume 1 unit from the chosen source
    if (source === 'inventory') {
      this.player.inventory.removeItemById(food.id, 1);
    } else {
      this.removeGroundItemById(food.id, 1);
    }

    const satietyGain =
      snapshotFreshness === 'rotten'
        ? Math.max(1, Math.floor(food.baseSatietyValue * 0.5))
        : food.baseSatietyValue;

    this.eventBus.log(
      `You finish eating ${food.name}.`,
      'info',
      this.timeline.currentTime,
      'finishEatingFood',
      { item: food.name }
    );

    this.player.modifySatiety(satietyGain);

    let decreasedAttribute: PrimaryAttributeKey | undefined;
    if (snapshotFreshness === 'rotten') {
      const candidates: PrimaryAttributeKey[] = ['str', 'con', 'int', 'wis', 'agi'];
      const chosenAttr = candidates[this.rng.nextInt(0, candidates.length - 1)];
      const oldVal = this.player.baseAttributes[chosenAttr];
      const newVal = Math.max(1, oldVal - 1);
      decreasedAttribute = chosenAttr;
      this.player.setBaseAttributes({ [chosenAttr]: newVal }, false);
      this.eventBus.log(
        `The rotten ${food.name} makes you sick! Your ${chosenAttr.toUpperCase()} decreased! (${oldVal} → ${newVal})`,
        'combat',
        this.timeline.currentTime,
        'rottenMeatSickness',
        {
          actor: this.player.logName,
          item: food.name,
          attr: chosenAttr,
          oldVal,
          newVal,
        }
      );
    }

    this.processPerishableDecay();
    return {
      status: 'COMPLETED',
      turnsElapsed,
      satietyGained: satietyGain,
      decreasedAttribute,
    };
  }

  /**
   * Quaffs 1 unit of a potion from `player.inventory` ('q' Potion Tab):
   * - Consumes 1 bottle, applies primary effect, grants +10 Satiety, and costs 1 character turn (100 base ticks).
   * - Strict observable-effect identification: marks `potion.itemTypeId` as identified iff `observableEffect` is true.
   * - If `deferParalysisTicks` is false (default), automatically drains any inflicted player paralysis turns synchronously;
   *   if true (browser UI), leaves `player.paralysisTurns > 0` so `InputController` can tick the ~120ms/turn visual countdown.
   */
  public quaffInventoryPotion(
    potionId: string,
    options?: { readonly deferParalysisTicks?: boolean }
  ): QuaffPotionResolution {
    const found = this.player.inventory
      .getItems()
      .find((item) => item.id === potionId && isPotionItem(item));
    if (!found || !isPotionItem(found)) {
      return {
        status: 'MISSING',
        observableEffect: false,
        newlyIdentified: false,
        amountRestored: 0,
        satietyGained: 0,
      };
    }

    const displayNameBefore = this.getItemDisplayNameForLog(found);
    const removed = this.player.inventory.removeItemById(found.id, 1);
    if (!removed) {
      return {
        status: 'MISSING',
        observableEffect: false,
        newlyIdentified: false,
        amountRestored: 0,
        satietyGained: 0,
      };
    }

    const effect = found.applyQuaffEffect(this.player, this.rng);
    let newlyIdentified = false;
    let statKey: PotionStatKey | undefined;
    let amountRestored = 0;
    let paralysisTurnsAdded: number | undefined;

    if (effect.kind === 'paralysis') {
      paralysisTurnsAdded = effect.paralysisTurnsAdded;
      if (effect.observableEffect && effect.paralysisTurnsAdded > 0) {
        newlyIdentified = this.identifyItemType(found.itemTypeId);
        if (newlyIdentified) {
          this.eventBus.log(
            `You quaff ${displayNameBefore} and become paralyzed for ${effect.paralysisTurnsAdded} turns! It was ${found.name}!`,
            'combat',
            this.timeline.currentTime,
            'quaffAndIdentifyParalyze',
            {
              item: displayNameBefore,
              turns: effect.paralysisTurnsAdded,
              trueItem: found.name,
            }
          );
        } else {
          this.eventBus.log(
            `You quaff ${found.name} and become paralyzed for ${effect.paralysisTurnsAdded} turns!`,
            'combat',
            this.timeline.currentTime,
            'quaffParalyzeEffect',
            {
              item: found.name,
              turns: effect.paralysisTurnsAdded,
            }
          );
        }
      } else {
        this.eventBus.log(
          `You quaff ${displayNameBefore}, but nothing noticeable happens.`,
          'info',
          this.timeline.currentTime,
          'quaffNothingHappens',
          { item: displayNameBefore }
        );
      }
    } else {
      statKey = effect.statKey;
      amountRestored = effect.amountRestored;
      if (effect.observableEffect && effect.amountRestored > 0) {
        newlyIdentified = this.identifyItemType(found.itemTypeId);
        const statUpper = effect.statKey.toUpperCase();
        if (newlyIdentified) {
          this.eventBus.log(
            `You quaff ${displayNameBefore} and recover ${effect.amountRestored} ${statUpper}! It was ${found.name}!`,
            'info',
            this.timeline.currentTime,
            'quaffAndIdentifyPotion',
            {
              item: displayNameBefore,
              amount: effect.amountRestored,
              stat: effect.statKey,
              trueItem: found.name,
            }
          );
        } else {
          this.eventBus.log(
            `You quaff ${found.name} and recover ${effect.amountRestored} ${statUpper}.`,
            'info',
            this.timeline.currentTime,
            'quaffPotionEffect',
            {
              item: found.name,
              amount: effect.amountRestored,
              stat: effect.statKey,
            }
          );
        }
      } else {
        this.eventBus.log(
          `You quaff ${displayNameBefore}, but nothing noticeable happens.`,
          'info',
          this.timeline.currentTime,
          'quaffNothingHappens',
          {
            item: displayNameBefore,
          }
        );
      }
    }

    const satBefore = this.player.satiety;
    this.player.modifySatiety(found.quaffSatietyBonus);
    const satietyGained = Math.max(0, Number((this.player.satiety - satBefore).toFixed(3)));

    this.advancePlayerTurn(DEFAULT_ACTION_TIME_COST, 0.5);

    if (!options?.deferParalysisTicks && this.player.isAlive() && this.player.isParalyzed()) {
      this.drainAllPlayerParalysisTurns();
    }

    return {
      status: 'QUAFFED',
      observableEffect: effect.observableEffect,
      newlyIdentified,
      statKey,
      amountRestored,
      paralysisTurnsAdded,
      satietyGained,
    };
  }

  /**
   * Returns the smart auto-aim initial cursor position for Throw Targeting Mode ('f'):
   * - Snaps to the nearest living `VISIBLE` enemy if one exists.
   * - Otherwise defaults to `player.position` ('@').
   */
  public getInitialThrowTarget(): Point {
    const visibleEnemies = this.getVisibleEnemies();
    if (visibleEnemies.length === 0) {
      return { ...this.player.position };
    }
    const px = this.player.position.x;
    const py = this.player.position.y;
    const sorted = [...visibleEnemies].sort((a, b) => {
      const chebA = Math.max(Math.abs(a.position.x - px), Math.abs(a.position.y - py));
      const chebB = Math.max(Math.abs(b.position.x - px), Math.abs(b.position.y - py));
      if (chebA !== chebB) return chebA - chebB;
      const distSqA = (a.position.x - px) ** 2 + (a.position.y - py) ** 2;
      const distSqB = (b.position.x - px) ** 2 + (b.position.y - py) ** 2;
      if (distSqA !== distSqB) return distSqA - distSqB;
      return a.id.localeCompare(b.id);
    });
    return { ...sorted[0].position };
  }

  /**
   * Traces the projectile flight ray from `player.position` toward `targetPos`:
   * - Self-firing (`targetPos === player.position`) hits `player` directly (`flightPath = []`).
   * - Otherwise steps along `computeBresenhamLine`, stopping at the first living Enemy (`100%` hit)
   *   or on the last passable tile immediately before an impassable WALL / CLOSED door.
   */
  public computeThrowTrajectory(targetPos: Point): ThrowTrajectory {
    const origin = { ...this.player.position };
    const targetCursor = { ...targetPos };

    if (pointsEqual(origin, targetCursor)) {
      return {
        origin,
        targetCursor,
        flightPath: [],
        impactTile: { ...origin },
        hitActor: this.player.isAlive() ? this.player : null,
        blockedByObstacle: false,
      };
    }

    const ray = computeBresenhamLine(origin, targetCursor);
    const flightPath: Point[] = [];
    let lastPassable: Point = { ...origin };

    for (const step of ray) {
      const tile = this.map.getTile(step.x, step.y);
      if (!tile || !tile.isPassable()) {
        return {
          origin,
          targetCursor,
          flightPath,
          impactTile: { ...lastPassable },
          hitActor: null,
          blockedByObstacle: true,
        };
      }

      flightPath.push({ ...step });
      lastPassable = { ...step };

      const actorAtStep = this.getBlockingActorAt(step);
      if (actorAtStep && !actorAtStep.isPlayer && actorAtStep.isAlive()) {
        return {
          origin,
          targetCursor,
          flightPath,
          impactTile: { ...step },
          hitActor: actorAtStep,
          blockedByObstacle: false,
        };
      }
    }

    return {
      origin,
      targetCursor,
      flightPath,
      impactTile: { ...lastPassable },
      hitActor: null,
      blockedByObstacle: false,
    };
  }

  /**
   * Executes the 'f' Throw Action for 1 unit of `itemId` from `player.inventory` toward `targetPos`:
   * - Requires `5 SP` (`THROW_SP_COST`); costs `1` character turn (`baseTimeCost = 100` scaled by `player.speed`, `0%` SP regen).
   * - Grants `+3 AGI XP` (`0.6 * 5 SP`) ONLY when hitting a living hostile `Enemy` (anti-farming).
   * - Alerts any hit `Enemy` (`alertedTurns = 15`) so it senses and chases the player outside `sensingRange`.
   * - `PotionItem`: shatters on impact (destroyed, no +10 Satiety); applies primary effect to hit `Actor`
   *   and identifies the potion iff `isTileVisible(impactTile) && observableEffect`.
   * - Non-potion `Item`: applies `applyThrowHit` (`0 HP` default damage) and drops `1` unit onto `impactTile`.
   */
  public throwInventoryItem(
    itemId: string,
    targetPos: Point,
    options?: { readonly deferParalysisTicks?: boolean }
  ): ThrowItemResolution {
    if (this.player.stats.sp < THROW_SP_COST) {
      this.eventBus.log(
        'Not enough stamina (SP)!',
        'combat',
        this.timeline.currentTime,
        'notEnoughStamina',
        {
          actor: this.player.logName,
          required: THROW_SP_COST,
        }
      );
      return {
        status: 'NO_SP',
        hitActor: null,
        shattered: false,
        droppedItem: null,
        observableEffect: false,
        newlyIdentified: false,
        amountRestored: 0,
        damageDealt: 0,
      };
    }

    const found = this.player.inventory.getItems().find((i) => i.id === itemId);
    if (!found) {
      return {
        status: 'MISSING',
        hitActor: null,
        shattered: false,
        droppedItem: null,
        observableEffect: false,
        newlyIdentified: false,
        amountRestored: 0,
        damageDealt: 0,
      };
    }

    const now = this.timeline.currentTime;
    const rawFreshness = isMeatItem(found) ? found.getFreshness(now) : undefined;
    const meatFreshness: 'fresh' | 'rotten' | undefined =
      rawFreshness === 'rotten' ? 'rotten' : rawFreshness === 'fresh' ? 'fresh' : undefined;
    const displayNameBefore = this.getItemDisplayNameForLog(found, meatFreshness);
    const spriteKey = this.getItemEffectiveSpriteKey(found);
    const trajectory = this.computeThrowTrajectory(targetPos);

    const thrownUnit = this.player.inventory.removeItemById(found.id, 1);
    if (!thrownUnit) {
      return {
        status: 'MISSING',
        hitActor: null,
        shattered: false,
        droppedItem: null,
        observableEffect: false,
        newlyIdentified: false,
        amountRestored: 0,
        damageDealt: 0,
      };
    }

    const hitActor = trajectory.hitActor;
    const hitLivingEnemy = Boolean(hitActor && !hitActor.isPlayer && hitActor.isAlive());

    // Spend 5 SP (0% SP recovery); exercise AGI (+3 XP) strictly when hitting a living hostile enemy
    this.player.consumeSp(THROW_SP_COST, hitLivingEnemy);

    if (hitLivingEnemy && hitActor) {
      (hitActor as Enemy).alertToPlayer(DEFAULT_ENEMY_ALERTED_TURNS);
    }

    let shattered = false;
    let droppedItem: Item | null = null;
    let observableEffect = false;
    let newlyIdentified = false;
    let statKey: PotionStatKey | undefined;
    let amountRestored = 0;
    let paralysisTurnsAdded: number | undefined;
    let damageDealt = 0;

    if (isPotionItem(thrownUnit)) {
      shattered = true;
      if (hitActor && hitActor.isAlive()) {
        const effect = thrownUnit.applyThrowEffect(hitActor, this.rng);
        observableEffect = effect.observableEffect;
        const canObserve = this.isTileVisible(trajectory.impactTile);

        if (effect.kind === 'paralysis') {
          paralysisTurnsAdded = effect.paralysisTurnsAdded;
          if (effect.observableEffect && effect.paralysisTurnsAdded > 0) {
            if (canObserve) {
              newlyIdentified = this.identifyItemType(thrownUnit.itemTypeId);
            }
            const knownNow = this.isItemIdentified(thrownUnit.itemTypeId);
            if (newlyIdentified) {
              this.eventBus.log(
                `You throw ${displayNameBefore} at ${hitActor.name} — ${hitActor.name} is paralyzed for ${effect.paralysisTurnsAdded} turns! It was ${thrownUnit.name}!`,
                'combat',
                now,
                'throwPotionIdentifyParalyze',
                {
                  item: displayNameBefore,
                  defender: hitActor.logName,
                  turns: effect.paralysisTurnsAdded,
                  trueItem: thrownUnit.name,
                }
              );
            } else {
              const shownName = knownNow ? thrownUnit.name : displayNameBefore;
              this.eventBus.log(
                `You throw ${shownName} at ${hitActor.name} — ${hitActor.name} is paralyzed for ${effect.paralysisTurnsAdded} turns!`,
                'combat',
                now,
                'throwPotionParalyze',
                {
                  item: shownName,
                  defender: hitActor.logName,
                  turns: effect.paralysisTurnsAdded,
                }
              );
            }
          } else {
            this.eventBus.log(
              `You throw ${displayNameBefore} at ${hitActor.name}, and the vial shatters with no noticeable effect.`,
              'info',
              now,
              'throwPotionNoEffect',
              {
                item: displayNameBefore,
                defender: hitActor.logName,
              }
            );
          }
        } else {
          statKey = effect.statKey;
          amountRestored = effect.amountRestored;
          if (effect.observableEffect && effect.amountRestored > 0) {
            if (canObserve) {
              newlyIdentified = this.identifyItemType(thrownUnit.itemTypeId);
            }
            const knownNow = this.isItemIdentified(thrownUnit.itemTypeId);
            const statUpper = effect.statKey.toUpperCase();
            if (newlyIdentified) {
              this.eventBus.log(
                `You throw ${displayNameBefore} at ${hitActor.name} — ${hitActor.name} recovers ${effect.amountRestored} ${statUpper}! It was ${thrownUnit.name}!`,
                'info',
                now,
                'throwPotionIdentifyRestore',
                {
                  item: displayNameBefore,
                  defender: hitActor.logName,
                  amount: effect.amountRestored,
                  stat: effect.statKey,
                  trueItem: thrownUnit.name,
                }
              );
            } else {
              const shownName = knownNow ? thrownUnit.name : displayNameBefore;
              this.eventBus.log(
                `You throw ${shownName} at ${hitActor.name} — ${hitActor.name} recovers ${effect.amountRestored} ${statUpper}!`,
                'info',
                now,
                'throwPotionRestore',
                {
                  item: shownName,
                  defender: hitActor.logName,
                  amount: effect.amountRestored,
                  stat: effect.statKey,
                }
              );
            }
          } else {
            this.eventBus.log(
              `You throw ${displayNameBefore} at ${hitActor.name}, and the vial shatters with no noticeable effect.`,
              'info',
              now,
              'throwPotionNoEffect',
              {
                item: displayNameBefore,
                defender: hitActor.logName,
              }
            );
          }
        }
      } else {
        this.eventBus.log(
          `You throw ${displayNameBefore}, and the vial shatters on impact.`,
          'info',
          now,
          'throwPotionShatterFloor',
          { item: displayNameBefore }
        );
      }
    } else {
      // General non-potion item: apply throw hit hook (0 damage default) and drop 1 unit onto impactTile
      if (hitActor && hitActor.isAlive()) {
        const hitRes = thrownUnit.applyThrowHit(hitActor, this.rng);
        const rawDamage = Math.max(0, Math.floor(hitRes.damageDealt));
        if (rawDamage > 0) {
          const actualDamage = Math.min(hitActor.stats.hp, rawDamage);
          hitActor.stats.hp = Math.max(0, hitActor.stats.hp - rawDamage);
          damageDealt = actualDamage;
          if (!hitActor.isPlayer) {
            this.recordDamageDealt(actualDamage);
          } else {
            this.recordDamageTaken(actualDamage, this.player);
          }
          this.eventBus.log(
            `You throw ${displayNameBefore} and hit ${hitActor.name} for ${rawDamage} damage!`,
            'combat',
            now,
            'throwItemHitDamage',
            {
              item: displayNameBefore,
              defender: hitActor.logName,
              damage: rawDamage,
            }
          );
          if (!hitActor.isAlive()) {
            this.eventBus.log(
              hitActor.isPlayer ? 'You are defeated!' : `${hitActor.name} is defeated!`,
              'combat',
              now,
              'actorDefeated',
              { defender: hitActor.logName }
            );
            if (!hitActor.isPlayer) {
              const defeatedEnemy = hitActor as Enemy;
              this.recordEnemyDefeated(defeatedEnemy);
              this.tryDropEnemyMeat(defeatedEnemy);
              this.removeEnemy(defeatedEnemy.id);
            }
          } else if (actualDamage > 0) {
            hitActor.exerciseAttribute(
              'con',
              actualDamage * ATTRIBUTE_EXERCISE_GAINS.conXpPerHpLost
            );
          }
        } else {
          this.eventBus.log(
            `You throw ${displayNameBefore} and hit ${hitActor.name}!`,
            'combat',
            now,
            'throwItemHitNoDamage',
            {
              item: displayNameBefore,
              defender: hitActor.logName,
            }
          );
        }
      } else {
        this.eventBus.log(
          `You throw ${displayNameBefore}.`,
          'info',
          now,
          'throwItemLanded',
          { item: displayNameBefore }
        );
      }

      thrownUnit.position = { ...trajectory.impactTile };
      droppedItem = this.addItem(thrownUnit);
    }

    // Advance 1 character turn (100 base ticks scaled by player.speed, 0% SP regen)
    this.advancePlayerTurn(DEFAULT_ACTION_TIME_COST, 0);

    if (!options?.deferParalysisTicks && this.player.isAlive() && this.player.isParalyzed()) {
      this.drainAllPlayerParalysisTurns();
    }

    return {
      status: 'THROWN',
      trajectory,
      spriteKey,
      hitActor,
      shattered,
      droppedItem,
      observableEffect,
      newlyIdentified,
      statKey,
      amountRestored,
      paralysisTurnsAdded,
      damageDealt,
    };
  }

  /**
   * Advances 1 stationary paralyzed turn (100 raw ticks, 100% SP regen) for the player,
   * decrementing `player.paralysisTurns` by 1 and processing enemy turns, FOV, spawning, and decay.
   * Returns `true` if the player is still alive AND still paralyzed (`paralysisTurns > 0`).
   */
  public stepPlayerParalysisTurn(): boolean {
    if (!this.player.isAlive() || !this.player.isParalyzed()) {
      return false;
    }

    const turnStart = this.timeline.currentTime;
    const remainingAfterStep = this.player.decrementParalysisTurn();
    this.player.lastActionSpRegenMultiplier = 1;
    this.timeline.recordRawTicks(this.player, DEFAULT_ACTION_TIME_COST);

    if (this.player.isAlive()) {
      this.processEnemyTurnsUntilPlayer();
      this.recomputeFOV();
      this.processTickCycleSpawning(turnStart, this.timeline.currentTime);
      this.processPerishableDecay();
      if (this.player.isAlive() && remainingAfterStep === 0) {
        this.eventBus.log(
          'The paralysis wears off — you can move again.',
          'info',
          this.timeline.currentTime,
          'paralysisWoreOff'
        );
      }
    } else {
      this.recomputeFOV();
      this.processPerishableDecay();
    }

    return this.player.isAlive() && this.player.isParalyzed();
  }

  /**
   * Synchronously drains all remaining `player.paralysisTurns` one turn at a time
   * (stopping early if the player dies).
   */
  public drainAllPlayerParalysisTurns(): number {
    let steps = 0;
    let safety = 1000;
    while (safety-- > 0 && this.player.isAlive() && this.player.isParalyzed()) {
      steps += 1;
      this.stepPlayerParalysisTurn();
    }
    return steps;
  }

  /**
   * Advances the player's turn on the timeline by `baseTimeCost` ticks and runs any
   * scheduled enemy turns, FOV updates, and per-tick-cycle dynamic enemy spawning.
   */
  public advancePlayerTurn(
    baseTimeCost = 100,
    spRegenMultiplier: SpRegenMultiplier = 0.5,
    isFoodConsumption = false
  ): void {
    if (baseTimeCost <= 0) {
      return;
    }
    const prevTime = this.timeline.currentTime;
    this.player.lastActionSpRegenMultiplier = spRegenMultiplier;
    this.timeline.recordAction(this.player, baseTimeCost);
    if (this.player.isAlive()) {
      this.processEnemyTurnsUntilPlayer();
      this.recomputeFOV();
      this.processTickCycleSpawning(prevTime, this.timeline.currentTime);
      this.processPerishableDecay();
      if (this.player.isAlive() && !isFoodConsumption && !this.player.isParalyzed()) {
        this.maybeTriggerFaintEpisode();
      }
    } else {
      this.recomputeFOV();
      this.processPerishableDecay();
    }
  }

  public getBlockingActorAt(pos: Point): Actor | null {
    if (this.player.isAlive() && pointsEqual(this.player.position, pos)) {
      return this.player;
    }
    for (const enemy of this.enemies) {
      if (enemy.isAlive() && pointsEqual(enemy.position, pos)) {
        return enemy;
      }
    }
    return null;
  }

  public getItemsAt(pos: Point): Item[] {
    return this.items.filter((item) => pointsEqual(item.position, pos));
  }

  public hasAnyEntityAt(pos: Point): boolean {
    return this.getBlockingActorAt(pos) !== null || this.getItemsAt(pos).length > 0;
  }

  /**
   * Executes a player action and advances the timeline (including any scheduled AI turns
   * and per-tick-cycle dynamic enemy spawning) when the action succeeds and consumes time.
   */
  public performPlayerAction(action: Action): ActionResult {
    const prevTime = this.timeline.currentTime;
    const result = action.execute(this.player, this);
    if (result.success && result.timeCost > 0) {
      this.timeline.recordAction(this.player, result.timeCost);
      if (this.player.isAlive()) {
        this.processEnemyTurnsUntilPlayer();
        this.recomputeFOV();
        this.processTickCycleSpawning(prevTime, this.timeline.currentTime);
        this.processPerishableDecay();
        if (this.player.isAlive() && !action.isFoodConsumption && !this.player.isParalyzed()) {
          this.maybeTriggerFaintEpisode();
        }
      } else {
        this.recomputeFOV();
        this.processPerishableDecay();
      }
    }
    return result;
  }

  /**
   * When the player is in the 'faint' hunger state (-100 <= satiety <= 0), rolls a 20% chance
   * to faint for 3–10 turns, advancing the dungeon timeline 1 turn (100 ticks) at a time while
   * halting immediately if the player dies from an enemy attack or starvation.
   */
  private maybeTriggerFaintEpisode(): void {
    if (!this.player.isAlive() || this.player.satietyState !== 'faint') {
      return;
    }
    if (this.nextRandom() >= FAINT_PROC_PROBABILITY) {
      return;
    }

    const faintTurns = this.rng.nextInt(FAINT_MIN_TURNS, FAINT_MAX_TURNS);
    this.eventBus.log(
      `You faint from hunger for ${faintTurns} turns!`,
      'combat',
      this.timeline.currentTime,
      'faintedFromHunger',
      { turns: faintTurns }
    );

    for (let i = 0; i < faintTurns; i++) {
      if (!this.player.isAlive()) {
        break;
      }
      const turnStart = this.timeline.currentTime;
      this.player.lastActionSpRegenMultiplier = 1;
      this.timeline.recordRawTicks(this.player, DEFAULT_ACTION_TIME_COST);
      if (!this.player.isAlive()) {
        break;
      }
      this.processEnemyTurnsUntilPlayer();
      if (!this.player.isAlive()) {
        break;
      }
      this.processTickCycleSpawning(turnStart, this.timeline.currentTime);
      this.processPerishableDecay();
    }
    this.recomputeFOV();
  }

  /**
   * Executes the 'F' -> '.' / '@' Self-Attack command:
   * - Costs 10 SP (0% SP recovery) and 1 character turn (scaled by player.speed).
   * - Guaranteed hit (100% hit, never misses, no crit), dealing mitigated physical damage.
   * - Exercises AGI (+6 XP) and CON (1.5 * actualHpLost if surviving), while NOT exercising STR (0 STR XP)
   *   and NOT incrementing `runStats.damageDealt`.
   */
  public attackSelf(): ActionResult {
    if (!this.player.isAlive()) {
      return { success: false, timeCost: 0, message: 'Player is no longer alive.' };
    }

    // Spend 10 SP and exercise AGI (+6 XP), setting 0% SP recovery; STR is NOT exercised
    if (!this.player.consumeSp(MELEE_SP_COST, true)) {
      const noSpMsg = 'Not enough stamina (SP)!';
      this.eventBus.log(noSpMsg, 'combat', this.timeline.currentTime, 'notEnoughStamina', {
        actor: this.player.logName,
        required: MELEE_SP_COST,
      });
      return { success: false, timeCost: 0, message: noSpMsg };
    }

    const selfDamage = Math.max(
      1,
      Math.floor(this.player.stats.physicalAttack - this.player.stats.physicalDefense * 0.5)
    );
    const actualDamage = Math.min(this.player.stats.hp, selfDamage);
    this.player.stats.hp = Math.max(0, this.player.stats.hp - selfDamage);
    this.recordDamageTaken(actualDamage, this.player);

    const message = `You attack yourself for ${selfDamage} damage.`;
    this.eventBus.log(message, 'combat', this.timeline.currentTime, 'attackSelf', {
      actor: this.player.logName,
      damage: selfDamage,
    });

    if (!this.player.isAlive()) {
      this.eventBus.log('You are defeated!', 'combat', this.timeline.currentTime, 'actorDefeated', {
        defender: this.player.logName,
      });
    } else if (actualDamage > 0) {
      this.player.exerciseAttribute('con', actualDamage * ATTRIBUTE_EXERCISE_GAINS.conXpPerHpLost);
    }

    this.advancePlayerTurn(DEFAULT_ACTION_TIME_COST, 0);
    return {
      success: true,
      timeCost: DEFAULT_ACTION_TIME_COST,
      message,
    };
  }

  /**
   * Executes the uppercase 'F' Directional Attack command:
   * - `(0, 0)` targets self via `attackSelf()`.
   * - Otherwise attempts a melee attack against `(player.x + dir.dx, player.y + dir.dy)` without moving.
   */
  public attackInDirection(dir: Pick<DirectionVector, 'dx' | 'dy'>): ActionResult {
    const dx = Math.sign(dir.dx);
    const dy = Math.sign(dir.dy);
    if (dx === 0 && dy === 0) {
      return this.attackSelf();
    }

    if (this.player.stats.sp < MELEE_SP_COST) {
      const noSpMsg = 'Not enough stamina (SP)!';
      this.eventBus.log(noSpMsg, 'combat', this.timeline.currentTime, 'notEnoughStamina', {
        actor: this.player.logName,
        required: MELEE_SP_COST,
      });
      return { success: false, timeCost: 0, message: noSpMsg };
    }

    const target: Point = {
      x: this.player.position.x + dx,
      y: this.player.position.y + dy,
    };

    const targetActor = this.getBlockingActorAt(target);
    if (targetActor && !targetActor.isPlayer && targetActor.isAlive()) {
      return this.performPlayerAction(new MeleeAttackAction(targetActor));
    }

    // Swinging at empty air spends 10 SP without exercising STR or AGI (anti-farming rule)
    this.player.consumeSp(MELEE_SP_COST, false);
    const message = 'You swing at empty air.';
    this.eventBus.log(
      message,
      'combat',
      this.timeline.currentTime,
      'attackEmptyAir',
      { actor: this.player.logName }
    );
    this.advancePlayerTurn(DEFAULT_ACTION_TIME_COST, 0);
    return {
      success: true,
      timeCost: DEFAULT_ACTION_TIME_COST,
      message,
    };
  }

  public dashPlayer(dir: Pick<DirectionVector, 'dx' | 'dy'>): ActionResult {
    return this.performPlayerAction(DashAction.fromDirection(dir));
  }

  public movePlayer(dir: DirectionVector): ActionResult {
    return this.performPlayerAction(MoveAction.fromDirection(dir));
  }

  public movePlayerByDelta(dx: number, dy: number): ActionResult {
    return this.performPlayerAction(new MoveAction(dx, dy));
  }

  /**
   * Returns all adjacent OPEN door coordinates around the player.
   */
  public getAdjacentOpenDoors(): Point[] {
    return this.map
      .getAdjacentPoints(this.player.position, true)
      .filter((pt) => this.map.getTile(pt.x, pt.y)?.isOpenDoor() ?? false);
  }

  /**
   * Handles the keyboard 'c' Close Door interaction:
   * - If a specific direction is provided, attempts to close the door in that direction.
   * - If 0 adjacent open doors exist, logs a message and returns NONE_NEARBY.
   * - If exactly 1 adjacent open door exists, closes it immediately.
   * - If 2+ adjacent open doors exist and no direction is given, returns NEEDS_DIRECTION.
   */
  public attemptCloseAdjacentDoor(direction?: DirectionVector): CloseDoorResolution {
    if (direction) {
      const target = {
        x: this.player.position.x + direction.dx,
        y: this.player.position.y + direction.dy,
      };
      const result = this.performPlayerAction(new DoorAction(target, 'CLOSE'));
      return {
        status: result.success ? 'CLOSED' : 'BLOCKED',
        result,
        candidateDoors: [target],
      };
    }

    const openDoors = this.getAdjacentOpenDoors();
    if (openDoors.length === 0) {
      this.eventBus.log(
        'There is no open door nearby to close.',
        'door',
        this.timeline.currentTime,
        'noOpenDoorNearby'
      );
      return { status: 'NONE_NEARBY', candidateDoors: [] };
    }

    if (openDoors.length === 1) {
      const target = openDoors[0];
      const result = this.performPlayerAction(new DoorAction(target, 'CLOSE'));
      return {
        status: result.success ? 'CLOSED' : 'BLOCKED',
        result,
        candidateDoors: openDoors,
      };
    }

    this.eventBus.log(
      'Multiple open doors nearby — press a direction arrow to choose which door to close (or Esc to cancel).',
      'door',
      this.timeline.currentTime,
      'multipleOpenDoorsNearby'
    );
    return {
      status: 'NEEDS_DIRECTION',
      candidateDoors: openDoors,
    };
  }

  private processEnemyTurnsUntilPlayer(): void {
    let safetyLimit = 100;
    while (safetyLimit-- > 0) {
      if (!this.player.isAlive()) {
        break;
      }

      const nextActor = this.timeline.peekNextActor();
      if (!nextActor || nextActor.isPlayer) {
        break;
      }

      const enemy = nextActor as Enemy;
      if (!enemy.isAlive()) {
        this.removeEnemy(enemy.id);
        continue;
      }

      if (enemy.isParalyzed()) {
        enemy.lastActionSpRegenMultiplier = 1;
        const remaining = enemy.decrementParalysisTurn();
        this.timeline.recordRawTicks(enemy, DEFAULT_ACTION_TIME_COST);
        if (remaining === 0 && enemy.isAlive() && this.isTileVisible(enemy.position)) {
          this.eventBus.log(
            `${enemy.name} is no longer paralyzed.`,
            'info',
            this.timeline.currentTime,
            'enemyParalysisRecovered',
            { actor: enemy.name }
          );
        }
        if (!this.player.isAlive()) {
          break;
        }
        continue;
      }

      const aiAction: Action = enemy.decideNextAction(this);
      const res = aiAction.execute(enemy, this);
      const cost = res.success && res.timeCost > 0 ? res.timeCost : 100;
      this.timeline.recordAction(enemy, cost);
      enemy.decrementAlertedTurn();

      if (!this.player.isAlive()) {
        break;
      }
    }
  }

  private processTickCycleSpawning(prevTime: number, newTime: number): void {
    const prevCycle = Math.floor(prevTime / 100);
    const newCycle = Math.floor(newTime / 100);
    const cyclesElapsed = Math.max(0, newCycle - prevCycle);
    for (let i = 0; i < cyclesElapsed; i++) {
      this.trySpawnDynamicEnemyOutsideSight();
    }
  }
}
