import { ConcreteItemOptions, Item, ItemProps } from './Item';

export const DEFAULT_EAT_MIN_TURNS = 5;
export const DEFAULT_EAT_MAX_TURNS = 10;

export interface FoodItemProps extends ItemProps {
  readonly baseSatietyValue: number;
  readonly eatMinTurns?: number;
  readonly eatMaxTurns?: number;
}

export interface FoodItemOptions extends ConcreteItemOptions {
  readonly baseSatietyValue?: number;
  readonly eatMinTurns?: number;
  readonly eatMaxTurns?: number;
}

/**
 * Base class for all edible food items that can be consumed via the 'e' Food Tab
 * to restore player Satiety over `eatMinTurns..eatMaxTurns` turns.
 */
export class FoodItem extends Item {
  public readonly isEdible = true as const;
  public readonly baseSatietyValue: number;
  public readonly eatMinTurns: number;
  public readonly eatMaxTurns: number;

  constructor(props: FoodItemProps) {
    super({
      ...props,
      itemType: props.itemType ?? 'consumable',
      spriteKey: props.spriteKey ?? 'item_meat_fresh',
    });
    this.baseSatietyValue = Math.max(1, Math.round(props.baseSatietyValue));
    this.eatMinTurns = Math.max(1, Math.round(props.eatMinTurns ?? DEFAULT_EAT_MIN_TURNS));
    this.eatMaxTurns = Math.max(
      this.eatMinTurns,
      Math.round(props.eatMaxTurns ?? DEFAULT_EAT_MAX_TURNS)
    );
  }

  public getEffectiveSatietyValue(_currentTimeTicks: number): number {
    return this.baseSatietyValue;
  }

  public getEffectiveSpriteKey(_currentTimeTicks: number): string {
    return this.spriteKey;
  }

  public override cloneWithAmount(newAmount: number, newId?: string): FoodItem {
    return new FoodItem({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      name: this.name,
      position: { ...this.position },
      itemTypeId: this.itemTypeId,
      itemType: this.itemType,
      spriteKey: this.spriteKey,
      amount: newAmount,
      weight: this.weight,
      stackable: this.stackable,
      description: this.description,
      baseSatietyValue: this.baseSatietyValue,
      eatMinTurns: this.eatMinTurns,
      eatMaxTurns: this.eatMaxTurns,
    });
  }

  public override serializeCustomData(): Record<string, unknown> {
    return {
      isFoodItem: true,
      baseSatietyValue: this.baseSatietyValue,
      eatMinTurns: this.eatMinTurns,
      eatMaxTurns: this.eatMaxTurns,
    };
  }
}

export function isFoodItem(item: Item): item is FoodItem {
  return item instanceof FoodItem;
}
